class ScopedZeroFileSizeLimit final {
public:
    ~ScopedZeroFileSizeLimit() {
        if (limitChanged_) {
            ::setrlimit(RLIMIT_FSIZE, &previousLimit_);
        }
        if (signalChanged_) {
            ::sigaction(SIGXFSZ, &previousAction_, nullptr);
        }
    }

    bool activate(QString *errorMessage) {
        if (::getrlimit(RLIMIT_FSIZE, &previousLimit_) != 0) {
            if (errorMessage) {
                *errorMessage = QString::fromLocal8Bit(
                    std::strerror(errno));
            }
            return false;
        }
        struct sigaction ignored {};
        ignored.sa_handler = SIG_IGN;
        ::sigemptyset(&ignored.sa_mask);
        if (::sigaction(SIGXFSZ, &ignored, &previousAction_) != 0) {
            if (errorMessage) {
                *errorMessage = QString::fromLocal8Bit(
                    std::strerror(errno));
            }
            return false;
        }
        signalChanged_ = true;
        struct rlimit limited = previousLimit_;
        limited.rlim_cur = 0;
        if (::setrlimit(RLIMIT_FSIZE, &limited) != 0) {
            if (errorMessage) {
                *errorMessage = QString::fromLocal8Bit(
                    std::strerror(errno));
            }
            return false;
        }
        limitChanged_ = true;
        return true;
    }

private:
    struct rlimit previousLimit_ {};
    struct sigaction previousAction_ {};
    bool signalChanged_ = false;
    bool limitChanged_ = false;
};

bool waitForDbusNameToDisappear(const QString &ownerUniqueName,
                                QString *errorMessage) {
    QDBusConnectionInterface *interface =
        QDBusConnection::sessionBus().interface();
    if (!interface) {
        if (errorMessage) {
            *errorMessage = QStringLiteral(
                "session bus interface is unavailable");
        }
        return false;
    }
    QElapsedTimer timer;
    timer.start();
    while (timer.elapsed() < 1000) {
        const QDBusReply<bool> registered =
            interface->isServiceRegistered(ownerUniqueName);
        if (!registered.isValid()) {
            if (errorMessage) {
                *errorMessage = registered.error().message();
            }
            return false;
        }
        if (!registered.value()) {
            return true;
        }
        QThread::msleep(1);
    }
    if (errorMessage) {
        *errorMessage = QStringLiteral(
            "D-Bus unique name remained registered");
    }
    return false;
}

