void appendTurrisVarint(QByteArray *output, quint64 value) {
    do {
        quint8 byte = static_cast<quint8>(value & 0x7fU);
        value >>= 7U;
        if (value != 0) {
            byte |= 0x80U;
        }
        output->append(static_cast<char>(byte));
    } while (value != 0);
}

void appendTurrisVarintField(QByteArray *output, quint32 field,
                             quint64 value) {
    appendTurrisVarint(output, static_cast<quint64>(field) << 3U);
    appendTurrisVarint(output, value);
}

void appendTurrisBytesField(QByteArray *output, quint32 field,
                            const QByteArray &value) {
    appendTurrisVarint(
        output, (static_cast<quint64>(field) << 3U) | 2U);
    appendTurrisVarint(output, static_cast<quint64>(value.size()));
    output->append(value);
}

QByteArray turrisMediaMetadata(quint32 mediaKind,
                               quint64 frameCount) {
    QByteArray metadata;
    appendTurrisVarintField(&metadata, 1, 0x4D584844U);
    appendTurrisBytesField(
        &metadata, 2,
        QByteArrayLiteral(
            "Tryx media header v1, fps=30, size=1280x720"));
    appendTurrisVarintField(&metadata, 3, mediaKind);
    appendTurrisVarintField(&metadata, 4, 1);
    appendTurrisVarintField(&metadata, 5, 30);
    appendTurrisVarintField(&metadata, 6, 1280);
    appendTurrisVarintField(&metadata, 7, 720);
    appendTurrisVarintField(&metadata, 8, frameCount);
    return metadata;
}

QByteArray wrapTurrisMediaBlob(const QByteArray &metadata,
                               const QByteArray &rawH264) {
    QByteArray blob;
    const quint32 metadataSize =
        static_cast<quint32>(metadata.size());
    blob.append(static_cast<char>(metadataSize & 0xffU));
    blob.append(static_cast<char>((metadataSize >> 8U) & 0xffU));
    blob.append(static_cast<char>((metadataSize >> 16U) & 0xffU));
    blob.append(static_cast<char>((metadataSize >> 24U) & 0xffU));
    blob.append(metadata);
    blob.append(rawH264);
    return blob;
}

QByteArray turrisMediaBlob(quint32 mediaKind = 4,
                           quint64 frameCount = 2) {
    const QByteArray metadata =
        turrisMediaMetadata(mediaKind, frameCount);
    return wrapTurrisMediaBlob(
        metadata, QByteArray::fromHex(
        "000000016764001facd9405005bb0110000003001000000303c0f1831960"
        "0000000168ebe3cb22c0"
        "00000001658884000affff"));
}

bool splitTurrisMediaBlob(const QByteArray &blob, QByteArray *metadata,
                          QByteArray *h264) {
    if (blob.size() < 5) {
        return false;
    }
    const quint32 metadataSize =
        static_cast<quint8>(blob.at(0)) |
        (static_cast<quint32>(static_cast<quint8>(blob.at(1))) << 8U) |
        (static_cast<quint32>(static_cast<quint8>(blob.at(2))) << 16U) |
        (static_cast<quint32>(static_cast<quint8>(blob.at(3))) << 24U);
    if (metadataSize == 0 ||
        metadataSize > static_cast<quint32>(blob.size() - 4)) {
        return false;
    }
    if (metadata) {
        *metadata = blob.mid(4, static_cast<qsizetype>(metadataSize));
    }
    if (h264) {
        *h264 = blob.mid(4 + static_cast<qsizetype>(metadataSize));
    }
    return true;
}

TryxFirmwareRecoveryRecord firmwareRecoveryRecord(
    const QString &phase = QStringLiteral("Armed"),
    QChar hashCharacter = QLatin1Char('a')) {
    const qint64 now =
        QDateTime::currentDateTimeUtc()
            .toMSecsSinceEpoch();
    TryxFirmwareRecoveryRecord record;
    record.attemptId =
        QUuid::createUuid().toString(
            QUuid::WithoutBraces);
    record.phase = phase;
    record.packageKind =
        QStringLiteral("RockchipBundle");
    record.packageSha256 =
        QString(64, hashCharacter);
    record.createdUtcMs = now;
    record.updatedUtcMs = now;
    return record;
}

bool sameFirmwareRecoveryRecord(
    const TryxFirmwareRecoveryRecord &left,
    const TryxFirmwareRecoveryRecord &right) {
    return left.attemptId == right.attemptId &&
           left.phase == right.phase &&
           left.packageKind ==
               right.packageKind &&
           left.packageSha256 ==
               right.packageSha256 &&
           left.createdUtcMs ==
               right.createdUtcMs &&
           left.updatedUtcMs ==
               right.updatedUtcMs;
}

bool createUsbDevice(const QString &sysRoot, const QString &name,
                     const QByteArray &productId) {
    const QString devicePath = QDir(sysRoot).filePath(QStringLiteral("bus/usb/devices/") + name);
    return writeTextFile(QDir(devicePath).filePath(QStringLiteral("idVendor")), "391a\n") &&
           writeTextFile(QDir(devicePath).filePath(QStringLiteral("idProduct")),
                         productId + '\n') &&
           writeTextFile(QDir(devicePath).filePath(QStringLiteral("manufacturer")), "TRYX\n") &&
           writeTextFile(QDir(devicePath).filePath(QStringLiteral("product")), "RK PASE\n") &&
           writeTextFile(QDir(devicePath).filePath(QStringLiteral("serial")),
                         name.toUtf8() + '\n');
}

bool createPrinterEndpoint(const QString &sysRoot, const QString &devRoot,
                           const QString &usbName, const QString &lpName) {
    const QString usbDevicePath =
        QDir(sysRoot).filePath(QStringLiteral("bus/usb/devices/") + usbName);
    const QString interfacePath = QDir(usbDevicePath).filePath(usbName + QStringLiteral(":1.0"));
    if (!writeTextFile(QDir(interfacePath).filePath(QStringLiteral("bInterfaceClass")), "07\n") ||
        !writeTextFile(QDir(interfacePath).filePath(QStringLiteral("bInterfaceSubClass")), "01\n") ||
        !writeTextFile(QDir(interfacePath).filePath(QStringLiteral("bInterfaceProtocol")), "02\n")) {
        return false;
    }

    const QString classPath =
        QDir(sysRoot).filePath(QStringLiteral("class/usbmisc/") + lpName);
    QDir().mkpath(classPath);
    const QString linkPath = QDir(classPath).filePath(QStringLiteral("device"));
    const QByteArray encodedTarget = QFile::encodeName(interfacePath);
    const QByteArray encodedLink = QFile::encodeName(linkPath);
    if (::symlink(encodedTarget.constData(), encodedLink.constData()) != 0) {
        return false;
    }

    const QString endpointPath = QDir(devRoot).filePath(QStringLiteral("usb/") + lpName);
    return writeTextFile(endpointPath, {});
}

bool hasUnknownField(const google::protobuf::UnknownFieldSet &fields, int number) {
    for (int index = 0; index < fields.field_count(); ++index) {
        if (fields.field(index).number() == number) {
            return true;
        }
    }
    return false;
}

