    QCOMPARE(wireDecoded.decodedSha256, expected.decodedSha256);
    QCOMPARE(wireDecoded.deviceGeneration, expected.deviceGeneration);
    QCOMPARE(wireDecoded.status, expected.status);
    QCOMPARE(wireDecoded.availableFields, expected.availableFields);
    QCOMPARE(wireDecoded.width, expected.width);
    QCOMPARE(wireDecoded.height, expected.height);
