void PrinterProtocolTests::runtimeSavedLayoutsDbusRoundTrip() {
    registerTryxRuntimeMetaTypes();

    TryxRuntimeSavedMediaRefV1 media;
    media.mediaId = QString(64, QLatin1Char('a'));
    media.name = QStringLiteral("game.h264_2240x1080");
    media.size = 4567;
    media.source = 1;
    media.readOnly = false;
    TryxRuntimeSavedLayoutV1 layout;
    layout.layoutId =
        QStringLiteral("11111111-1111-4111-8111-111111111111");
    layout.revision = 7;
    layout.deviceIdentity = QStringLiteral("PASE-SAVED-001");
    layout.productId = QStringLiteral("391a:1021");
    layout.name = QStringLiteral("Gaming");
    layout.media = {media};
    layout.request.media = {media.name};
    layout.request.ratio = QStringLiteral("2:1");
    layout.request.screenMode = QStringLiteral("Full Screen");
    layout.request.playMode = QStringLiteral("Loop");
    layout.request.settingsPosition = QStringLiteral("Top");
    layout.request.settingsColor = QStringLiteral("#112233");
    layout.request.settingsAlign = QStringLiteral("Center");
    layout.request.settingsPosition2 = QStringLiteral("Top");
    layout.request.settingsColor2 = QStringLiteral("#112233");
    layout.request.settingsAlign2 = QStringLiteral("Center");
    layout.request.replaceOverlay = true;
    layout.request.display.brightnessPresent = true;
    layout.request.display.brightness = 61;
    layout.request.display.orientationPresent = true;

    TryxRuntimeSavedLayoutsSnapshotV1 expected;
    expected.revision = 7;
    expected.status = QStringLiteral("Ready");
    expected.deviceIdentity = layout.deviceIdentity;
    expected.productId = layout.productId;
    expected.layouts = {layout};

    QDBusConnection bus = QDBusConnection::sessionBus();
    QVERIFY2(bus.isConnected(), qPrintable(bus.lastError().message()));
    RuntimeRoundTripObject serviceObject;
    const QString objectPath =
        QStringLiteral("/org/tryx/Panorama/SavedLayoutsTest/%1")
            .arg(QCoreApplication::applicationPid());
    QVERIFY2(bus.registerObject(objectPath, &serviceObject,
                                QDBusConnection::ExportAllSlots),
             qPrintable(bus.lastError().message()));
    QDBusInterface interface(bus.baseService(), objectPath,
                             QStringLiteral("org.tryx.Panorama.Test"), bus);
    const QDBusReply<TryxRuntimeSavedLayoutsSnapshotV1> reply =
        interface.call(QStringLiteral("EchoSavedLayoutsV1"),
                       QVariant::fromValue(expected));
    bus.unregisterObject(objectPath);
    QVERIFY2(reply.isValid(), qPrintable(reply.error().message()));

    const TryxRuntimeSavedLayoutsSnapshotV1 actual = reply.value();
    QCOMPARE(actual.schemaVersion, 1U);
    QCOMPARE(actual.revision, expected.revision);
    QCOMPARE(actual.status, expected.status);
    QCOMPARE(actual.diagnostic, QString());
    QCOMPARE(actual.deviceIdentity, expected.deviceIdentity);
    QCOMPARE(actual.productId, expected.productId);
    QCOMPARE(actual.layouts.size(), 1);
    const TryxRuntimeSavedLayoutV1 decoded = actual.layouts.constFirst();
    QCOMPARE(decoded.layoutId, layout.layoutId);
    QCOMPARE(decoded.revision, layout.revision);
    QCOMPARE(decoded.name, layout.name);
    QCOMPARE(decoded.media.size(), 1);
    QCOMPARE(decoded.media.constFirst().mediaId, media.mediaId);
    QCOMPARE(decoded.media.constFirst().name, media.name);
    QCOMPARE(decoded.media.constFirst().size, media.size);
    QCOMPARE(decoded.request.media, layout.request.media);
    QCOMPARE(decoded.request.display.brightness, 61);
}

void PrinterProtocolTests::
    savedLayoutsSnapshotRejectsNonCanonicalDeviceIdentity_data() {
    QTest::addColumn<QString>("deviceIdentity");

    QTest::newRow("leading-whitespace") << QStringLiteral(" 1-1");
    QTest::newRow("trailing-whitespace") << QStringLiteral("1-1 ");
    QTest::newRow("control") << QStringLiteral("1-\n1");
    QTest::newRow("bidi-override") << QStringLiteral("1-\u202E1");
    QTest::newRow("bidi-isolate") << QStringLiteral("1-\u20661");
    QTest::newRow("legacy-prefix") << QStringLiteral("legacy:1-1");
    QTest::newRow("overlong-257")
        << QString(257, QLatin1Char('a'));
}

void PrinterProtocolTests::
    savedLayoutsSnapshotRejectsNonCanonicalDeviceIdentity() {
    QFETCH(QString, deviceIdentity);
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString sysRoot = QDir(temporaryDirectory.path()).filePath(
        QStringLiteral("sys"));
    const QString devRoot = QDir(temporaryDirectory.path()).filePath(
        QStringLiteral("dev"));
    QVERIFY(createUsbDevice(sysRoot, QStringLiteral("1-1"), "1021"));
    QVERIFY(createPrinterEndpoint(
        sysRoot, devRoot, QStringLiteral("1-1"),
        QStringLiteral("lp0")));

    std::unique_ptr<DeviceManager> manager(
        DeviceManager::createForTesting(sysRoot, devRoot));

    QObject::disconnect(
        manager.get(), &DeviceManager::requestPrinterApplyMedia,
        manager->worker_, &DeviceWorker::applyPrinterMedia);
    QObject::disconnect(
        manager.get(),
        &DeviceManager::requestBeginPrinterForegroundOperation,
        manager->worker_, &DeviceWorker::beginPrinterForegroundOperation);
    manager->setAutoConnectModeForTesting(true);
    manager->rescanPrinterForTesting();
    QVERIFY(manager->isPrinterClassConnected());
    manager->sessionController_.state_.printerDisplaySessionActive = true;
    manager->sessionController_.state_.printerDeviceSerial = deviceIdentity;

    const TryxRuntimeSavedLayoutsSnapshotV1 snapshot =
        manager->savedLayoutsSnapshot();
    QCOMPARE(snapshot.status, QStringLiteral("Unavailable"));
    QCOMPARE(snapshot.deviceIdentity, deviceIdentity);
    QVERIFY(!snapshot.diagnostic.isEmpty());
    QVERIFY(snapshot.layouts.isEmpty());

    QString exactIdentity = QStringLiteral("sentinel");
    QString exactProduct = QStringLiteral("sentinel");
    QVERIFY(!manager->currentSavedLayoutsContext(
        &exactIdentity, &exactProduct));
    QVERIFY(exactIdentity.isEmpty());
    QVERIFY(exactProduct.isEmpty());

    QSignalSpy foregroundSpy(
        manager.get(),
        &DeviceManager::requestBeginPrinterForegroundOperation);
    QSignalSpy workerSpy(
        manager.get(), &DeviceManager::requestPrinterApplyMedia);
    TryxRuntimeSavedLayoutsSnapshotV1 confirmed;
    QString errorName;
    QString errorMessage;
    TryxRuntimeSavedLayoutV1 candidate;
    candidate.deviceIdentity = deviceIdentity;
    candidate.productId = QStringLiteral("391a:1021");
    candidate.name = QStringLiteral("Rejected");
    QVERIFY(!manager->putSavedLayout(
        snapshot.revision, candidate, &confirmed,
        &errorName, &errorMessage));
    QCOMPARE(errorName, QStringLiteral(
        "org.tryx.Panorama.Error.SavedLayoutsUnavailable"));
    QVERIFY(!manager->deleteSavedLayout(
        snapshot.revision,
        QStringLiteral("aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"),
        &confirmed, &errorName, &errorMessage));
    QCOMPARE(errorName, QStringLiteral(
        "org.tryx.Panorama.Error.SavedLayoutsUnavailable"));

    const QString operationId =
        QStringLiteral("93939393-9393-4393-8393-939393939393");
    QCOMPARE(manager->queueSavedLayoutApplyOperation(
                 operationId,
                 QStringLiteral(
                     "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"),
                 1, {}),
             operationId);
    const TryxRuntimeOperationInfo info =
        manager->operationInfo(operationId);
    QCOMPARE(info.state, QStringLiteral("Failed"));
    QCOMPARE(info.stage, QStringLiteral("Rejected"));
    QCOMPARE(info.errorCategory,
             QStringLiteral("SavedLayoutsUnavailable"));
    QCOMPARE(foregroundSpy.count(), 0);
    QCOMPARE(workerSpy.count(), 0);
}

void PrinterProtocolTests::savedLayoutsCrudIsDeviceScopedAndDispatchFree() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString sysRoot =
        QDir(temporaryDirectory.path()).filePath(QStringLiteral("sys"));
    const QString devRoot =
        QDir(temporaryDirectory.path()).filePath(QStringLiteral("dev"));
    QVERIFY(createUsbDevice(sysRoot, QStringLiteral("1-1"), "1021"));
    QVERIFY(createPrinterEndpoint(
        sysRoot, devRoot, QStringLiteral("1-1"),
        QStringLiteral("lp0")));

    std::unique_ptr<DeviceManager> manager(
        DeviceManager::createForTesting(sysRoot, devRoot));
    QObject::disconnect(
        manager.get(), &DeviceManager::requestPrinterApplyMedia,
        manager->worker_, &DeviceWorker::applyPrinterMedia);
    QObject::disconnect(
        manager.get(),
        &DeviceManager::requestBeginPrinterForegroundOperation,
        manager->worker_, &DeviceWorker::beginPrinterForegroundOperation);
    manager->setAutoConnectModeForTesting(true);
    manager->rescanPrinterForTesting();
    QVERIFY(manager->isPrinterClassConnected());
    manager->sessionController_.state_.printerDisplaySessionActive = true;

    PrinterProtocol::MediaFile media;
    media.name = QStringLiteral("layout.mp4.h264_2240x1080");
    media.size = 4096;
    media.source = PrinterProtocol::MediaSource::User;
    manager->updateMediaCatalog({media});

    QSignalSpy foregroundSpy(
        manager.get(),
        &DeviceManager::requestBeginPrinterForegroundOperation);
    QSignalSpy workerSpy(
        manager.get(), &DeviceManager::requestPrinterApplyMedia);

    const TryxRuntimeSavedLayoutsSnapshotV1 empty =
        manager->savedLayoutsSnapshot();
    QCOMPARE(empty.status, QStringLiteral("Ready"));
    QCOMPARE(empty.revision, quint64{0});
    QCOMPARE(empty.deviceIdentity, QStringLiteral("1-1"));
    QCOMPARE(empty.productId, QStringLiteral("391a:1021"));
    QVERIFY(empty.layouts.isEmpty());

    TryxRuntimeSavedLayoutV1 create = savedLayoutForTesting(
        manager.get(), QStringLiteral("Gaming"));
    QVERIFY(create.layoutId.isEmpty());
    QCOMPARE(create.revision, quint64{0});
    TryxRuntimeSavedLayoutsSnapshotV1 confirmed;
    QString errorName;
    QString errorMessage;
    QVERIFY2(manager->putSavedLayout(
                 empty.revision, create, &confirmed,
                 &errorName, &errorMessage),
             qPrintable(errorMessage));
    QVERIFY(errorName.isEmpty());
    QCOMPARE(confirmed.status, QStringLiteral("Ready"));
    QCOMPARE(confirmed.revision, quint64{1});
    QCOMPARE(confirmed.layouts.size(), 1);
    const TryxRuntimeSavedLayoutV1 created =
        confirmed.layouts.constFirst();
    QCOMPARE(created.revision, confirmed.revision);
    QCOMPARE(
        QUuid(created.layoutId).toString(QUuid::WithoutBraces),
        created.layoutId);
    QVERIFY(!QUuid(created.layoutId).isNull());

    TryxRuntimeSavedLayoutV1 staleCreate = savedLayoutForTesting(
        manager.get(), QStringLiteral("Work"));
    QVERIFY(!manager->putSavedLayout(
        0, staleCreate, &confirmed, &errorName, &errorMessage));
    QCOMPARE(
        errorName,
        QStringLiteral(
            "org.tryx.Panorama.Error.SavedLayoutsRevisionConflict"));
    QCOMPARE(confirmed.revision, quint64{1});

    TryxRuntimeSavedLayoutV1 duplicate = savedLayoutForTesting(
        manager.get(), QStringLiteral("gAmInG"));
    QVERIFY(!manager->putSavedLayout(
        1, duplicate, &confirmed, &errorName, &errorMessage));
    QCOMPARE(
        errorName,
        QStringLiteral(
            "org.tryx.Panorama.Error.SavedLayoutNameConflict"));
    QCOMPARE(confirmed.revision, quint64{1});

    TryxRuntimeSavedLayoutV1 wrongDevice =
        savedLayoutForTesting(manager.get(), QStringLiteral("Foreign"));
    wrongDevice.deviceIdentity = QStringLiteral("other-device");
    QVERIFY(!manager->putSavedLayout(
        1, wrongDevice, &confirmed, &errorName, &errorMessage));
    QCOMPARE(
        errorName,
        QStringLiteral(
            "org.tryx.Panorama.Error.InvalidSavedLayout"));
    QCOMPARE(confirmed.revision, quint64{1});

    manager->sessionController_.state_.printerProductId = 0x2011;
    QVERIFY(!manager->putSavedLayout(
        1, staleCreate, &confirmed, &errorName, &errorMessage));
    QCOMPARE(
        errorName,
        QStringLiteral(
            "org.tryx.Panorama.Error.UnsupportedProduct"));
    manager->sessionController_.state_.printerProductId = 0x1021;

    manager->sessionController_.state_.connected = false;
    QVERIFY(!manager->putSavedLayout(
        1, staleCreate, &confirmed, &errorName, &errorMessage));
    QCOMPARE(
        errorName,
        QStringLiteral(
            "org.tryx.Panorama.Error.SavedLayoutsUnavailable"));
    manager->sessionController_.state_.connected = true;

    TryxRuntimeSavedLayoutV1 update = created;
    update.request.display.brightness = 73;
    QVERIFY2(manager->putSavedLayout(
                 1, update, &confirmed, &errorName, &errorMessage),
             qPrintable(errorMessage));
    QCOMPARE(confirmed.revision, quint64{2});
    QCOMPARE(confirmed.layouts.size(), 1);
    const TryxRuntimeSavedLayoutV1 updated =
        confirmed.layouts.constFirst();
    QCOMPARE(updated.layoutId, created.layoutId);
    QCOMPARE(updated.revision, quint64{2});
    QCOMPARE(updated.request.display.brightness, 73);

    manager->sessionController_.state_.connected = false;
    const TryxRuntimeSavedLayoutsSnapshotV1 disconnected =
        manager->savedLayoutsSnapshot();
    QCOMPARE(disconnected.status, QStringLiteral("Disconnected"));
    QCOMPARE(disconnected.revision, quint64{2});
    manager->sessionController_.state_.connected = true;

    manager->sessionController_.state_.printerProductId = 0x2011;
    const TryxRuntimeSavedLayoutsSnapshotV1 unsupported =
        manager->savedLayoutsSnapshot();
    QCOMPARE(unsupported.status, QStringLiteral("Unsupported"));
    QCOMPARE(unsupported.revision, quint64{2});
    manager->sessionController_.state_.printerProductId = 0x1021;

    manager->savedLayoutsStoreLoaded_ = false;
    const TryxRuntimeSavedLayoutsSnapshotV1 unavailable =
        manager->savedLayoutsSnapshot();
    QCOMPARE(unavailable.status, QStringLiteral("Unavailable"));
    QCOMPARE(unavailable.revision, quint64{2});
    manager->savedLayoutsStoreLoaded_ = true;

    manager->sessionController_.state_.printerDeviceSerial = QStringLiteral("other-device");
    const TryxRuntimeSavedLayoutsSnapshotV1 otherDevice =
        manager->savedLayoutsSnapshot();
    QCOMPARE(otherDevice.status, QStringLiteral("Ready"));
    QCOMPARE(otherDevice.revision, quint64{2});
    QVERIFY(otherDevice.layouts.isEmpty());
    QVERIFY(!manager->deleteSavedLayout(
        2, updated.layoutId, &confirmed, &errorName, &errorMessage));
    QCOMPARE(
        errorName,
        QStringLiteral(
            "org.tryx.Panorama.Error.InvalidSavedLayout"));

    manager->sessionController_.state_.printerDeviceSerial = QStringLiteral("bad\u202Edevice");
    const TryxRuntimeSavedLayoutsSnapshotV1 invalidIdentity =
        manager->savedLayoutsSnapshot();
    QCOMPARE(invalidIdentity.status, QStringLiteral("Unavailable"));
    QCOMPARE(invalidIdentity.revision, quint64{2});
    QVERIFY(!invalidIdentity.diagnostic.isEmpty());
    QVERIFY(invalidIdentity.layouts.isEmpty());

    manager->sessionController_.state_.printerDeviceSerial = QStringLiteral("1-1");
    QCOMPARE(manager->savedLayoutsSnapshot().layouts.size(), 1);
    QVERIFY(!manager->deleteSavedLayout(
        1, updated.layoutId, &confirmed, &errorName, &errorMessage));
    QCOMPARE(
        errorName,
        QStringLiteral(
            "org.tryx.Panorama.Error.SavedLayoutsRevisionConflict"));
    QVERIFY2(manager->deleteSavedLayout(
                 2, updated.layoutId, &confirmed,
                 &errorName, &errorMessage),
             qPrintable(errorMessage));
    QCOMPARE(confirmed.revision, quint64{3});
    QVERIFY(confirmed.layouts.isEmpty());
    QCOMPARE(foregroundSpy.count(), 0);
    QCOMPARE(workerSpy.count(), 0);
}

void PrinterProtocolTests::
    savedLayoutDowngradeLatchBlocksCrudWithoutDispatch() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString sysRoot =
        QDir(temporaryDirectory.path()).filePath(QStringLiteral("sys"));
    const QString devRoot =
        QDir(temporaryDirectory.path()).filePath(QStringLiteral("dev"));
    QVERIFY(createUsbDevice(sysRoot, QStringLiteral("1-1"), "1021"));
    QVERIFY(createPrinterEndpoint(
        sysRoot, devRoot, QStringLiteral("1-1"),
        QStringLiteral("lp0")));

    std::unique_ptr<DeviceManager> manager(
        DeviceManager::createForTesting(sysRoot, devRoot));
    QObject::disconnect(
        manager.get(), &DeviceManager::requestPrinterApplyMedia,
        manager->worker_, &DeviceWorker::applyPrinterMedia);
    QObject::disconnect(
        manager.get(),
        &DeviceManager::requestBeginPrinterForegroundOperation,
        manager->worker_, &DeviceWorker::beginPrinterForegroundOperation);
    manager->setAutoConnectModeForTesting(true);
    manager->rescanPrinterForTesting();
    manager->sessionController_.state_.printerDisplaySessionActive = true;
    PrinterProtocol::MediaFile media;
    media.name = QStringLiteral("layout.mp4.h264_2240x1080");
    media.size = 4096;
    media.source = PrinterProtocol::MediaSource::User;
    manager->updateMediaCatalog({media});

    TryxRuntimeSavedLayoutsSnapshotV1 confirmed;
    QString errorName;
    QString errorMessage;
    QVERIFY2(manager->putSavedLayout(
                 0,
                 savedLayoutForTesting(
                     manager.get(), QStringLiteral("Gaming")),
                 &confirmed, &errorName, &errorMessage),
             qPrintable(errorMessage));
    const TryxRuntimeSavedLayoutV1 created =
        confirmed.layouts.constFirst();
    manager->runtimeDowngradeV10Prepared_ = true;

    QSignalSpy foregroundSpy(
        manager.get(),
        &DeviceManager::requestBeginPrinterForegroundOperation);
    QSignalSpy workerSpy(
        manager.get(), &DeviceManager::requestPrinterApplyMedia);
    QVERIFY(!manager->putSavedLayout(
        1,
        savedLayoutForTesting(manager.get(), QStringLiteral("Blocked")),
        &confirmed, &errorName, &errorMessage));
    QCOMPARE(
        errorName,
        QStringLiteral(
            "org.tryx.Panorama.Error.DowngradePrepared"));
    QVERIFY(!manager->deleteSavedLayout(
        1, created.layoutId, &confirmed, &errorName, &errorMessage));
    QCOMPARE(
        errorName,
        QStringLiteral(
            "org.tryx.Panorama.Error.DowngradePrepared"));
    QCOMPARE(manager->savedLayoutsSnapshot().revision, quint64{1});
    QCOMPARE(manager->savedLayoutsSnapshot().layouts.size(), 1);
    QCOMPARE(foregroundSpy.count(), 0);
    QCOMPARE(workerSpy.count(), 0);
}

