void PrinterProtocolTests::
    runtimeApplyRequestCodecRoundTripsAndPreservesV8Defaults() {
    namespace codec = tryx::runtime_apply_request_codec;

    TryxRuntimeApplyRequest expected;
    expected.media = {QStringLiteral("left.mp4.h264_2240x1080")};
    expected.ratio = QStringLiteral("2:1");
    expected.screenMode = QStringLiteral("Screen Splitting");
    expected.playMode = QStringLiteral("Loop");
    expected.sysinfoLabels = {QStringLiteral("CPU Temperature")};
    expected.settingsPosition = QStringLiteral("Top");
    expected.settingsColor = QStringLiteral("#112233");
    expected.settingsAlign = QStringLiteral("Left");
    expected.settingsBadges = {QStringLiteral("CPU Badge")};
    expected.filterOpacity = 42;
    expected.presetId = QStringLiteral("preset");
    expected.sysinfoLabels2 = {QStringLiteral("GPU Usage")};
    expected.settingsBadges2 = {QStringLiteral("GPU Badge")};
    expected.settingsPosition2 = QStringLiteral("Bottom");
    expected.settingsColor2 = QStringLiteral("#abcdef");
    expected.settingsAlign2 = QStringLiteral("Right");
    expected.waterfallMode = true;
    expected.replaceOverlay = true;
    expected.display.brightnessPresent = true;
    expected.display.brightness = 73;
    expected.display.standbyPresent = true;
    expected.display.standbyEnabled = false;
    expected.display.backlightPresent = true;
    expected.display.backlightEnabled = false;
    expected.display.orientationPresent = true;
    expected.display.mirrorMode = true;
    expected.display.waterfallMode = false;

    const QJsonObject encoded = codec::runtimeApplyRequestToJson(expected);
    QJsonParseError expectedJsonError;
    const QJsonDocument expectedDocument = QJsonDocument::fromJson(
        QByteArrayLiteral(R"json(
            {
              "media": ["left.mp4.h264_2240x1080"],
              "ratio": "2:1",
              "screenMode": "Screen Splitting",
              "playMode": "Loop",
              "sysinfoLabels": ["CPU Temperature"],
              "settingsPosition": "Top",
              "settingsColor": "#112233",
              "settingsAlign": "Left",
              "settingsBadges": ["CPU Badge"],
              "filterOpacity": 42,
              "presetId": "preset",
              "sysinfoLabels2": ["GPU Usage"],
              "settingsBadges2": ["GPU Badge"],
              "settingsPosition2": "Bottom",
              "settingsColor2": "#abcdef",
              "settingsAlign2": "Right",
              "waterfallMode": true,
              "replaceOverlay": true,
              "display": {
                "brightnessPresent": true,
                "brightness": 73,
                "standbyPresent": true,
                "standbyEnabled": false,
                "backlightPresent": true,
                "backlightEnabled": false,
                "orientationPresent": true,
                "mirrorMode": true,
                "waterfallMode": false
              }
            }
        )json"),
        &expectedJsonError);
    QCOMPARE(expectedJsonError.error, QJsonParseError::NoError);
    QCOMPARE(encoded, expectedDocument.object());
    QCOMPARE(
        codec::runtimeApplyRequestFingerprint(expected),
        QStringLiteral(
            "4c98b435a6449031176d54c9754b82570925f17d94ece2a74cdbb6d270ef9b51"));
    TryxRuntimeApplyRequest parsed;
    QVERIFY(codec::runtimeApplyRequestFromJson(
        encoded, &parsed, true));
    QVERIFY(codec::runtimeApplyRequestToJson(parsed) == encoded);
    QCOMPARE(codec::runtimeApplyRequestFingerprint(parsed),
             codec::runtimeApplyRequestFingerprint(expected));
    QCOMPARE(codec::runtimeApplyRequestFingerprint(expected).size(), 64);

    QJsonObject legacy = encoded;
    QJsonObject legacyDisplay =
        legacy.value(QStringLiteral("display")).toObject();
    legacyDisplay.remove(QStringLiteral("backlightPresent"));
    legacyDisplay.remove(QStringLiteral("backlightEnabled"));
    legacy.insert(QStringLiteral("display"), legacyDisplay);
    legacy.insert(QStringLiteral("settingsColor"), QString());
    legacy.insert(QStringLiteral("settingsColor2"), QString());
    TryxRuntimeApplyRequest parsedLegacy;
    QVERIFY(codec::runtimeApplyRequestFromJson(
        legacy, &parsedLegacy, false));
    QVERIFY(!parsedLegacy.display.backlightPresent);
    QVERIFY(parsedLegacy.display.backlightEnabled);
    QCOMPARE(parsedLegacy.settingsColor, QStringLiteral("#dcdcdc"));
    QCOMPARE(parsedLegacy.settingsColor2, parsedLegacy.settingsColor);
    QVERIFY(!codec::runtimeApplyRequestFromJson(
        legacy, &parsedLegacy, true));

    QJsonObject malformed = encoded;
    malformed.insert(QStringLiteral("media"), QJsonArray{17});
    QVERIFY(!codec::runtimeApplyRequestFromJson(
        malformed, &parsed, true));

    TryxRuntimeMediaTransform transform = tryxLegacyFitMediaTransform();
    const QString transformFingerprint =
        codec::runtimeMediaTransformRequestFingerprint(transform);
    QCOMPARE(
        transformFingerprint,
        QStringLiteral(
            "7577239a0064871dee191658e5907f65fb4cb6ca62b2025a9a611f2a97e02cee"));
    transform.rotationQuarterTurns = 1;
    QVERIFY(codec::runtimeMediaTransformRequestFingerprint(transform) !=
            transformFingerprint);
}

void PrinterProtocolTests::mediaTransformValidationAndFilters() {
    const TryxRuntimeMediaTransform legacy = tryxLegacyFitMediaTransform();
    QVERIFY(tryxMediaTransformIsValid(legacy));
    QVERIFY(tryxMediaTransformIsLegacyFit(legacy));
    const QString legacyFingerprint =
        tryxMediaTransformFingerprint(legacy);
    QCOMPARE(legacyFingerprint.size(), 64);
    const QString legacyFilter =
        tryxMediaTransformFfmpegFilter(legacy);
    QVERIFY(!legacyFilter.startsWith(QStringLiteral("transpose=")));
    QVERIFY(!legacyFilter.startsWith(QStringLiteral("hflip,")));
    QVERIFY(legacyFilter.startsWith(
        QStringLiteral(
            "scale='if(lte(sar,0),iw,max(1,round(iw*sar)))':ih,"
            "setsar=1,")));
    QVERIFY(legacyFilter.contains(
        QStringLiteral(
            "scale=2240:1080:force_original_aspect_ratio=decrease")));
    QVERIFY(legacyFilter.contains(
        QStringLiteral(
            "pad=2240:1080:(ow-iw)/2:(oh-ih)/2:color=0x000000")));
    QVERIFY(legacyFilter.endsWith(
        QStringLiteral("setsar=1,format=yuv420p,fps=30")));

    TryxRuntimeMediaTransform fit = legacy;
    fit.backgroundRgb = 0x123ABC;
    fit.rotationQuarterTurns = 1;
    QVERIFY(tryxMediaTransformIsValid(fit));
    const QString fitFilter = tryxMediaTransformFfmpegFilter(fit);
    QVERIFY(fitFilter.startsWith(QStringLiteral("transpose=clock,")));
    QVERIFY(fitFilter.contains(QStringLiteral("color=0x123abc")));
    QVERIFY(tryxMediaTransformFingerprint(fit) != legacyFingerprint);

    fit.rotationQuarterTurns = 3;
    QVERIFY(tryxMediaTransformFfmpegFilter(fit).startsWith(
        QStringLiteral("transpose=cclock,")));

    TryxRuntimeMediaTransform fill = legacy;
    fill.mode = QStringLiteral("Fill");
    QVERIFY(tryxMediaTransformIsValid(fill));
    const QString fillFilter = tryxMediaTransformFfmpegFilter(fill);
    QVERIFY(fillFilter.contains(
        QStringLiteral(
            "scale=2240:1080:force_original_aspect_ratio=increase:"
            "force_divisible_by=2")));
    QVERIFY(fillFilter.contains(
        QStringLiteral(
            "crop=2240:1080:"
            "'trunc((iw-2240)*5000/10000/2)*2':"
            "'trunc((ih-1080)*5000/10000/2)*2'")));
    QVERIFY(!fillFilter.contains(QStringLiteral("pad=")));

    TryxRuntimeMediaTransform neutralCrop = legacy;
    neutralCrop.mode = QStringLiteral("Crop");
    QCOMPARE(
        tryxMediaTransformFfmpegFilter(neutralCrop),
        fillFilter);

    TryxRuntimeMediaTransform crop = legacy;
    crop.mode = QStringLiteral("Crop");
    crop.rotationQuarterTurns = 2;
    crop.zoomPermille = 2500;
    crop.focusX = 2500;
    crop.focusY = 7500;
    QVERIFY(tryxMediaTransformIsValid(crop));
    const QString cropFilter = tryxMediaTransformFfmpegFilter(crop);
    QVERIFY(cropFilter.startsWith(QStringLiteral("hflip,vflip,")));
    QVERIFY(cropFilter.contains(QStringLiteral("iw*2500/1000")));
    QVERIFY(cropFilter.contains(QStringLiteral("(iw-2240)*2500/10000")));
    QVERIFY(cropFilter.contains(QStringLiteral("(ih-1080)*7500/10000")));

    TryxRuntimeMediaTransform stretch = legacy;
    stretch.mode = QStringLiteral("Stretch");
    QVERIFY(tryxMediaTransformIsValid(stretch));
    QCOMPARE(
        tryxMediaTransformFfmpegFilter(stretch),
        QStringLiteral(
            "scale='if(lte(sar,0),iw,max(1,round(iw*sar)))':ih,"
            "setsar=1,scale=2240:1080,"
            "setsar=1,format=yuv420p,fps=30"));

    TryxRuntimeMediaTransform invalid = crop;
    invalid.schemaVersion = 2;
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    QVERIFY(tryxMediaTransformFingerprint(invalid).isEmpty());
    QVERIFY(tryxMediaTransformFfmpegFilter(invalid).isEmpty());

    invalid = fill;
    invalid.mode = QStringLiteral("Unknown");
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    invalid = crop;
    invalid.zoomPermille = 999;
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    invalid.zoomPermille = 4001;
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    invalid = fill;
    invalid.zoomPermille = 1001;
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    invalid = crop;
    invalid.focusX = 10001;
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    invalid = crop;
    invalid.focusY = 10001;
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    invalid = stretch;
    invalid.backgroundRgb = 1;
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    invalid = legacy;
    invalid.backgroundRgb = 0x01000000;
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    invalid = legacy;
    invalid.rotationQuarterTurns = 4;
    QVERIFY(!tryxMediaTransformIsValid(invalid));
    QVERIFY(tryxMediaTransformFfmpegFilter(legacy, 2239, 1080).isEmpty());
}

void PrinterProtocolTests::mediaTransformChangesConversionProfile() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString sourcePath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("profile-source.png"));
    QVERIFY(writeTextFile(sourcePath, QByteArray("profile-source")));

    PrinterMediaPreparer preparer;
    QSignalSpy analyzedSpy(&preparer,
                           &PrinterMediaPreparer::sourceAnalyzed);
    const TryxRuntimeMediaTransform legacy =
        tryxLegacyFitMediaTransform();
    preparer.analyzeSource(
        QStringLiteral("21212121-2121-4121-8121-212121212121"),
        sourcePath, 1, legacy);
    QCOMPARE(analyzedSpy.count(), 1);
    const QString legacyProfile =
        analyzedSpy.first().at(4).toString();
    QCOMPARE(
        legacyProfile,
        QStringLiteral(
            "pase-h264-v1-image-60s-2240x1080-yuv420p-30fps-libx264-veryfast-crf23"));

    TryxRuntimeMediaTransform crop = legacy;
    crop.mode = QStringLiteral("Crop");
    crop.zoomPermille = 1750;
    crop.focusX = 2500;
    crop.focusY = 7500;
    preparer.analyzeSource(
        QStringLiteral("23232323-2323-4323-8323-232323232323"),
        sourcePath, 1, crop);
    QCOMPARE(analyzedSpy.count(), 2);
    const QString cropProfile =
        analyzedSpy.at(1).at(4).toString();
    QVERIFY(cropProfile.startsWith(
        QStringLiteral(
            "pase-h264-v2-image-60s-2240x1080-yuv420p-30fps-libx264-veryfast-crf23-transform-")));
    QVERIFY(cropProfile.endsWith(
        tryxMediaTransformFingerprint(crop)));
    QVERIFY(cropProfile != legacyProfile);
    QVERIFY(cropProfile.size() <= 256);

    TryxRuntimeMediaPreparationProfileV1 splitProfile;
    splitProfile.target = QStringLiteral("SplitArea");
    splitProfile.transform = crop;
    preparer.analyzeSourceWithPreparationProfile(
        QStringLiteral("24242424-2424-4424-8424-242424242424"),
        sourcePath, 1, splitProfile, 0x1021);
    QCOMPARE(analyzedSpy.count(), 3);
    const QString splitConversionProfile =
        analyzedSpy.at(2).at(4).toString();
    QVERIFY(splitConversionProfile.startsWith(
        QStringLiteral(
            "pase-h264-v3-image-60s-split-area-1120x1080-yuv420p-30fps-libx264-veryfast-crf23-transform-")));
    QVERIFY(splitConversionProfile.endsWith(
        tryxMediaTransformFingerprint(crop)));
    QVERIFY(splitConversionProfile != cropProfile);

    const auto pase = printerProductProfileForId(0x1021);
    QVERIFY(pase.has_value());
    const QString splitConversion =
        tryx::printer_media_identity::printerMediaConversionIdentity(
            *pase, splitProfile);
    QCOMPARE(splitConversion,
             QStringLiteral("h264-yuv420p-1120x1080-30fps"));
    QCOMPARE(
        tryx::printer_media_identity::h264PrinterName(
            QStringLiteral("source.mp4"), 0x1021, splitProfile),
        QStringLiteral("source.mp4.h264_1120x1080"));
    QVERIFY(tryx::printer_media_identity::printerMediaNameMatchesConversion(
        QStringLiteral("source.mp4.h264_1120x1080"),
        *pase, splitConversion));
    QVERIFY(!tryx::printer_media_identity::printerMediaNameMatchesConversion(
        QStringLiteral("source.mp4.h264_2240x1080"),
        *pase, splitConversion));
    QVERIFY(tryx::printer_media_identity::
        printerConversionProfileMatchesConversion(
            splitConversionProfile, *pase, splitConversion));
    QVERIFY(!tryx::printer_media_identity::
        printerConversionProfileMatchesConversion(
            cropProfile, *pase, splitConversion));
    QVERIFY(tryx::printer_media_identity::printerConversionProfile(
        sourcePath, splitProfile, 0x2011).isEmpty());

    const QString splitFilter = tryxMediaTransformFfmpegFilter(
        splitProfile.transform,
        tryxMediaPreparationTargetWidth(splitProfile),
        tryxMediaPreparationTargetHeight(splitProfile));
    QVERIFY(splitFilter.contains(
        QStringLiteral("crop=1120:1080:")));
    QVERIFY(!splitFilter.contains(
        QStringLiteral("scale=2240:1080")));
}

void PrinterProtocolTests::productProfilesExposeExactCapabilities() {
    const auto pase = printerProductProfileForId(0x1021);
    const auto pano = printerProductProfileForId(0x1011);
    const auto turris = printerProductProfileForId(0x2011);
    QVERIFY(pase.has_value());
    QVERIFY(pano.has_value());
    QVERIFY(turris.has_value());
    QVERIFY(!printerProductProfileForId(0x9999).has_value());

    QCOMPARE(pase->mediaWidth, 2240);
    QCOMPARE(pase->mediaHeight, 1080);
    QCOMPARE(pase->idleMode, PrinterIdleMode::OverlayLayout);
    QVERIFY(pase->mediaUploadSupported);
    QVERIFY(pase->mediaCatalogSupported);
    QVERIFY(pase->displayConfigurationSupported);
    QVERIFY(pase->splitAreaMediaSupported);
    QVERIFY(pase->overlayMetricsSupported);
    QVERIFY(pase->firmwareFlashSupported);

    QCOMPARE(pano->mediaWidth, 2240);
    QCOMPARE(pano->mediaHeight, 1080);
    QCOMPARE(pano->idleMode, PrinterIdleMode::OverlayLayout);
    QVERIFY(pano->mediaUploadSupported);
    QVERIFY(pano->mediaCatalogSupported);
    QVERIFY(pano->displayConfigurationSupported);
    QVERIFY(pano->splitAreaMediaSupported);
    QVERIFY(pano->overlayMetricsSupported);
    QVERIFY(!pano->firmwareFlashSupported);

    QCOMPARE(turris->mediaWidth, 1280);
    QCOMPARE(turris->mediaHeight, 720);
    QCOMPARE(turris->idleMode, PrinterIdleMode::TransferOnly);
    QVERIFY(turris->mediaUploadSupported);
    QVERIFY(!turris->mediaCatalogSupported);
    QVERIFY(!turris->displayConfigurationSupported);
    QVERIFY(!turris->splitAreaMediaSupported);
    QVERIFY(!turris->overlayMetricsSupported);
    QVERIFY(!turris->firmwareFlashSupported);

    PrinterProtocol turrisProtocol(*turris, 100);
    const PrinterProtocol::MediaListResult mediaList =
        turrisProtocol.readMediaList(QStringLiteral("unused"), {});
    QVERIFY(!mediaList.success);
    QVERIFY(mediaList.error.contains(QStringLiteral("391a:2011")));
    const PrinterProtocol::DeleteResult deleteResult =
        turrisProtocol.removeUserMedia(
            QStringLiteral("unused"),
            {QStringLiteral("turris.mp4.h264_1280x720")},
            PrinterProtocol::BeforeDeleteDispatch{},
            PrinterProtocol::DeleteProgress{},
            PrinterProtocol::OperationContext{});
    QVERIFY(!deleteResult.success);
    QCOMPARE(deleteResult.outcome,
             PrinterProtocol::MutationOutcome::Rejected);

    const PrinterProtocol::PaseDisplayStateResult displayState =
        turrisProtocol.readPaseDisplayState(
            QStringLiteral("unused"), {});
    QVERIFY(!displayState.success);
    QVERIFY(displayState.error.contains(QStringLiteral("391a:2011")));
    PrinterProtocol::PaseApplyConfig applyConfig;
    applyConfig.mediaPresent = true;
    applyConfig.media = {
        QStringLiteral("turris.mp4.h264_1280x720")};
    PrinterProtocol::MutationDetails mutation;
    QString error;
    QVERIFY(!turrisProtocol.applyPaseConfiguration(
        QStringLiteral("unused"), applyConfig, &error, {}, &mutation));
    QCOMPARE(mutation.outcome,
             PrinterProtocol::MutationOutcome::Rejected);
    QVERIFY(error.contains(QStringLiteral("391a:2011")));
    error.clear();
    mutation = {};
    QVERIFY(!turrisProtocol.configurePaseOverlay(
        QStringLiteral("unused"), PrinterProtocol::PaseOverlayConfig{},
        &error, {}, &mutation));
    QCOMPARE(mutation.outcome,
             PrinterProtocol::MutationOutcome::Rejected);
    QVERIFY(error.contains(QStringLiteral("391a:2011")));
}

