void PrinterProtocolTests::turrisMediaFormatFrameCountParserIsStrict() {
    namespace turris = tryx::turris_media;

    const turris::FrameCountProbeResult video =
        turris::parseFrameCountProbe(
            QByteArrayLiteral(
                "width=1280\r\nheight=720\r\nnb_read_frames=2\r\n"),
            turris::kVideoKind);
    QVERIFY(video.valid);
    QCOMPARE(video.frameCount, quint64{2});

    const turris::FrameCountProbeResult image =
        turris::parseFrameCountProbe(
            QByteArrayLiteral(
                "nb_read_frames=1\nheight=720\nwidth=1280\n"),
            turris::kImageKind);
    QVERIFY(image.valid);
    QCOMPARE(image.frameCount, quint64{1});

    const turris::FrameCountProbeResult maximumVideo =
        turris::parseFrameCountProbe(
            QByteArrayLiteral(
                "width=1280\nheight=720\nnb_read_frames=4294967295\n"),
            turris::kVideoKind);
    QVERIFY(maximumVideo.valid);
    QCOMPARE(maximumVideo.frameCount, quint64{4294967295ULL});

    const QList<QByteArray> malformed{
        QByteArrayLiteral(
            "width=1280\nwidth=1280\nheight=720\nnb_read_frames=2\n"),
        QByteArrayLiteral(
            "width=1280\nheight=720\nnb_read_frames=2\nprofile=Main\n"),
        QByteArrayLiteral(
            "width=2240\nheight=1080\nnb_read_frames=2\n"),
        QByteArrayLiteral("width=1280\nheight=720\n"),
        QByteArrayLiteral(
            "width=1280\nheight=720\nnb_read_frames=0\n"),
        QByteArrayLiteral(
            "width=1280\nheight=720\nnb_read_frames=4294967296\n"),
        QByteArrayLiteral(
            "width=1280\nheight=720\nnb_read_frames=not-a-number\n")};
    for (const QByteArray &probe : malformed) {
        const turris::FrameCountProbeResult result =
            turris::parseFrameCountProbe(probe, turris::kVideoKind);
        QVERIFY2(!result.valid, probe.constData());
        QCOMPARE(result.frameCount, quint64{0});
    }

    const turris::FrameCountProbeResult multiFrameImage =
        turris::parseFrameCountProbe(
            QByteArrayLiteral(
                "width=1280\nheight=720\nnb_read_frames=2\n"),
            turris::kImageKind);
    QVERIFY(!multiFrameImage.valid);
    QCOMPARE(multiFrameImage.frameCount, quint64{0});

    const turris::FrameCountProbeResult unknownKind =
        turris::parseFrameCountProbe(
            QByteArrayLiteral(
                "width=1280\nheight=720\nnb_read_frames=2\n"),
            999U);
    QVERIFY(!unknownKind.valid);
    QCOMPARE(unknownKind.frameCount, quint64{0});
}

void PrinterProtocolTests::turrisMediaFormatWriterIsAtomicAndRewinds() {
    namespace turris = tryx::turris_media;

    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    QByteArray expectedMetadata;
    QByteArray rawH264;
    const QByteArray expectedBlob = turrisMediaBlob(
        turris::kVideoKind, 2);
    QVERIFY(splitTurrisMediaBlob(
        expectedBlob, &expectedMetadata, &rawH264));
    QVERIFY(!expectedMetadata.isEmpty());

    const QString rawPath = QDir(temporaryDirectory.path()).filePath(
        QStringLiteral("source.h264"));
    const QString outputPath = QDir(temporaryDirectory.path()).filePath(
        QStringLiteral("output.mxhd"));
    QVERIFY(writeTextFile(rawPath, rawH264));

    const turris::WriteResult written = turris::writeBlob(
        rawPath, outputPath, turris::kVideoKind, 2, {});
    QVERIFY2(written.error.isEmpty(), qPrintable(written.error));
    QVERIFY(!written.cancelled);
    QVERIFY(!written.sha256.isEmpty());

    QFile output(outputPath);
    QVERIFY(output.open(QIODevice::ReadOnly));
    const QByteArray actualBlob = output.readAll();
    QCOMPARE(actualBlob, expectedBlob);
    QCOMPARE(
        written.sha256,
        QString::fromLatin1(
            QCryptographicHash::hash(
                actualBlob, QCryptographicHash::Sha256).toHex()));
    output.close();

    const QString validationPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("validation.mxhd"));
    QVERIFY(writeTextFile(validationPath, expectedBlob));
    QFile validationFile(validationPath);
    QVERIFY(validationFile.open(QIODevice::ReadOnly));
    QVERIFY(validationFile.seek(7));
    QString validationError;
    QVERIFY2(turris::validateBlob(
                 &validationFile, expectedBlob.size(),
                 QStringLiteral("fixture.mp4.h264_1280x720"),
                 &validationError),
             qPrintable(validationError));
    QCOMPARE(validationFile.pos(), qint64{0});
    QCOMPARE(validationFile.read(4), expectedBlob.left(4));
    validationFile.close();

    QByteArray largeRaw(300 * 1024, '\0');
    largeRaw.replace(0, 5, QByteArray::fromHex("0000000167"));
    const QString largeRawPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("large-source.h264"));
    const QString cancelledPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("cancelled.mxhd"));
    QVERIFY(writeTextFile(largeRawPath, largeRaw));
    const QByteArray sentinel("existing-target");
    QVERIFY(writeTextFile(cancelledPath, sentinel));
    const QStringList entriesBefore =
        QDir(temporaryDirectory.path()).entryList(
            QDir::Files | QDir::Hidden | QDir::System |
            QDir::NoDotAndDotDot);
    int cancellationChecks = 0;
    const turris::WriteResult cancelled = turris::writeBlob(
        largeRawPath, cancelledPath, turris::kVideoKind, 2,
        [&cancellationChecks]() {
            ++cancellationChecks;
            return cancellationChecks >= 3;
        });
    QVERIFY(cancelled.cancelled);
    QVERIFY(cancelled.sha256.isEmpty());
    QVERIFY(cancelled.error.isEmpty());
    QVERIFY(cancellationChecks >= 3);
    QFile cancelledTarget(cancelledPath);
    QVERIFY(cancelledTarget.open(QIODevice::ReadOnly));
    QCOMPARE(cancelledTarget.readAll(), sentinel);
    QCOMPARE(
        QDir(temporaryDirectory.path()).entryList(
            QDir::Files | QDir::Hidden | QDir::System |
            QDir::NoDotAndDotDot),
        entriesBefore);
}

void PrinterProtocolTests::
    turrisMediaFormatValidatorRejectsMalformedMetadata() {
    namespace turris = tryx::turris_media;

    QByteArray baseMetadata;
    QByteArray rawH264;
    const QByteArray validBlob = turrisMediaBlob(
        turris::kVideoKind, 2);
    QVERIFY(splitTurrisMediaBlob(
        validBlob, &baseMetadata, &rawH264));

    QByteArray duplicateField = baseMetadata;
    appendTurrisVarintField(&duplicateField, 1, 0x4D584844U);
    QByteArray unknownField = baseMetadata;
    appendTurrisVarintField(&unknownField, 9, 1);
    QByteArray nonCanonicalVarint = baseMetadata;
    nonCanonicalVarint.replace(
        0, 1, QByteArray::fromHex("8800"));
    QByteArray missingField = baseMetadata;
    missingField.chop(2);
    QByteArray wrongFps = baseMetadata;
    const qsizetype fpsField =
        wrongFps.indexOf(QByteArray::fromHex("281e"));
    QVERIFY(fpsField >= 0);
    wrongFps[fpsField + 1] = static_cast<char>(29);

    struct MalformedCase {
        QByteArray blob;
        QString remoteName;
    };
    const QList<MalformedCase> malformed{
        {wrapTurrisMediaBlob(duplicateField, rawH264),
         QStringLiteral("duplicate.mp4.h264_1280x720")},
        {wrapTurrisMediaBlob(unknownField, rawH264),
         QStringLiteral("unknown.mp4.h264_1280x720")},
        {wrapTurrisMediaBlob(nonCanonicalVarint, rawH264),
         QStringLiteral("noncanonical.mp4.h264_1280x720")},
        {wrapTurrisMediaBlob(missingField, rawH264),
         QStringLiteral("missing.mp4.h264_1280x720")},
        {wrapTurrisMediaBlob(wrongFps, rawH264),
         QStringLiteral("fps.mp4.h264_1280x720")},
        {validBlob, QStringLiteral("kind.png.h264_1280x720")},
        {wrapTurrisMediaBlob(
             baseMetadata, QByteArrayLiteral("not-annex-b")),
         QStringLiteral("payload.mp4.h264_1280x720")},
    };

    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    for (qsizetype index = 0; index < malformed.size(); ++index) {
        const MalformedCase &testCase = malformed.at(index);
        const QString path =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("malformed-%1.mxhd").arg(index));
        QVERIFY(writeTextFile(path, testCase.blob));
        QFile file(path);
        QVERIFY(file.open(QIODevice::ReadOnly));
        QString error;
        QVERIFY(!turris::validateBlob(
            &file, testCase.blob.size(), testCase.remoteName, &error));
        QVERIFY2(error.contains(
                     QStringLiteral("container"),
                     Qt::CaseInsensitive),
                 qPrintable(error));
    }
}

void PrinterProtocolTests::turrisImagePreparationBuildsMxhdBlob() {
    if (QStandardPaths::findExecutable(QStringLiteral("ffmpeg")).isEmpty() ||
        QStandardPaths::findExecutable(QStringLiteral("ffprobe")).isEmpty()) {
        QSKIP("ffmpeg and ffprobe are required for the integration test");
    }
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString sourcePath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("turris-image.png"));
    QImage image(32, 18, QImage::Format_RGB32);
    image.fill(QColor(QStringLiteral("#336699")));
    QVERIFY(image.save(sourcePath));

    PrinterMediaPreparer preparer;
    QSignalSpy preparedSpy(&preparer,
                           &PrinterMediaPreparer::prepared);
    QSignalSpy failedSpy(&preparer,
                         &PrinterMediaPreparer::failed);
    const QString operationId =
        QStringLiteral("20112011-2011-4011-8011-201120112016");
    preparer.prepare(
        operationId, QStringLiteral("turris-endpoint"), sourcePath,
        QString(), 11, tryxLegacyFitMediaTransform(), 0x2011);
    QTRY_VERIFY_WITH_TIMEOUT(
        preparedSpy.count() + failedSpy.count() > 0, 60000);
    if (!failedSpy.isEmpty()) {
        QFAIL(qPrintable(failedSpy.first().at(1).toString()));
    }
    QCOMPARE(preparedSpy.count(), 1);
    const QList<QVariant> prepared = preparedSpy.first();
    QCOMPARE(prepared.at(0).toString(), operationId);
    const QString outputPath = prepared.at(3).toString();
    const QString remoteName = prepared.at(4).toString();
    const QString expectedSha256 = prepared.at(5).toString();
    QVERIFY(remoteName.endsWith(
        QStringLiteral(".png.h264_1280x720")));

    QFile output(outputPath);
    QVERIFY(output.open(QIODevice::ReadOnly));
    const QByteArray blob = output.readAll();
    QVERIFY(blob.size() > 4);
    QCOMPARE(static_cast<quint8>(blob.at(0)), quint8{65});
    QCOMPARE(static_cast<quint8>(blob.at(1)), quint8{0});
    QCOMPARE(static_cast<quint8>(blob.at(2)), quint8{0});
    QCOMPARE(static_cast<quint8>(blob.at(3)), quint8{0});
    QByteArray metadata;
    QByteArray h264;
    QVERIFY(splitTurrisMediaBlob(blob, &metadata, &h264));
    QCOMPARE(metadata, turrisMediaMetadata(2, 1));
    QVERIFY(h264.startsWith(QByteArray::fromHex("00000001")) ||
            h264.startsWith(QByteArray::fromHex("000001")));
    const QString rawPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("turris-image.raw.h264"));
    QVERIFY(writeTextFile(rawPath, h264));
    QProcess probe;
    probe.start(
        QStandardPaths::findExecutable(QStringLiteral("ffprobe")),
        {QStringLiteral("-v"), QStringLiteral("error"),
         QStringLiteral("-f"), QStringLiteral("h264"),
         QStringLiteral("-select_streams"), QStringLiteral("v:0"),
         QStringLiteral("-count_frames"),
         QStringLiteral("-show_entries"),
         QStringLiteral("stream=profile,level,width,height,color_range,color_space,color_transfer,color_primaries,nb_read_frames"),
         QStringLiteral("-of"),
         QStringLiteral("default=noprint_wrappers=1"), rawPath});
    QVERIFY(probe.waitForFinished(10000));
    QCOMPARE(probe.exitStatus(), QProcess::NormalExit);
    QCOMPARE(probe.exitCode(), 0);
    const QStringList properties =
        QString::fromLatin1(probe.readAllStandardOutput())
            .split(QLatin1Char('\n'), Qt::SkipEmptyParts);
    for (const QString &expected : {
             QStringLiteral("profile=Main"),
             QStringLiteral("level=40"),
             QStringLiteral("width=1280"),
             QStringLiteral("height=720"),
             QStringLiteral("color_range=pc"),
             QStringLiteral("color_space=bt709"),
             QStringLiteral("color_transfer=bt709"),
             QStringLiteral("color_primaries=bt709"),
             QStringLiteral("nb_read_frames=1")}) {
        QVERIFY2(properties.contains(expected), qPrintable(expected));
    }
    QCOMPARE(
        expectedSha256,
        QString::fromLatin1(
            QCryptographicHash::hash(blob, QCryptographicHash::Sha256)
                .toHex()));
}

void PrinterProtocolTests::pasePreparationProfilesProduceExactGeometry() {
    namespace validator = tryx::printer_media_validator;

    const QString ffmpeg =
        QStandardPaths::findExecutable(QStringLiteral("ffmpeg"));
    const QString ffprobe =
        QStandardPaths::findExecutable(QStringLiteral("ffprobe"));
    if (ffmpeg.isEmpty() || ffprobe.isEmpty()) {
        QSKIP("ffmpeg and ffprobe are required for the integration test");
    }

    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString sourcePath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("short-source.mp4"));
    QProcess generator;
    generator.setProcessChannelMode(QProcess::MergedChannels);
    generator.start(
        ffmpeg,
        {QStringLiteral("-v"), QStringLiteral("error"),
         QStringLiteral("-f"), QStringLiteral("lavfi"),
         QStringLiteral("-i"),
         QStringLiteral("color=c=#315d84:s=64x64:r=2:d=1"),
         QStringLiteral("-frames:v"), QStringLiteral("2"),
         QStringLiteral("-an"), QStringLiteral("-c:v"),
         QStringLiteral("libx264"), QStringLiteral("-pix_fmt"),
         QStringLiteral("yuv420p"), QStringLiteral("-movflags"),
         QStringLiteral("+faststart"), QStringLiteral("-y"),
         sourcePath});
    const bool generatorFinished = generator.waitForFinished(60000);
    const QByteArray generatorOutput = generator.readAll();
    QVERIFY2(generatorFinished,
             qPrintable(QString::fromLocal8Bit(generatorOutput)));
    QCOMPARE(generator.exitStatus(), QProcess::NormalExit);
    QVERIFY2(generator.exitCode() == 0,
             qPrintable(QString::fromLocal8Bit(generatorOutput)));
    QVERIFY(QFileInfo(sourcePath).size() > 0);

    struct PreparationCase {
        QString target;
        quint32 width;
        quint32 oppositeWidth;
    };
    const QList<PreparationCase> cases{
        {QStringLiteral("FullFrame"), 2240U, 1120U},
        {QStringLiteral("SplitArea"), 1120U, 2240U},
    };
    quint64 generation = 60;
    for (const PreparationCase &testCase : cases) {
        PrinterMediaPreparer preparer;
        QSignalSpy preparedSpy(
            &preparer, &PrinterMediaPreparer::prepared);
        QSignalSpy failedSpy(
            &preparer, &PrinterMediaPreparer::failed);
        TryxRuntimeMediaPreparationProfileV1 profile;
        profile.target = testCase.target;
        profile.transform = tryxLegacyFitMediaTransform();
        const QString operationId =
            QUuid::createUuid().toString(QUuid::WithoutBraces);
        preparer.prepareWithPreparationProfile(
            operationId, QStringLiteral("pase-endpoint"), sourcePath,
            QString(), ++generation, profile, 0x1021);
        QTRY_VERIFY_WITH_TIMEOUT(
            preparedSpy.count() + failedSpy.count() > 0, 120000);
        if (!failedSpy.isEmpty()) {
            QFAIL(qPrintable(failedSpy.first().at(1).toString()));
        }
        QCOMPARE(preparedSpy.count(), 1);
        const QList<QVariant> prepared = preparedSpy.first();
        QCOMPARE(prepared.at(0).toString(), operationId);
        const QString outputPath = prepared.at(3).toString();
        const QString remoteName = prepared.at(4).toString();
        const QString expectedSha256 = prepared.at(5).toString();
        QVERIFY(remoteName.endsWith(
            QStringLiteral(".mp4.h264_%1x1080").arg(testCase.width)));
        const QFileInfo outputInfo(outputPath);
        QVERIFY(outputInfo.exists());
        QVERIFY(outputInfo.isFile());
        QVERIFY(outputInfo.size() > 0);
        QCOMPARE(
            expectedSha256,
            tryx::printer_media_file_integrity::sha256File(outputPath));

        bool cancelled = false;
        QString validationError;
        validator::RecoveredH264ProbeMetadata metadata;
        QVERIFY2(validator::validateRecoveredH264(
                     outputPath, outputInfo.size(), expectedSha256, {},
                     &cancelled, &validationError, &metadata,
                     testCase.width, 1080),
                 qPrintable(validationError));
        QVERIFY(!cancelled);
        QCOMPARE(metadata.width, testCase.width);
        QCOMPARE(metadata.height, quint32{1080});
        QVERIFY(metadata.frameCountAvailable);
        QCOMPARE(metadata.frameCount, quint64{30});

        QProcess probe;
        probe.setProcessChannelMode(QProcess::MergedChannels);
        probe.start(
            ffprobe,
            {QStringLiteral("-v"), QStringLiteral("error"),
             QStringLiteral("-f"), QStringLiteral("h264"),
             QStringLiteral("-select_streams"),
             QStringLiteral("v:0"), QStringLiteral("-count_frames"),
             QStringLiteral("-show_entries"),
             QStringLiteral(
                 "stream=codec_name,width,height,pix_fmt,nb_read_frames"),
             QStringLiteral("-of"),
             QStringLiteral("default=noprint_wrappers=1"),
             outputPath});
        const bool probeFinished = probe.waitForFinished(60000);
        const QByteArray probeOutput = probe.readAll();
        QVERIFY2(probeFinished,
                 qPrintable(QString::fromLocal8Bit(probeOutput)));
        QCOMPARE(probe.exitStatus(), QProcess::NormalExit);
        QVERIFY2(probe.exitCode() == 0,
                 qPrintable(QString::fromLocal8Bit(probeOutput)));
        const QStringList streamProperties =
            QString::fromLocal8Bit(probeOutput)
                .split(QLatin1Char('\n'), Qt::SkipEmptyParts);
        for (const QString &expected : {
                 QStringLiteral("codec_name=h264"),
                 QStringLiteral("width=%1").arg(testCase.width),
                 QStringLiteral("height=1080"),
                 QStringLiteral("pix_fmt=yuv420p"),
                 QStringLiteral("nb_read_frames=30")}) {
            QVERIFY2(streamProperties.contains(expected),
                     qPrintable(expected));
        }

        // Raw Annex-B H264 has no container duration and ffprobe's reported
        // r/avg rates are demux heuristics. Read the SPS timing fields instead:
        // time_scale / (2 * num_units_in_tick) is the nominal frame rate.
        QProcess timingProbe;
        timingProbe.setProcessChannelMode(QProcess::MergedChannels);
        timingProbe.start(
            ffmpeg,
            {QStringLiteral("-v"), QStringLiteral("trace"),
             QStringLiteral("-f"), QStringLiteral("h264"),
             QStringLiteral("-i"), outputPath,
             QStringLiteral("-map"), QStringLiteral("0:v:0"),
             QStringLiteral("-c:v"), QStringLiteral("copy"),
             QStringLiteral("-bsf:v"),
             QStringLiteral("trace_headers"),
             QStringLiteral("-f"), QStringLiteral("null"),
             QStringLiteral("-")});
        const bool timingProbeFinished =
            timingProbe.waitForFinished(60000);
        const QString timingOutput = QString::fromLocal8Bit(
            timingProbe.readAll());
        QVERIFY2(timingProbeFinished, qPrintable(timingOutput));
        QCOMPARE(timingProbe.exitStatus(), QProcess::NormalExit);
        QVERIFY2(timingProbe.exitCode() == 0,
                 qPrintable(timingOutput));
        const QRegularExpressionMatch tickMatch =
            QRegularExpression(QStringLiteral(
                "num_units_in_tick[^\\r\\n]*=\\s*(\\d+)"))
                .match(timingOutput);
        const QRegularExpressionMatch scaleMatch =
            QRegularExpression(QStringLiteral(
                "time_scale[^\\r\\n]*=\\s*(\\d+)"))
                .match(timingOutput);
        QVERIFY2(tickMatch.hasMatch(), qPrintable(timingOutput));
        QVERIFY2(scaleMatch.hasMatch(), qPrintable(timingOutput));
        const quint64 numUnitsInTick =
            tickMatch.captured(1).toULongLong();
        const quint64 timeScale =
            scaleMatch.captured(1).toULongLong();
        QCOMPARE(numUnitsInTick, quint64{1});
        QCOMPARE(timeScale, quint64{60});
        QCOMPARE(timeScale / (2 * numUnitsInTick), quint64{30});
        QCOMPARE(
            metadata.frameCount * 2 * numUnitsInTick * 1000 /
                timeScale,
            quint64{1000});

        validationError.clear();
        QVERIFY(!validator::validateRecoveredH264(
            outputPath, outputInfo.size(), expectedSha256, {},
            &cancelled, &validationError, nullptr,
            testCase.oppositeWidth, 1080));
        QVERIFY(!cancelled);
        QVERIFY2(validationError.contains(
                     QStringLiteral("%1x1080")
                         .arg(testCase.oppositeWidth)),
                 qPrintable(validationError));
    }
}

void PrinterProtocolTests::recoveredMediaValidatorIsStrictAndCancellable() {
    namespace validator = tryx::printer_media_validator;

    const QString ffmpeg =
        QStandardPaths::findExecutable(QStringLiteral("ffmpeg"));
    const QString ffprobe =
        QStandardPaths::findExecutable(QStringLiteral("ffprobe"));
    if (ffmpeg.isEmpty() || ffprobe.isEmpty()) {
        QSKIP("ffmpeg and ffprobe are required for the validator test");
    }

    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const auto generateH264 = [&ffmpeg](
                                  const QString &path,
                                  const QString &geometry,
                                  QString *detail) {
        QProcess process;
        process.setProcessChannelMode(QProcess::MergedChannels);
        process.start(
            ffmpeg,
            {QStringLiteral("-v"), QStringLiteral("error"),
             QStringLiteral("-f"), QStringLiteral("lavfi"),
             QStringLiteral("-i"),
             QStringLiteral("color=c=black:s=%1:r=1:d=1")
                 .arg(geometry),
             QStringLiteral("-frames:v"), QStringLiteral("1"),
             QStringLiteral("-an"), QStringLiteral("-c:v"),
             QStringLiteral("libx264"), QStringLiteral("-pix_fmt"),
             QStringLiteral("yuv420p"), QStringLiteral("-f"),
             QStringLiteral("h264"), QStringLiteral("-y"), path});
        if (!process.waitForFinished(60000) ||
            process.exitStatus() != QProcess::NormalExit ||
            process.exitCode() != 0) {
            if (detail) {
                *detail = QString::fromLocal8Bit(process.readAll());
            }
            return false;
        }
        return true;
    };
    const auto fileBytes = [](const QString &path) {
        QFile file(path);
        if (!file.open(QIODevice::ReadOnly)) {
            return QByteArray();
        }
        return file.readAll();
    };

    const QString validPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("valid-2240x1080.h264"));
    QString generatorError;
    QVERIFY2(generateH264(
                 validPath, QStringLiteral("2240x1080"),
                 &generatorError),
             qPrintable(generatorError));
    const QByteArray validBytes = fileBytes(validPath);
    QVERIFY(!validBytes.isEmpty());
    const QString validHash = QString::fromLatin1(
        QCryptographicHash::hash(
            validBytes, QCryptographicHash::Sha256).toHex());

    bool cancelled = false;
    QString error;
    validator::RecoveredH264ProbeMetadata validatedMetadata;
    QVERIFY2(validator::validateRecoveredH264(
                 validPath, validBytes.size(), validHash, {},
                 &cancelled, &error, &validatedMetadata),
             qPrintable(error));
    QVERIFY(!cancelled);
    QVERIFY(error.isEmpty());
    QVERIFY(validatedMetadata.dimensionsAvailable);
    QCOMPARE(validatedMetadata.width, quint32{2240});
    QCOMPARE(validatedMetadata.height, quint32{1080});
    QVERIFY(validatedMetadata.frameCountAvailable);
    QCOMPARE(validatedMetadata.frameCount, quint64{1});

    const QString splitPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("valid-1120x1080.h264"));
    generatorError.clear();
    QVERIFY2(generateH264(
                 splitPath, QStringLiteral("1120x1080"),
                 &generatorError),
             qPrintable(generatorError));
    const QByteArray splitBytes = fileBytes(splitPath);
    QVERIFY(!splitBytes.isEmpty());
    const QString splitHash = QString::fromLatin1(
        QCryptographicHash::hash(
            splitBytes, QCryptographicHash::Sha256).toHex());
    validator::RecoveredH264ProbeMetadata splitMetadata;
    error.clear();
    QVERIFY2(validator::validateRecoveredH264(
                 splitPath, splitBytes.size(), splitHash, {},
                 &cancelled, &error, &splitMetadata, 1120, 1080),
             qPrintable(error));
    QCOMPARE(splitMetadata.width, quint32{1120});
    QCOMPARE(splitMetadata.height, quint32{1080});
    error.clear();
    QVERIFY(!validator::validateRecoveredH264(
        splitPath, splitBytes.size(), splitHash, {},
        &cancelled, &error));
    QVERIFY(error.contains(QStringLiteral("2240x1080")));

    error.clear();
    QVERIFY(!validator::validateRecoveredH264(
        validPath, validBytes.size() + 1, validHash, {},
        &cancelled, &error));
    QVERIFY(!cancelled);
    QVERIFY(error.contains(QStringLiteral("file size"),
                           Qt::CaseInsensitive));

    error.clear();
    QVERIFY(!validator::validateRecoveredH264(
        validPath, validBytes.size(), QString(64, QLatin1Char('0')), {},
        &cancelled, &error));
    QVERIFY(!cancelled);
    QVERIFY(error.contains(QStringLiteral("hash"),
                           Qt::CaseInsensitive));

    error.clear();
    QVERIFY(!validator::validateRecoveredH264(
        validPath, validBytes.size(), validHash,
        []() { return true; }, &cancelled, &error));
    QVERIFY(cancelled);

    const QString incompletePath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("incomplete.h264"));
    const QByteArray incompleteBytes =
        QByteArray::fromHex("000000016764001f");
    QVERIFY(writeTextFile(incompletePath, incompleteBytes));
    const QString incompleteHash = QString::fromLatin1(
        QCryptographicHash::hash(
            incompleteBytes, QCryptographicHash::Sha256).toHex());
    cancelled = false;
    error.clear();
    QVERIFY(!validator::validateRecoveredH264(
        incompletePath, incompleteBytes.size(), incompleteHash, {},
        &cancelled, &error));
    QVERIFY(!cancelled);
    QVERIFY(error.contains(QStringLiteral("complete Annex B"),
                           Qt::CaseInsensitive));

    const QString wrongGeometryPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("wrong-1280x720.h264"));
    generatorError.clear();
    QVERIFY2(generateH264(
                 wrongGeometryPath, QStringLiteral("1280x720"),
                 &generatorError),
             qPrintable(generatorError));
    const QByteArray wrongGeometryBytes = fileBytes(wrongGeometryPath);
    QVERIFY(!wrongGeometryBytes.isEmpty());
    const QString wrongGeometryHash = QString::fromLatin1(
        QCryptographicHash::hash(
            wrongGeometryBytes, QCryptographicHash::Sha256).toHex());
    error.clear();
    QVERIFY(!validator::validateRecoveredH264(
        wrongGeometryPath, wrongGeometryBytes.size(), wrongGeometryHash, {},
        &cancelled, &error));
    QVERIFY(!cancelled);
    QVERIFY(error.contains(QStringLiteral("2240x1080")));
}

void PrinterProtocolTests::recoveredMediaProbeParserIsExact() {
    namespace validator = tryx::printer_media_validator;

    QVERIFY(validator::hasExpectedRecoveredH264ProbeOutput(
        QByteArrayLiteral("codec_name=h264\nwidth=2240\nheight=1080\n")));
    QVERIFY(validator::hasExpectedRecoveredH264ProbeOutput(
        QByteArrayLiteral("height=1080\r\ncodec_name=h264\r\nwidth=2240\r\n")));
    const validator::RecoveredH264ProbeMetadata split =
        validator::parseRecoveredH264ProbeOutput(
            QByteArrayLiteral(
                "codec_name=h264\nwidth=1120\nheight=1080\n"));
    QVERIFY(split.dimensionsAvailable);
    QCOMPARE(split.width, quint32{1120});
    QCOMPARE(split.height, quint32{1080});

    const validator::RecoveredH264ProbeMetadata complete =
        validator::parseRecoveredH264ProbeOutput(
            QByteArrayLiteral(
                "nb_read_frames=1800\r\nheight=1080\r\n"
                "codec_name=h264\r\nwidth=2240\r\n"));
    QVERIFY(complete.dimensionsAvailable);
    QCOMPARE(complete.width, quint32{2240});
    QCOMPARE(complete.height, quint32{1080});
    QVERIFY(complete.frameCountAvailable);
    QCOMPARE(complete.frameCount, quint64{1800});

    const validator::RecoveredH264ProbeMetadata maximum =
        validator::parseRecoveredH264ProbeOutput(
            QByteArrayLiteral(
                "codec_name=h264\nwidth=2240\nheight=1080\n"
                "nb_read_frames=18144000\n"));
    QVERIFY(maximum.dimensionsAvailable);
    QVERIFY(maximum.frameCountAvailable);
    QCOMPARE(maximum.frameCount, quint64{18144000});

    const validator::RecoveredH264ProbeMetadata overMaximum =
        validator::parseRecoveredH264ProbeOutput(
            QByteArrayLiteral(
                "codec_name=h264\nwidth=2240\nheight=1080\n"
                "nb_read_frames=18144001\n"));
    QVERIFY(overMaximum.dimensionsAvailable);
    QVERIFY(!overMaximum.frameCountAvailable);
    QCOMPARE(overMaximum.frameCount, quint64{0});

    for (const QByteArray &optionalFrameCount : {
             QByteArray{}, QByteArrayLiteral("nb_read_frames=N/A\n"),
             QByteArrayLiteral("nb_read_frames=0\n"),
             QByteArrayLiteral("nb_read_frames=+1\n"),
             QByteArrayLiteral("nb_read_frames=not-a-number\n"),
             QByteArrayLiteral(
                 "nb_read_frames=18446744073709551616\n")}) {
        const validator::RecoveredH264ProbeMetadata partial =
            validator::parseRecoveredH264ProbeOutput(
                QByteArrayLiteral(
                    "codec_name=h264\nwidth=2240\nheight=1080\n") +
                optionalFrameCount);
        QVERIFY2(partial.dimensionsAvailable,
                 optionalFrameCount.constData());
        QCOMPARE(partial.width, quint32{2240});
        QCOMPARE(partial.height, quint32{1080});
        QVERIFY2(!partial.frameCountAvailable,
                 optionalFrameCount.constData());
        QCOMPARE(partial.frameCount, quint64{0});
    }

    for (const QByteArray &probeOutput : {
             QByteArrayLiteral("codec_name=h264\nwidth=22400\nheight=10800\n"),
             QByteArrayLiteral("codec_name=h264\nwidth=2240\nheight=1080\nwidth=2240\n"),
             QByteArrayLiteral("codec_name=h264\nwidth=2240\n"),
             QByteArrayLiteral("codec_name=hevc\nwidth=2240\nheight=1080\n"),
             QByteArrayLiteral("codec_name=h264\nwidth=02240\nheight=1080\n"),
             QByteArrayLiteral("codec_name=h264\nwidth=2240 \nheight=1080\n"),
             QByteArrayLiteral("codec_name=h264\nwidth=2240\nheight=1080\nextra=value\n"),
             QByteArrayLiteral("codec_name=h264\nwidth=2240\nheight=1080\nr_frame_rate=30/1\n")}) {
        QVERIFY(!validator::hasExpectedRecoveredH264ProbeOutput(probeOutput));
        const validator::RecoveredH264ProbeMetadata rejected =
            validator::parseRecoveredH264ProbeOutput(probeOutput);
        QVERIFY2(!rejected.dimensionsAvailable, probeOutput.constData());
        QCOMPARE(rejected.width, quint32{0});
        QCOMPARE(rejected.height, quint32{0});
        QVERIFY(!rejected.frameCountAvailable);
        QCOMPARE(rejected.frameCount, quint64{0});
    }
}

void PrinterProtocolTests::recoveredMediaDiagnosticTailIsBounded() {
    namespace validator = tryx::printer_media_validator;

    const QByteArray hostileOutput(
        (16 * 1024) + 37, 'x');
    const QByteArray bounded =
        validator::validationDiagnosticTailForTesting(hostileOutput);
    QCOMPARE(bounded.size(), 16 * 1024);
    QCOMPARE(bounded, hostileOutput.right(16 * 1024));
}

void PrinterProtocolTests::sha256ValidationRequiresLowercaseAscii() {
    namespace integrity = tryx::printer_media_file_integrity;

    QVERIFY(integrity::isSha256Hex(QString(64, QLatin1Char('0'))));
    QVERIFY(integrity::isSha256Hex(QString(64, QLatin1Char('f'))));
    QVERIFY(!integrity::isSha256Hex(QString(64, QLatin1Char('F'))));
    QVERIFY(!integrity::isSha256Hex(QString(64, QChar(0x0660))));
    QVERIFY(!integrity::isSha256Hex(QString(63, QLatin1Char('0'))));
}

void PrinterProtocolTests::privateRuntimePathsEnforceFilesystemBoundaries() {
    namespace paths = tryx::private_runtime_paths;

    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QDir root(temporaryDirectory.path());
    const auto readFile = [](const QString &path) {
        QFile file(path);
        if (!file.open(QIODevice::ReadOnly)) {
            return QByteArray();
        }
        return file.readAll();
    };
    QString error;

    const QString privatePath = root.filePath(QStringLiteral("private"));
    QVERIFY(!paths::ensurePrivateDirectory(privatePath, false, &error));
    QVERIFY(!error.isEmpty());
    error.clear();
    QVERIFY2(paths::ensurePrivateDirectory(privatePath, true, &error),
             qPrintable(error));
    struct stat directoryStatus {};
    const QByteArray privatePathBytes = QFile::encodeName(privatePath);
    QCOMPARE(::lstat(privatePathBytes.constData(), &directoryStatus), 0);
    QVERIFY(S_ISDIR(directoryStatus.st_mode));
    QCOMPARE(directoryStatus.st_mode & 07777, static_cast<mode_t>(0700));

    const QString insecurePath = root.filePath(QStringLiteral("insecure"));
    QVERIFY(QDir().mkdir(insecurePath));
    QVERIFY(QFile::setPermissions(
        insecurePath,
        QFileDevice::ReadOwner | QFileDevice::WriteOwner |
            QFileDevice::ExeOwner | QFileDevice::ReadGroup |
            QFileDevice::ExeGroup));
    error.clear();
    QVERIFY(!paths::ensurePrivateDirectory(insecurePath, false, &error));
    QVERIFY(error.contains(QStringLiteral("0700")));

    const QString symlinkPath = root.filePath(QStringLiteral("private-link"));
    const QByteArray symlinkPathBytes = QFile::encodeName(symlinkPath);
    QCOMPARE(::symlink(privatePathBytes.constData(),
                       symlinkPathBytes.constData()), 0);
    error.clear();
    QVERIFY(!paths::ensurePrivateDirectory(symlinkPath, false, &error));

    const QString sourcePath = root.filePath(QStringLiteral("source.bin"));
    QVERIFY(writeTextFile(sourcePath, QByteArrayLiteral("source")));
    QVERIFY(QFile::setPermissions(
        sourcePath,
        QFileDevice::ReadOwner | QFileDevice::WriteOwner));
    struct stat sourceStatus {};
    const QByteArray sourcePathBytes = QFile::encodeName(sourcePath);
    QCOMPARE(::lstat(sourcePathBytes.constData(), &sourceStatus), 0);
    QVERIFY(paths::stagedSourceStatIsValid(sourceStatus));

    const QString hardlinkPath = root.filePath(QStringLiteral("hardlink.bin"));
    const QByteArray hardlinkPathBytes = QFile::encodeName(hardlinkPath);
    QCOMPARE(::link(sourcePathBytes.constData(), hardlinkPathBytes.constData()), 0);
    QCOMPARE(::lstat(sourcePathBytes.constData(), &sourceStatus), 0);
    QVERIFY(!paths::stagedSourceStatIsValid(sourceStatus));
    QVERIFY(QFile::remove(hardlinkPath));

    const QString collisionSource =
        root.filePath(QStringLiteral("collision-source.bin"));
    const QString collisionDestination =
        root.filePath(QStringLiteral("collision-destination.bin"));
    QVERIFY(writeTextFile(collisionSource, QByteArrayLiteral("new")));
    QVERIFY(writeTextFile(collisionDestination, QByteArrayLiteral("existing")));
    error.clear();
    QVERIFY(!paths::atomicRenameNoReplace(
        collisionSource, collisionDestination, &error));
    QVERIFY(!error.isEmpty());
    QCOMPARE(readFile(collisionSource), QByteArrayLiteral("new"));
    QCOMPARE(readFile(collisionDestination), QByteArrayLiteral("existing"));

    const QString claimedDestination =
        root.filePath(QStringLiteral("claimed.bin"));
    error.clear();
    QVERIFY2(paths::atomicRenameNoReplace(
                 collisionSource, claimedDestination, &error),
             qPrintable(error));
    QVERIFY(!QFileInfo::exists(collisionSource));
    QCOMPARE(readFile(claimedDestination), QByteArrayLiteral("new"));

    QVERIFY(paths::pathIsInside(QStringLiteral("/tmp/file"),
                                QStringLiteral("/")));
    QVERIFY(!paths::pathIsInside(QStringLiteral("/tmp2/file"),
                                 QStringLiteral("/tmp")));
}

void PrinterProtocolTests::runtimeUploadAdaptorsPreserveMediaTransform() {
    registerTryxRuntimeMetaTypes();

    enum class UploadMethod {
        LegacyUpload,
        LegacyUploadAndApply,
        LegacyEnsure,
        TransformedUpload,
        TransformedUploadAndApply,
        TransformedEnsure
    };
    const QList<UploadMethod> methods{
        UploadMethod::LegacyUpload,
        UploadMethod::LegacyUploadAndApply,
        UploadMethod::LegacyEnsure,
        UploadMethod::TransformedUpload,
        UploadMethod::TransformedUploadAndApply,
        UploadMethod::TransformedEnsure
    };

    for (const UploadMethod method : methods) {
        QTemporaryDir temporaryDirectory;
        QVERIFY(temporaryDirectory.isValid());
        const QString sysRoot =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("sys"));
        const QString devRoot =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("dev"));
        QVERIFY(createUsbDevice(sysRoot, QStringLiteral("1-1"), "1021"));
        QVERIFY(createPrinterEndpoint(
            sysRoot, devRoot, QStringLiteral("1-1"),
            QStringLiteral("lp0")));
        std::unique_ptr<DeviceManager> manager(
            DeviceManager::createForTesting(sysRoot, devRoot));
        manager->setAutoConnectModeForTesting(true);
        manager->rescanPrinterForTesting();
        manager->sessionController_.state_.printerDisplaySessionActive = true;

        const QString sourcePath =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("transform.png"));
        QVERIFY(writeTextFile(sourcePath, QByteArray("transform")));

        QObject::disconnect(
            manager.get(), &DeviceManager::requestAnalyzePrinterSource,
            manager->printerMediaPreparer_,
            &PrinterMediaPreparer::analyzeSource);
        QObject::disconnect(
            manager.get(), &DeviceManager::requestPreparePrinterMedia,
            manager->printerMediaPreparer_,
            &PrinterMediaPreparer::prepare);
        QSignalSpy analyzeSpy(
            manager.get(), &DeviceManager::requestAnalyzePrinterSource);
        QSignalSpy prepareSpy(
            manager.get(), &DeviceManager::requestPreparePrinterMedia);

        TryxRuntimeExportedObject exportedObject;
        TryxRuntimeManagerAdaptor connectionAdaptor(
            &exportedObject, manager.get());
        TryxRuntimeOperationsAdaptor operationsAdaptor(
            &exportedObject, manager.get(), &connectionAdaptor);

        TryxRuntimeApplyRequest applyRequest;
        applyRequest.screenMode = QStringLiteral("Full Screen");
        applyRequest.playMode = QStringLiteral("Single");
        applyRequest.ratio = QStringLiteral("2:1");
        TryxRuntimeMediaTransform transformed =
            tryxLegacyFitMediaTransform();
        transformed.mode = QStringLiteral("Crop");
        transformed.rotationQuarterTurns = 3;
        transformed.zoomPermille = 2200;
        transformed.focusX = 3000;
        transformed.focusY = 7000;

        const QString operationId =
            QUuid::createUuid().toString(QUuid::WithoutBraces);
        switch (method) {
        case UploadMethod::LegacyUpload:
            operationsAdaptor.QueueUpload(operationId, sourcePath, false);
            break;
        case UploadMethod::LegacyUploadAndApply:
            operationsAdaptor.QueueUploadWithApply(
                operationId, sourcePath, applyRequest);
            break;
        case UploadMethod::LegacyEnsure:
            operationsAdaptor.QueueEnsureMediaAndApply(
                operationId, sourcePath, applyRequest);
            break;
        case UploadMethod::TransformedUpload:
            operationsAdaptor.QueueUploadWithTransform(
                operationId, sourcePath, transformed);
            break;
        case UploadMethod::TransformedUploadAndApply:
            operationsAdaptor.QueueUploadWithApplyAndTransform(
                operationId, sourcePath, applyRequest, transformed);
            break;
        case UploadMethod::TransformedEnsure:
            operationsAdaptor.QueueEnsureMediaAndApplyWithTransform(
                operationId, sourcePath, applyRequest, transformed);
            break;
        }

        const bool ensure =
            method == UploadMethod::LegacyEnsure ||
            method == UploadMethod::TransformedEnsure;
        QCOMPARE(analyzeSpy.count(), ensure ? 1 : 0);
        QCOMPARE(prepareSpy.count(), ensure ? 0 : 1);
        const QList<QVariant> arguments =
            ensure ? analyzeSpy.first() : prepareSpy.first();
        const int transformIndex = ensure ? 3 : 5;
        const TryxRuntimeMediaTransform actual =
            arguments.at(transformIndex)
                .value<TryxRuntimeMediaTransform>();
        const bool transformedMethod =
            method == UploadMethod::TransformedUpload ||
            method == UploadMethod::TransformedUploadAndApply ||
            method == UploadMethod::TransformedEnsure;
        QCOMPARE(
            tryxMediaTransformCanonicalValue(actual),
            tryxMediaTransformCanonicalValue(
                transformedMethod
                    ? transformed
                    : tryxLegacyFitMediaTransform()));
    }
}

