void PrinterProtocolTests::
metricsCatalogTokensAndPaseGroupIdsRemainFrozen() {
    QFETCH(QString, token);
    QFETCH(quint32, groupId);
    QFETCH(quint32, titleId);
    QFETCH(quint32, valueId);
    QFETCH(quint32, unitId);

    const QStringList expectedCatalog = {
        QStringLiteral("CPU Temperature"),
        QStringLiteral("CPU Frequency"),
        QStringLiteral("CPU Usage"),
        QStringLiteral("CPU Power"),
        QStringLiteral("GPU Temperature"),
        QStringLiteral("GPU Frequency"),
        QStringLiteral("GPU Usage"),
        QStringLiteral("GPU Power"),
        QStringLiteral("Memory Frequency"),
        QStringLiteral("Memory Usage"),
        QStringLiteral("Date&Time")};
    QCOMPARE(tryxMetricsCatalog(), expectedCatalog);

    int sockets[2] = {-1, -1};
    QString socketError;
    QVERIFY2(createSocketPair(sockets, &socketError),
             qPrintable(socketError));
    PrinterProtocol protocol;
    const QString endpoint =
        QStringLiteral("/dev/usb/lp-pase-frozen-metric-ids");
    protocol.adoptFileDescriptorForTesting(sockets[0], endpoint);
    panorama::wire::v1::Request captured;
    QString peerError;
    std::thread peer([&]() {
        if (!readRequest(sockets[1], &captured, &peerError)) {
            return;
        }
        auto response = baseResponse(captured);
        response.mutable_acknowledgement();
        writeResponse(sockets[1], response, &peerError);
    });

    PrinterProtocol::PaseOverlayConfig overlay;
    overlay.dualMode = true;
    overlay.left.metrics = {token};
    overlay.right.metrics = {token};
    QString error;
    const bool sent = protocol.sendPaseRunConfigForTesting(
        endpoint, overlay, &error,
        PrinterProtocol::OperationContext{});
    peer.join();
    ::close(sockets[1]);

    QVERIFY2(sent, qPrintable(error));
    QVERIFY2(peerError.isEmpty(), qPrintable(peerError));
    QCOMPARE(captured.overlay_layout().label_groups_size(), 2);
    for (int side = 0; side < 2; ++side) {
        const quint32 offset = side == 0 ? 0U : 100U;
        const auto &group =
            captured.overlay_layout().label_groups(side);
        QCOMPARE(group.group_id(), groupId + offset);
        QCOMPARE(group.labels_size(), unitId == 0U ? 2 : 3);
        QCOMPARE(group.labels(0).label_id(), titleId + offset);
        QCOMPARE(group.labels(1).label_id(), valueId + offset);
        if (unitId != 0U) {
            QCOMPARE(group.labels(2).label_id(), unitId + offset);
        }
    }
}

