void PrinterProtocolTests::queuedApplyCancellationIsNotDrainedOrExecuted() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString sysRoot =
        QDir(temporaryDirectory.path()).filePath(QStringLiteral("sys"));
    const QString devRoot =
        QDir(temporaryDirectory.path()).filePath(QStringLiteral("dev"));
    QVERIFY(createUsbDevice(sysRoot, QStringLiteral("1-1"), "1021"));
    QVERIFY(createPrinterEndpoint(sysRoot, devRoot,
                                  QStringLiteral("1-1"),
                                  QStringLiteral("lp0")));

    std::unique_ptr<DeviceManager> manager(
        DeviceManager::createForTesting(sysRoot, devRoot));
    manager->setAutoConnectModeForTesting(true);
    manager->rescanPrinterForTesting();
    QVERIFY(manager->isPrinterClassConnected());
    manager->sessionController_.state_.printerDisplaySessionActive = true;
    QSignalSpy changedSpy(manager.get(), &DeviceManager::operationChanged);

    TryxRuntimeApplyRequest request;
    request.media = {QStringLiteral("existing.mp4.h264_2240x1080")};
    request.ratio = QStringLiteral("2:1");
    request.screenMode = QStringLiteral("Full Screen");
    request.playMode = QStringLiteral("Single");
    const QString operationId =
        QStringLiteral("33333333-3333-4333-8333-333333333333");
    QCOMPARE(manager->queueApplyOperation(operationId, request), operationId);
    QCOMPARE(manager->operationInfo(operationId).state,
             QStringLiteral("Preflight"));

    manager->cancelOperation(operationId);
    QTRY_COMPARE(manager->operationInfo(operationId).state,
                 QStringLiteral("Cancelled"));
    QCOMPARE(manager->operationInfo(operationId).errorCategory,
             QStringLiteral("UserCancelled"));
    QVERIFY(manager->activeOperationInfo().id.isEmpty());

    int terminalSignals = 0;
    for (const QList<QVariant> &arguments : changedSpy) {
        const TryxRuntimeOperationInfo info =
            qvariant_cast<TryxRuntimeOperationInfo>(arguments.at(0));
        if (info.id == operationId &&
            (info.state == QStringLiteral("Succeeded") ||
             info.state == QStringLiteral("Failed") ||
             info.state == QStringLiteral("Cancelled") ||
             info.state == QStringLiteral("RetryAvailable"))) {
            ++terminalSignals;
        }
    }
    QCOMPARE(terminalSignals, 1);
}


void PrinterProtocolTests::
    retryCacheStoreRejectsInvalidPreparedDomainMetadata_data() {
    QTest::addColumn<QString>("scenario");

    QTest::newRow("conversion-identity-mismatch")
        << QStringLiteral("conversion");
    QTest::newRow("original-name-from-other-product-profile")
        << QStringLiteral("original-name");
    QTest::newRow("retry-name-from-other-product-profile")
        << QStringLiteral("retry-name");
    QTest::newRow("unsupported-product")
        << QStringLiteral("unsupported-product");
    QTest::newRow("turris-2011-without-required-origin")
        << QStringLiteral("turris-without-origin");
}

void PrinterProtocolTests::
    retryCacheStoreRejectsInvalidPreparedDomainMetadata() {
    QFETCH(QString, scenario);
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    const QString stagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("invalid-domain-source.bin"));
    const QByteArray preparedBytes("invalid-domain-prepared-media");
    QVERIFY(writeAtomicOwnerFile(stagingPath, preparedBytes));

    auto input = retryCachePreparedInput(
        stagingPath, preparedBytes,
        QStringLiteral("invalid-domain"));
    const auto turrisProfile = printerProductProfileForId(0x2011);
    QVERIFY(turrisProfile.has_value());
    const QString turrisRemoteName =
        QStringLiteral("invalid-domain.mp4.h264_1280x720");
    if (scenario == QStringLiteral("conversion")) {
        input.conversion = tryx::printer_media_identity::
            printerMediaConversionIdentity(*turrisProfile);
    } else if (scenario == QStringLiteral("original-name")) {
        input.originalRemoteName = turrisRemoteName;
    } else if (scenario == QStringLiteral("retry-name")) {
        input.retryRemoteName = turrisRemoteName;
    } else if (scenario == QStringLiteral("unsupported-product")) {
        input.productId = 0xffff;
    } else if (scenario == QStringLiteral("turris-without-origin")) {
        input.productId = turrisProfile->productId;
        input.conversion = tryx::printer_media_identity::
            printerMediaConversionIdentity(*turrisProfile);
        input.originalRemoteName = turrisRemoteName;
        input.retryRemoteName = turrisRemoteName;
        QVERIFY(!input.origin.has_value());
    } else {
        QFAIL("Unknown invalid prepared domain scenario");
    }

    tryx::RetryCacheStore store(retryDirectory);
    const auto rejected = store.persistPrepared(input);
    QCOMPARE(rejected.code,
             tryx::RetryCacheStore::ErrorCode::InvalidInput);
    QVERIFY(!rejected.ok());
    QVERIFY(!rejected.snapshot.has_value());
    QVERIFY(!store.blocksMutations());
    QVERIFY(!QFileInfo::exists(store.canonicalManifestPath()));
    QVERIFY(!QFileInfo::exists(store.legacyShadowManifestPath()));
    QFile preservedStaging(stagingPath);
    QVERIFY(preservedStaging.open(QIODevice::ReadOnly));
    QCOMPARE(preservedStaging.readAll(), preparedBytes);
}

void PrinterProtocolTests::runtimeDowngradeBlocksBadgeFormats_data() {
    QTest::addColumn<QString>("storeName");
    QTest::newRow("overlay-v3") << QStringLiteral("overlay");
    QTest::newRow("saved-v2") << QStringLiteral("saved");
}

void PrinterProtocolTests::runtimeDowngradeBlocksBadgeFormats() {
    QFETCH(QString, storeName);
    QTemporaryDir temporary;
    QVERIFY(temporary.isValid());
    std::unique_ptr<DeviceManager> manager(DeviceManager::createForTesting(
        temporary.filePath(QStringLiteral("sys")), temporary.filePath(QStringLiteral("dev"))));
    const QString path = storeName == QStringLiteral("overlay")
        ? manager->sessionController_.paseMetricsConfigStore_->configPath()
        : manager->savedLayoutStore_->indexPath();
    QVERIFY(QDir().mkpath(QFileInfo(path).absolutePath()));
    const QByteArray bytes = storeName == QStringLiteral("overlay")
        ? QByteArrayLiteral("{\"version\":3}") : QByteArrayLiteral("{\"version\":2}");
    QVERIFY(writeAtomicOwnerFile(path, bytes));
    QSignalSpy exitSpy(manager.get(), &DeviceManager::runtimeDowngradeV10PreparedForExit);
    QString mode, errorName, errorMessage;
    QVERIFY(!manager->prepareRuntimeDowngradeV10(&mode, &errorName, &errorMessage));
    QCOMPARE(errorName, QStringLiteral("org.tryx.Panorama.Error.DowngradeV10Blocked"));
    QVERIFY(!manager->runtimeDowngradeV10Prepared());
    QCOMPARE(exitSpy.count(), 0);
    QCOMPARE(readFileBytes(path), bytes);
}

void PrinterProtocolTests::retryLegacyUpgradePreservesBackup() {
    QTemporaryDir temporary;
    QVERIFY(temporary.isValid());
    const QString retryRoot = temporary.filePath(QStringLiteral("retry"));
    const QString canonicalRoot = QDir(retryRoot).filePath(QStringLiteral("v11"));
    QVERIFY(QDir().mkpath(canonicalRoot));
    QVERIFY(QFile::setPermissions(retryRoot, QFileDevice::ReadOwner | QFileDevice::WriteOwner | QFileDevice::ExeOwner));
    QVERIFY(QFile::setPermissions(canonicalRoot, QFileDevice::ReadOwner | QFileDevice::WriteOwner | QFileDevice::ExeOwner));
    const QString manifestPath = QDir(canonicalRoot).filePath(QStringLiteral("retry-manifest.json"));
    const QByteArray oldBytes("{\"version\":11,\"storeRevision\":\"19\"}");
    QVERIFY(writeAtomicOwnerFile(manifestPath, oldBytes));
    tryx::RetryCacheStore store(retryRoot);
    const auto loaded = store.load();
    QCOMPARE(loaded.status, tryx::RetryCacheStore::LoadStatus::Loaded);
    QCOMPARE(readFileBytes(manifestPath), oldBytes);
    QCOMPARE(QDir(canonicalRoot).entryList(QDir::Files).size(), 1);
    const QByteArray bytes("legacy-upgrade-prepared");
    const QString staging = temporary.filePath(QStringLiteral("prepared.bin"));
    QVERIFY(writeAtomicOwnerFile(staging, bytes));
    auto input = retryCachePreparedInput(staging, bytes, QStringLiteral("upgrade"));
    TryxRuntimeApplyWithBadgesV1 autoEnvelope;
    autoEnvelope.request.screenMode = QStringLiteral("Full Screen");
    autoEnvelope.request.playMode = QStringLiteral("Single");
    autoEnvelope.request.ratio = QStringLiteral("2:1");
    input.applyWithBadges = autoEnvelope; // Accepted Auto continuation need not replace the overlay.
    const auto persisted = store.persistPrepared(*loaded.snapshot, input);
    QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
    const QString backupPath = manifestPath + QStringLiteral(".pre-c16-")
        + QString::fromLatin1(QCryptographicHash::hash(oldBytes, QCryptographicHash::Sha256).toHex());
    QCOMPARE(readFileBytes(backupPath), oldBytes);
    QCOMPARE(QJsonDocument::fromJson(readFileBytes(manifestPath)).object().value(QStringLiteral("version")).toInt(), 12);
    tryx::RetryCacheStore::ExpectedDispatch expected{input.lineageId, input.dispatchId, input.operationId,
        input.productId, input.deviceIdentity, input.deviceGeneration};
    const auto armed = store.armDispatch(*persisted.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));
    const auto retired = store.retireDispatch(*armed.snapshot, expected,
        tryx::RetryCacheStore::DispatchRetirement::ProvenNotStarted);
    QVERIFY2(retired.ok(), qPrintable(retired.detail));
    tryx::RetryCacheStore restarted(retryRoot);
    QCOMPARE(restarted.load().status, tryx::RetryCacheStore::LoadStatus::Loaded);
    QCOMPARE(readFileBytes(backupPath), oldBytes);
    QVERIFY(writeAtomicOwnerFile(backupPath, QByteArrayLiteral("{\"version\":11}")));
    tryx::RetryCacheStore tampered(retryRoot);
    QCOMPARE(tampered.load().status, tryx::RetryCacheStore::LoadStatus::Conflict);
    QVERIFY(QFileInfo::exists(backupPath));
}

void PrinterProtocolTests::retryBadgeManifestRejectsMutation_data() {
    QTest::addColumn<QString>("mutation");
    for (const char *name : {"missing-fingerprint", "wrong-fingerprint", "future-schema", "hidden-text", "invalid-text",
             "unexpected-media", "unsupported-product", "disguised-v11", "retry-missing", "retry-different"})
        QTest::newRow(name) << QString::fromLatin1(name);
}

void PrinterProtocolTests::retryBadgeManifestRejectsMutation() {
    QFETCH(QString, mutation);
    QTemporaryDir temporary;
    QVERIFY(temporary.isValid());
    const QByteArray bytes("strict-badge-payload");
    const QString staging = temporary.filePath(QStringLiteral("prepared.bin"));
    QVERIFY(writeAtomicOwnerFile(staging, bytes));
    auto input = retryCachePreparedInput(staging, bytes, QStringLiteral("strict"));
    TryxRuntimeApplyWithBadgesV1 envelope;
    envelope.request.screenMode = QStringLiteral("Full Screen");
    envelope.request.playMode = QStringLiteral("Single");
    envelope.request.ratio = QStringLiteral("2:1");
    envelope.request.replaceOverlay = true;
    envelope.request.settingsBadges = {QStringLiteral("CPU Badge")};
    envelope.badges.primaryCpu = {QStringLiteral("Custom"), QStringLiteral("Private sentinel")};
    QVERIFY(tryx::pase_overlay_config::normalizeAndValidatePaseApplyOverlayStyles(&envelope.request));
    input.applyWithBadges = envelope;
    tryx::RetryCacheStore writer(temporary.filePath(QStringLiteral("retry")));
    QVERIFY(writer.persistPrepared(input).ok());
    QJsonObject manifest = QJsonDocument::fromJson(readFileBytes(writer.canonicalManifestPath())).object();
    auto dispatch = manifest.value(QStringLiteral("inFlightDispatch")).toObject();
    if (mutation.startsWith(QStringLiteral("retry-"))) {
        auto candidate = dispatch;
        candidate.insert(QStringLiteral("phase"), QStringLiteral("NotStarted"));
        candidate.insert(QStringLiteral("confirmedBytes"), QStringLiteral("0"));
        candidate.insert(QStringLiteral("lastConfirmedChunkIndex"), -1);
        candidate.insert(QStringLiteral("requiresDeviceRecovery"), false);
        candidate.insert(QStringLiteral("requiresNewRemoteName"), false);
        candidate.insert(QStringLiteral("finalizationOnlyReconciliation"), false);
        manifest.insert(QStringLiteral("retryCandidate"), candidate);
        dispatch.insert(QStringLiteral("dispatchId"), QUuid::createUuid().toString(QUuid::WithoutBraces));
        dispatch.insert(QStringLiteral("operationId"), QUuid::createUuid().toString(QUuid::WithoutBraces));
        dispatch.insert(QStringLiteral("attempt"), 2);
        dispatch.insert(QStringLiteral("retriesLineageId"), input.lineageId);
    }
    if (mutation == QStringLiteral("future-schema")) envelope.schemaVersion = 2;
    if (mutation == QStringLiteral("hidden-text")) envelope.request.settingsBadges.clear();
    if (mutation == QStringLiteral("invalid-text")) envelope.badges.primaryCpu.text.append(QLatin1Char('\n'));
    if (mutation == QStringLiteral("unexpected-media")) envelope.request.media = {input.originalRemoteName};
    if (mutation == QStringLiteral("unsupported-product")) dispatch.insert(QStringLiteral("productId"), 0x1011);
    if (mutation == QStringLiteral("disguised-v11")) manifest.insert(QStringLiteral("version"), 11);
    if (mutation == QStringLiteral("retry-different")) envelope.badges.primaryCpu.text = QStringLiteral("Different intent");
    dispatch.insert(QStringLiteral("applyWithBadges"), tryx::runtime_apply_request_codec::runtimeApplyWithBadgesV1ToJson(envelope));
    dispatch.insert(QStringLiteral("applyWithBadgesFingerprint"), tryx::runtime_apply_request_codec::runtimeApplyWithBadgesV1Fingerprint(envelope));
    if (mutation == QStringLiteral("missing-fingerprint")) dispatch.remove(QStringLiteral("applyWithBadgesFingerprint"));
    if (mutation == QStringLiteral("wrong-fingerprint")) dispatch.insert(QStringLiteral("applyWithBadgesFingerprint"), QString(64, QLatin1Char('0')));
    if (mutation == QStringLiteral("retry-missing")) {
        dispatch.remove(QStringLiteral("applyWithBadges"));
        dispatch.remove(QStringLiteral("applyWithBadgesFingerprint"));
    }
    manifest.insert(QStringLiteral("inFlightDispatch"), dispatch);
    const auto malformed = QJsonDocument(manifest).toJson(QJsonDocument::Compact);
    QVERIFY(writeAtomicOwnerFile(writer.canonicalManifestPath(), malformed));
    tryx::RetryCacheStore reader(temporary.filePath(QStringLiteral("retry")));
    const auto rejected = reader.load();
    QCOMPARE(rejected.status, tryx::RetryCacheStore::LoadStatus::Invalid);
    QVERIFY(reader.blocksMutations());
    QVERIFY(!rejected.detail.contains(QStringLiteral("Private sentinel")));
    QCOMPARE(readFileBytes(writer.canonicalManifestPath()), malformed);
}

void PrinterProtocolTests::customBadgeRetryRequiresExplicitContinuation() {
    QTemporaryDir temporary;
    QVERIFY(temporary.isValid());
    PrinterOperationCoordinator coordinator;
    coordinator.retryCacheDirectoryOverride_ = temporary.filePath(QStringLiteral("retry"));
    coordinator.retryCacheLoadComplete_ = true;
    tryx::RetryCacheStore::StoredRetryCandidate candidate;
    candidate.operationId = QUuid::createUuid().toString(QUuid::WithoutBraces);
    candidate.dispatchId = QUuid::createUuid().toString(QUuid::WithoutBraces);
    candidate.lineageId = QUuid::createUuid().toString(QUuid::WithoutBraces);
    candidate.productId = 0x1021;
    candidate.deviceIdentity = QStringLiteral("badge-device");
    candidate.deviceGeneration = 7;
    candidate.conversion = mediaConversionForProduct(0x1021);
    candidate.originalRemoteName = QStringLiteral("badge.mp4.h264_2240x1080");
    candidate.retryRemoteName = candidate.originalRemoteName;
    candidate.prepared = {QStringLiteral("prepared-%1.bin").arg(candidate.lineageId), 12, QString(64, QLatin1Char('a'))};
    TryxRuntimeApplyWithBadgesV1 envelope;
    envelope.request.screenMode = QStringLiteral("Full Screen");
    envelope.request.playMode = QStringLiteral("Single");
    envelope.request.ratio = QStringLiteral("2:1");
    envelope.request.replaceOverlay = true;
    envelope.request.settingsBadges = {QStringLiteral("CPU Badge")};
    envelope.badges.primaryCpu = {QStringLiteral("Custom"), QStringLiteral("Durable choice")};
    QVERIFY(tryx::pase_overlay_config::normalizeAndValidatePaseApplyOverlayStyles(&envelope.request));
    candidate.applyWithBadges = envelope;
    auto recovered = coordinator.retryCacheOperationRecord(candidate, 8);
    QVERIFY(!recovered.info.applyAfterUpload);
    QVERIFY(!recovered.updateMetrics);
    QVERIFY(recovered.badgeChoices.has_value());
    QCOMPARE(*recovered.badgeChoices, envelope.badges);
    QCOMPARE(recovered.applyRequest, envelope.request);
    auto finalization = candidate;
    finalization.finalizationOnlyReconciliation = true;
    finalization.outcome = tryx::RetryCacheStore::TerminalOutcome::FinalizationUnknown;
    QVERIFY(!coordinator.retryCacheOperationRecord(finalization, 8).info.applyAfterUpload);
    // The mutable operation surface is not the source of retry intent.
    recovered.badgeChoices->primaryCpu.text = QStringLiteral("Unrelated draft");
    coordinator.operations_.insert(candidate.operationId, recovered);
    coordinator.operationOrder_.append(candidate.operationId);
    coordinator.retryCacheSnapshot_.storeRevision = 4;
    coordinator.retryCacheSnapshot_.retryCandidate = candidate;
    PrinterOperationContext context;
    context.connected = context.printerClassConnected = context.printerEndpointReady = true;
    context.displaySessionActive = context.supportsMediaCatalog = context.supportsDisplayConfiguration = true;
    context.productId = candidate.productId;
    context.generation = 8;
    context.deviceIdentity = QStringLiteral("another-device");
    context.devicePath = QStringLiteral("fixture-endpoint");
    QSignalSpy applySpy(&coordinator, &PrinterOperationCoordinator::requestApplyMediaWithBadgesV1);
    QSignalSpy refreshSpy(&coordinator, &PrinterOperationCoordinator::requestRefreshMedia);
    const QString wrongId = QUuid::createUuid().toString(QUuid::WithoutBraces);
    QCOMPARE(coordinator.retryOperation(context, candidate.operationId, wrongId), wrongId);
    QCOMPARE(coordinator.operationInfo(wrongId).errorCategory, QStringLiteral("DeviceIdentityMismatch"));
    QCOMPARE(refreshSpy.count(), 0);
    context.deviceIdentity = candidate.deviceIdentity;
    const QString retryId = QUuid::createUuid().toString(QUuid::WithoutBraces);
    QCOMPARE(coordinator.retryOperation(context, candidate.operationId, retryId), retryId);
    QCOMPARE(coordinator.retryOperation(context, candidate.operationId, retryId), retryId);
    QVERIFY(coordinator.retryOperation(context, candidate.operationId, candidate.operationId).isEmpty());
    const auto retried = coordinator.operations_.value(retryId);
    QVERIFY(retried.info.applyAfterUpload);
    QVERIFY(retried.updateMetrics);
    QCOMPARE(retried.applyRequest, envelope.request);
    QCOMPARE(*retried.badgeChoices, envelope.badges);
    QCOMPARE(refreshSpy.count(), 1);
    QCOMPARE(applySpy.count(), 0); // Preflight is not itself permission to Apply.
}

void PrinterProtocolTests::retryCacheStorePreservesBadgeContinuationV12() {
    QTemporaryDir temporary;
    QVERIFY(temporary.isValid());
    const QString staging = temporary.filePath(QStringLiteral("prepared.bin"));
    const QByteArray bytes("badge-retry-prepared");
    QVERIFY(writeAtomicOwnerFile(staging, bytes));
    auto input = retryCachePreparedInput(staging, bytes, QStringLiteral("badge-retry"));
    TryxRuntimeApplyWithBadgesV1 envelope;
    envelope.request.screenMode = QStringLiteral("Full Screen");
    envelope.request.ratio = QStringLiteral("2:1");
    envelope.request.playMode = QStringLiteral("Single");
    envelope.request.replaceOverlay = true;
    envelope.request.settingsBadges = {QStringLiteral("CPU Badge")};
    envelope.badges.primaryCpu = {QStringLiteral("Custom"), QStringLiteral("Sentinel C16 retry")};
    QVERIFY(tryx::pase_overlay_config::normalizeAndValidatePaseApplyOverlayStyles(&envelope.request));
    input.applyWithBadges = envelope;
    tryx::RetryCacheStore writer(temporary.filePath(QStringLiteral("retry")));
    const auto persisted = writer.persistPrepared(input);
    QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
    QVERIFY(persisted.snapshot->inFlightDispatch->applyWithBadges.has_value());
    QVERIFY(*persisted.snapshot->inFlightDispatch->applyWithBadges == envelope);
    const auto dispatch = *persisted.snapshot->inFlightDispatch;
    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = dispatch.lineageId;
    expected.dispatchId = dispatch.dispatchId;
    expected.operationId = dispatch.operationId;
    expected.productId = dispatch.productId;
    expected.deviceIdentity = dispatch.deviceIdentity;
    expected.deviceGeneration = dispatch.deviceGeneration;
    const auto armed = writer.armDispatch(*persisted.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));
    QFile shadow(writer.legacyShadowManifestPath());
    QVERIFY(shadow.open(QIODevice::ReadOnly));
    const auto shadowObject = QJsonDocument::fromJson(shadow.readAll()).object();
    QCOMPARE(shadowObject.value(QStringLiteral("version")).toInt(), 12);
    QVERIFY(!shadowObject.value(QStringLiteral("applyAfterUpload")).toBool());
    QCOMPARE(shadowObject.value(QStringLiteral("applyWithBadges")).toObject(),
        tryx::runtime_apply_request_codec::runtimeApplyWithBadgesV1ToJson(envelope));
    tryx::RetryCacheStore restarted(temporary.filePath(QStringLiteral("retry")));
    const auto loaded = restarted.load();
    QCOMPARE(loaded.status, tryx::RetryCacheStore::LoadStatus::NeedsValidation);
    QVERIFY(!loaded.validationRequests.isEmpty());
    tryx::RetryCacheStore::MutationResult validated;
    for (const auto &request : loaded.validationRequests) {
        tryx::RetryCacheStore::ValidationResult result;
        result.token = request.token;
        result.valid = true;
        result.actualSize = request.expectedSize;
        result.actualSha256 = request.expectedSha256;
        result.actualDevice = request.expectedDevice;
        result.actualInode = request.expectedInode;
        validated = restarted.completeValidation(result);
        QVERIFY2(validated.ok(), qPrintable(validated.detail));
    }
    QVERIFY(validated.snapshot->retryCandidate.has_value());
    QVERIFY(validated.snapshot->retryCandidate->applyWithBadges.has_value());
    QVERIFY(*validated.snapshot->retryCandidate->applyWithBadges == envelope);
    QVERIFY(!restarted.releasedV10DowngradeSafety(*validated.snapshot).safe);
    const auto reconnected = restarted.resolveCandidateRecovery(*validated.snapshot, expected,
        tryx::RetryCacheStore::CandidateRecoveryProof::PhysicalReconnectObserved);
    QVERIFY2(reconnected.ok(), qPrintable(reconnected.detail));
    QVERIFY(*reconnected.snapshot->retryCandidate->applyWithBadges == envelope);
    tryx::RetryCacheStore::RetryPreparedInput retry;
    retry.dispatchId = QUuid::createUuid().toString(QUuid::WithoutBraces);
    retry.operationId = QUuid::createUuid().toString(QUuid::WithoutBraces);
    retry.deviceIdentity = input.deviceIdentity;
    retry.deviceGeneration = input.deviceGeneration + 1;
    retry.retryRemoteName = QStringLiteral("badge-retry-2.mp4.h264_2240x1080");
    const auto retried = restarted.beginRetry(*reconnected.snapshot, retry);
    QVERIFY2(retried.ok(), qPrintable(retried.detail));
    QVERIFY(*retried.snapshot->inFlightDispatch->applyWithBadges == envelope);
    expected.dispatchId = retry.dispatchId;
    expected.operationId = retry.operationId;
    expected.deviceGeneration = retry.deviceGeneration;
    const auto retryArmed = restarted.armDispatch(*retried.snapshot, expected);
    QVERIFY2(retryArmed.ok(), qPrintable(retryArmed.detail));
    tryx::RetryCacheStore::RetryableOutcomeInput outcome;
    outcome.outcome = tryx::RetryCacheStore::TerminalOutcome::PartialOrUnknown;
    const auto terminal = restarted.recordRetryableOutcome(*retryArmed.snapshot, expected, outcome);
    QVERIFY2(terminal.ok(), qPrintable(terminal.detail));
    QVERIFY(*terminal.snapshot->retryCandidate->applyWithBadges == envelope);
    const auto cleared = restarted.clearCandidate(*terminal.snapshot, expected);
    QVERIFY2(cleared.ok(), qPrintable(cleared.detail));
}

void PrinterProtocolTests::retryCacheStorePersistsPreparingCanonicalV11() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());

    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    const QString stagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-source.bin"));
    const QByteArray preparedBytes("canonical-v11-prepared-media");
    QVERIFY(writeAtomicOwnerFile(stagingPath, preparedBytes));
    const QString preparedSha256 = QString::fromLatin1(
        QCryptographicHash::hash(
            preparedBytes, QCryptographicHash::Sha256).toHex());

    const auto profile = printerProductProfileForId(0x1021);
    QVERIFY(profile.has_value());

    tryx::RetryCacheStore store(retryDirectory);
    tryx::RetryCacheStore::PersistPreparedInput input;
    input.lineageId = QUuid::createUuid().toString(
        QUuid::WithoutBraces);
    input.dispatchId = QUuid::createUuid().toString(
        QUuid::WithoutBraces);
    input.operationId = QUuid::createUuid().toString(
        QUuid::WithoutBraces);
    input.productId = profile->productId;
    input.conversion =
        tryx::printer_media_identity::printerMediaConversionIdentity(
            *profile);
    input.deviceIdentity = QStringLiteral("pase:test-device");
    input.deviceGeneration = 42;
    input.originalRemoteName =
        QStringLiteral("v11.mp4.h264_2240x1080");
    input.retryRemoteName = input.originalRemoteName;
    input.subject = QStringLiteral("v11.mp4");
    input.prepared.stagingPath = stagingPath;
    input.prepared.expectedSize = preparedBytes.size();
    input.prepared.expectedSha256 = preparedSha256;

    const auto persisted = store.persistPrepared(input);
    QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
    QVERIFY(persisted.snapshot.has_value());
    QVERIFY(!persisted.snapshot->retryCandidate.has_value());
    QVERIFY(persisted.snapshot->inFlightDispatch.has_value());
    const auto &dispatch = *persisted.snapshot->inFlightDispatch;
    QCOMPARE(dispatch.phase,
             tryx::RetryCacheStore::DispatchPhase::Preparing);
    QCOMPARE(dispatch.lineageId, input.lineageId);
    QCOMPARE(dispatch.dispatchId, input.dispatchId);
    QCOMPARE(dispatch.operationId, input.operationId);

    QFile manifestFile(store.canonicalManifestPath());
    QVERIFY(manifestFile.open(QIODevice::ReadOnly));
    const QByteArray manifestBytes = manifestFile.readAll();
    const QJsonDocument document =
        QJsonDocument::fromJson(manifestBytes);
    QVERIFY(document.isObject());
    const QJsonObject manifest = document.object();
    QCOMPARE(manifest.value(QStringLiteral("version")).toInt(),
             tryx::RetryCacheStore::FormatVersion);
    QVERIFY(!manifest.contains(QStringLiteral("retryCandidate")));
    QVERIFY(manifest.value(QStringLiteral("inFlightDispatch")).isObject());

    const QString artifactName = dispatch.prepared.name;
    QCOMPARE(QFileInfo(artifactName).fileName(), artifactName);
    QVERIFY(!artifactName.contains(QLatin1Char('/')));
    const QString canonicalArtifactPath =
        QDir(store.canonicalDirectory()).filePath(artifactName);
    QFile canonicalArtifact(canonicalArtifactPath);
    QVERIFY(canonicalArtifact.open(QIODevice::ReadOnly));
    QCOMPARE(canonicalArtifact.readAll(), preparedBytes);
    QCOMPARE(dispatch.prepared.size,
             static_cast<qint64>(preparedBytes.size()));
    QCOMPARE(dispatch.prepared.sha256, preparedSha256);
    QVERIFY(!manifestBytes.contains(stagingPath.toUtf8()));
    QVERIFY(!manifestBytes.contains("sourcePath"));
    QVERIFY(!QFileInfo::exists(store.legacyShadowManifestPath()));
    QCOMPARE(QDir(retryDirectory).entryList(
                 {QStringLiteral("shadow-*")}, QDir::Files),
             QStringList{});
}

void PrinterProtocolTests::
retryCacheSplitPreparationPersistsExactGeometry() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("split-prepared-media"));
    const QString stagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("split-prepared.bin"));
    const QByteArray preparedBytes(
        "canonical-v11-split-prepared-media");
    QVERIFY(writeAtomicOwnerFile(stagingPath, preparedBytes));

    auto input = retryCachePreparedInput(
        stagingPath, preparedBytes,
        QStringLiteral("split-v11"));
    input.conversion =
        QStringLiteral("h264-yuv420p-1120x1080-30fps");
    input.originalRemoteName =
        QStringLiteral("split-v11.mp4.h264_1120x1080");
    input.retryRemoteName = input.originalRemoteName;

    tryx::RetryCacheStore store(retryDirectory);
    auto mismatched = input;
    mismatched.originalRemoteName =
        QStringLiteral("split-v11.mp4.h264_2240x1080");
    QCOMPARE(store.persistPrepared(mismatched).code,
             tryx::RetryCacheStore::ErrorCode::InvalidInput);

    const auto persisted = store.persistPrepared(input);
    QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
    QVERIFY(persisted.snapshot.has_value());
    QVERIFY(persisted.snapshot->inFlightDispatch.has_value());
    const auto dispatch =
        *persisted.snapshot->inFlightDispatch;
    QCOMPARE(dispatch.conversion, input.conversion);
    QCOMPARE(dispatch.retryRemoteName, input.retryRemoteName);

    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = dispatch.lineageId;
    expected.dispatchId = dispatch.dispatchId;
    expected.operationId = dispatch.operationId;
    expected.productId = dispatch.productId;
    expected.deviceIdentity = dispatch.deviceIdentity;
    expected.deviceGeneration = dispatch.deviceGeneration;
    const auto armed = store.armDispatch(
        *persisted.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));

    QFile shadow(store.legacyShadowManifestPath());
    QVERIFY(shadow.open(QIODevice::ReadOnly));
    const QJsonObject shadowObject =
        QJsonDocument::fromJson(shadow.readAll()).object();
    QCOMPARE(shadowObject.value(QStringLiteral("version")).toInt(), 10);
    QCOMPARE(shadowObject.value(QStringLiteral("conversion")).toString(),
             input.conversion);
    QCOMPARE(shadowObject.value(QStringLiteral("retryRemoteName")).toString(),
             input.retryRemoteName);
    shadow.close();

    const QString canonicalArtifact =
        QDir(store.canonicalDirectory()).filePath(
            dispatch.prepared.name);
    QVERIFY(QFile::remove(store.canonicalManifestPath()));
    QVERIFY(QFile::remove(canonicalArtifact));

    tryx::RetryCacheStore restarted(retryDirectory);
    const auto loaded = restarted.load();
    QVERIFY2(loaded.status ==
                 tryx::RetryCacheStore::LoadStatus::NeedsValidation,
             qPrintable(loaded.detail));
    QVERIFY(!loaded.validationRequests.isEmpty());
    tryx::RetryCacheStore::MutationResult validated;
    for (const auto &request : loaded.validationRequests) {
        tryx::RetryCacheStore::ValidationResult result;
        result.token = request.token;
        result.valid = true;
        result.actualSize = request.expectedSize;
        result.actualSha256 = request.expectedSha256;
        result.actualDevice = request.expectedDevice;
        result.actualInode = request.expectedInode;
        validated = restarted.completeValidation(result);
        QVERIFY2(validated.ok(), qPrintable(validated.detail));
    }
    QVERIFY(validated.snapshot.has_value());
    const auto *loadedDispatch =
        validated.snapshot->inFlightDispatch
            ? &*validated.snapshot->inFlightDispatch
            : nullptr;
    const auto *loadedCandidate =
        validated.snapshot->retryCandidate
            ? &*validated.snapshot->retryCandidate
            : nullptr;
    QVERIFY(loadedDispatch || loadedCandidate);
    QCOMPARE(loadedDispatch ? loadedDispatch->conversion
                            : loadedCandidate->conversion,
             input.conversion);
    QCOMPARE(loadedDispatch ? loadedDispatch->retryRemoteName
                            : loadedCandidate->retryRemoteName,
             input.retryRemoteName);
}

void PrinterProtocolTests::
retryCacheReleasedV10DowngradeGateIsExact() {
    {
        QTemporaryDir temporaryDirectory;
        QVERIFY(temporaryDirectory.isValid());
        tryx::RetryCacheStore emptyStore(
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("missing-retry-cache")));
        const auto loaded = emptyStore.load();
        QCOMPARE(loaded.status,
                 tryx::RetryCacheStore::LoadStatus::Missing);
        const auto safe =
            emptyStore.releasedV10DowngradeSafety({});
        QVERIFY(safe.safe);
        QCOMPARE(safe.status, QStringLiteral("SafeEmpty"));
    }

    {
        QTemporaryDir temporaryDirectory;
        QVERIFY(temporaryDirectory.isValid());
        const QString retryDirectory =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("full-candidate"));
        RetryCandidateFixture fixture;
        QString detail;
        QVERIFY2(createRetryCandidateFixture(
                     temporaryDirectory.path(), retryDirectory,
                     QByteArray("full-downgrade-candidate"),
                     QStringLiteral("full-downgrade"),
                     &fixture, &detail),
                 qPrintable(detail));
        const auto safe = fixture.store
            ->releasedV10DowngradeSafety(fixture.snapshot);
        QVERIFY(safe.safe);
        QCOMPARE(safe.status, QStringLiteral("SafeFullRetry"));

        auto changedSnapshot = fixture.snapshot;
        ++changedSnapshot.storeRevision;
        const auto changed = fixture.store
            ->releasedV10DowngradeSafety(changedSnapshot);
        QVERIFY(!changed.safe);
        QCOMPARE(changed.status,
                 QStringLiteral("BlockedSnapshotChanged"));
    }

    {
        QTemporaryDir temporaryDirectory;
        QVERIFY(temporaryDirectory.isValid());
        const QString retryDirectory =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("tampered-full-candidate"));
        RetryCandidateFixture fixture;
        QString detail;
        QVERIFY2(createRetryCandidateFixture(
                     temporaryDirectory.path(), retryDirectory,
                     QByteArray("tampered-full-downgrade-candidate"),
                     QStringLiteral("tampered-full-downgrade"),
                     &fixture, &detail),
                 qPrintable(detail));
        QFile shadow(fixture.store->legacyShadowManifestPath());
        QVERIFY(shadow.open(QIODevice::WriteOnly | QIODevice::Truncate));
        QCOMPARE(shadow.write(QByteArrayLiteral("{}")), qint64{2});
        shadow.close();
        const auto blocked = fixture.store
            ->releasedV10DowngradeSafety(fixture.snapshot);
        QVERIFY(!blocked.safe);
        QCOMPARE(blocked.status,
                 QStringLiteral("BlockedFilesystemState"));
    }

    {
        QTemporaryDir temporaryDirectory;
        QVERIFY(temporaryDirectory.isValid());
        const QString retryDirectory =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("in-flight-full"));
        const QString stagingPath =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("in-flight-full.bin"));
        const QByteArray preparedBytes("in-flight-full-candidate");
        QVERIFY(writeAtomicOwnerFile(stagingPath, preparedBytes));
        const auto input = retryCachePreparedInput(
            stagingPath, preparedBytes,
            QStringLiteral("in-flight-full"));
        tryx::RetryCacheStore store(retryDirectory);
        const auto persisted = store.persistPrepared(input);
        QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
        const auto preparing = store.releasedV10DowngradeSafety(
            *persisted.snapshot);
        QVERIFY(!preparing.safe);
        QCOMPARE(preparing.status,
                 QStringLiteral("BlockedInFlightDispatch"));

        tryx::RetryCacheStore::ExpectedDispatch expected;
        expected.lineageId = input.lineageId;
        expected.dispatchId = input.dispatchId;
        expected.operationId = input.operationId;
        expected.productId = input.productId;
        expected.deviceIdentity = input.deviceIdentity;
        expected.deviceGeneration = input.deviceGeneration;
        const auto armed = store.armDispatch(
            *persisted.snapshot, expected);
        QVERIFY2(armed.ok(), qPrintable(armed.detail));
        const auto dispatchArmed =
            store.releasedV10DowngradeSafety(*armed.snapshot);
        QVERIFY(!dispatchArmed.safe);
        QCOMPARE(dispatchArmed.status,
                 QStringLiteral("BlockedInFlightDispatch"));
    }

    {
        QTemporaryDir temporaryDirectory;
        QVERIFY(temporaryDirectory.isValid());
        const QString retryDirectory =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("split-candidate"));
        const QString stagingPath =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("split-candidate.bin"));
        const QByteArray preparedBytes("split-downgrade-candidate");
        QVERIFY(writeAtomicOwnerFile(stagingPath, preparedBytes));
        auto input = retryCachePreparedInput(
            stagingPath, preparedBytes,
            QStringLiteral("split-downgrade-gate"));
        input.conversion =
            QStringLiteral("h264-yuv420p-1120x1080-30fps");
        input.originalRemoteName = QStringLiteral(
            "split-downgrade-gate.mp4.h264_1120x1080");
        input.retryRemoteName = input.originalRemoteName;
        tryx::RetryCacheStore store(retryDirectory);
        const auto persisted = store.persistPrepared(input);
        QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
        tryx::RetryCacheStore::ExpectedDispatch expected;
        expected.lineageId = input.lineageId;
        expected.dispatchId = input.dispatchId;
        expected.operationId = input.operationId;
        expected.productId = input.productId;
        expected.deviceIdentity = input.deviceIdentity;
        expected.deviceGeneration = input.deviceGeneration;
        const auto armed = store.armDispatch(
            *persisted.snapshot, expected);
        QVERIFY2(armed.ok(), qPrintable(armed.detail));
        tryx::RetryCacheStore::RetryableOutcomeInput outcome;
        outcome.outcome = tryx::RetryCacheStore::TerminalOutcome::
            PartialOrUnknown;
        outcome.primaryErrorCategory =
            QStringLiteral("PartialOrUnknown");
        outcome.primaryErrorMessage =
            QStringLiteral("Split dispatch outcome is unknown");
        const auto recorded = store.recordRetryableOutcome(
            *armed.snapshot, expected, outcome);
        QVERIFY2(recorded.ok(), qPrintable(recorded.detail));
        QVERIFY(recorded.snapshot->retryCandidate.has_value());
        const auto blocked = store.releasedV10DowngradeSafety(
            *recorded.snapshot);
        QVERIFY(!blocked.safe);
        QCOMPARE(blocked.status,
                 QStringLiteral("BlockedIncompatibleGeometry"));
    }

    {
        QTemporaryDir temporaryDirectory;
        QVERIFY(temporaryDirectory.isValid());
        const QString retryDirectory =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("cleared-candidate"));
        RetryCandidateFixture fixture;
        QString detail;
        QVERIFY2(createRetryCandidateFixture(
                     temporaryDirectory.path(), retryDirectory,
                     QByteArray("cleared-full-downgrade-candidate"),
                     QStringLiteral("cleared-full-downgrade"),
                     &fixture, &detail),
                 qPrintable(detail));
        const auto candidate = *fixture.snapshot.retryCandidate;
        tryx::RetryCacheStore::ExpectedDispatch expected;
        expected.lineageId = candidate.lineageId;
        expected.dispatchId = candidate.dispatchId;
        expected.operationId = candidate.operationId;
        expected.productId = candidate.productId;
        expected.deviceIdentity = candidate.deviceIdentity;
        expected.deviceGeneration = candidate.deviceGeneration;
        const auto cleared = fixture.store->clearCandidate(
            fixture.snapshot, expected);
        QVERIFY2(cleared.ok(), qPrintable(cleared.detail));
        QVERIFY(cleared.snapshot.has_value());
        QVERIFY(!cleared.snapshot->retryCandidate.has_value());
        QVERIFY(!cleared.snapshot->inFlightDispatch.has_value());
        QVERIFY(cleared.snapshot->cleanupPending.isEmpty());
        const auto safe = fixture.store
            ->releasedV10DowngradeSafety(*cleared.snapshot);
        QVERIFY(safe.safe);
        QCOMPARE(safe.status, QStringLiteral("SafeEmpty"));
    }
}

void PrinterProtocolTests::
retryCacheSplitShadowCleanupPreservesCanonicalV11() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("split-downgrade"));
    const QString stagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("split-downgrade.bin"));
    const QByteArray preparedBytes(
        "split-shadow-must-not-be-retried-by-v10");
    QVERIFY(writeAtomicOwnerFile(stagingPath, preparedBytes));

    auto input = retryCachePreparedInput(
        stagingPath, preparedBytes,
        QStringLiteral("split-downgrade"));
    input.conversion =
        QStringLiteral("h264-yuv420p-1120x1080-30fps");
    input.originalRemoteName =
        QStringLiteral("split-downgrade.mp4.h264_1120x1080");
    input.retryRemoteName = input.originalRemoteName;

    auto writer =
        std::make_unique<tryx::RetryCacheStore>(retryDirectory);
    const auto persisted = writer->persistPrepared(input);
    QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
    QVERIFY(persisted.snapshot.has_value());
    QVERIFY(persisted.snapshot->inFlightDispatch.has_value());
    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = input.lineageId;
    expected.dispatchId = input.dispatchId;
    expected.operationId = input.operationId;
    expected.productId = input.productId;
    expected.deviceIdentity = input.deviceIdentity;
    expected.deviceGeneration = input.deviceGeneration;
    const auto armed = writer->armDispatch(
        *persisted.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));
    QVERIFY(armed.snapshot.has_value());
    QVERIFY(armed.snapshot->inFlightDispatch.has_value());

    const QString canonicalManifestPath =
        writer->canonicalManifestPath();
    const QString canonicalPreparedPath =
        QDir(writer->canonicalDirectory()).filePath(
            armed.snapshot->inFlightDispatch->prepared.name);
    const QString shadowManifestPath =
        writer->legacyShadowManifestPath();
    QFile shadowFile(shadowManifestPath);
    QVERIFY(shadowFile.open(QIODevice::ReadOnly));
    const QJsonObject shadow = QJsonDocument::fromJson(
        shadowFile.readAll()).object();
    shadowFile.close();
    const QString shadowPreparedPath = shadow.value(
        QStringLiteral("preparedPath")).toString();
    QCOMPARE(shadow.value(QStringLiteral("version")).toInt(), 10);
    QCOMPARE(shadow.value(QStringLiteral("conversion")).toString(),
             input.conversion);
    QVERIFY(QFileInfo::exists(shadowPreparedPath));
    writer.reset();

    ReleasedV10RetryCacheConsumer releasedV10(retryDirectory);
    QString detail;
    QVERIFY(!releasedV10.load(&detail));
    QVERIFY(detail.contains(QStringLiteral("rejected")));
    QVERIFY(!QFileInfo::exists(shadowManifestPath));
    QVERIFY(!QFileInfo::exists(shadowPreparedPath));
    QVERIFY(QFileInfo::exists(canonicalManifestPath));
    QVERIFY(QFileInfo::exists(canonicalPreparedPath));

    tryx::RetryCacheStore restarted(retryDirectory);
    const auto fenced = restarted.load();
    QVERIFY2(fenced.status == tryx::RetryCacheStore::LoadStatus::Loaded,
             qPrintable(fenced.detail));
    QVERIFY(fenced.snapshot.has_value());
    QVERIFY(fenced.snapshot->inFlightDispatch.has_value());
    QCOMPARE(fenced.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::ShadowMissingFence);
    QCOMPARE(fenced.snapshot->inFlightDispatch->conversion,
             input.conversion);
    QVERIFY(fenced.snapshot->inFlightDispatch
                ->requiresDeviceRecovery);
    QVERIFY(fenced.snapshot->inFlightDispatch
                ->requiresNewRemoteName);
}

void PrinterProtocolTests::retryCacheStorePersistsPreparingThumbnail() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    const QString preparedPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-with-thumbnail.bin"));
    const QString thumbnailPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-thumbnail.png"));
    const QByteArray preparedBytes(
        "canonical-v11-prepared-with-thumbnail");
    const QByteArray thumbnailBytes(
        "canonical-v11-thumbnail-bytes");
    QVERIFY(writeAtomicOwnerFile(preparedPath, preparedBytes));
    QVERIFY(writeAtomicOwnerFile(thumbnailPath, thumbnailBytes));

    tryx::RetryCacheStore store(retryDirectory);
    auto input = retryCachePreparedInput(
        preparedPath, preparedBytes,
        QStringLiteral("fresh-thumbnail"));
    input.thumbnail =
        tryx::RetryCacheStore::PreparedArtifactInput{
            thumbnailPath,
            static_cast<qint64>(thumbnailBytes.size()),
            QString::fromLatin1(
                QCryptographicHash::hash(
                    thumbnailBytes, QCryptographicHash::Sha256)
                    .toHex()),
        };

    const auto persisted = store.persistPrepared(input);
    QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
    QVERIFY(persisted.snapshot.has_value());
    QVERIFY(persisted.snapshot->inFlightDispatch.has_value());
    const auto &dispatch =
        *persisted.snapshot->inFlightDispatch;
    QVERIFY(dispatch.thumbnail.has_value());
    const QString canonicalThumbnailPath =
        QDir(store.canonicalDirectory()).filePath(
            dispatch.thumbnail->name);
    QFile canonicalThumbnail(canonicalThumbnailPath);
    QVERIFY(canonicalThumbnail.open(QIODevice::ReadOnly));
    QCOMPARE(canonicalThumbnail.readAll(), thumbnailBytes);
    QCOMPARE(dispatch.thumbnail->size,
             static_cast<qint64>(thumbnailBytes.size()));

    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = dispatch.lineageId;
    expected.dispatchId = dispatch.dispatchId;
    expected.operationId = dispatch.operationId;
    expected.productId = dispatch.productId;
    expected.deviceIdentity = dispatch.deviceIdentity;
    expected.deviceGeneration = dispatch.deviceGeneration;
    const auto armed = store.armDispatch(
        *persisted.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));
    const QString shadowThumbnailPath =
        QDir(retryDirectory).filePath(
            QStringLiteral("shadow-%1-thumbnail.bin")
                .arg(dispatch.lineageId));
    QFile shadowThumbnail(shadowThumbnailPath);
    QVERIFY(shadowThumbnail.open(QIODevice::ReadOnly));
    QCOMPARE(shadowThumbnail.readAll(), thumbnailBytes);

    QFile shadowManifest(store.legacyShadowManifestPath());
    QVERIFY(shadowManifest.open(QIODevice::ReadOnly));
    const QByteArray shadowBytes = shadowManifest.readAll();
    QVERIFY(shadowBytes.contains(
        QFile::encodeName(shadowThumbnailPath)));
    QVERIFY(!shadowBytes.contains(thumbnailPath.toUtf8()));
}

void PrinterProtocolTests::
    retryCacheStorePersistsIndependentDispatchAlongsideCandidate() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));

    const QByteArray candidateBytes("durable-candidate-a");
    const QString candidateStagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("candidate-a.bin"));
    QVERIFY(writeAtomicOwnerFile(candidateStagingPath, candidateBytes));
    const auto candidateInput = retryCachePreparedInput(
        candidateStagingPath, candidateBytes,
        QStringLiteral("candidate-a"));

    tryx::RetryCacheStore writer(retryDirectory);
    const auto prepared = writer.persistPrepared(candidateInput);
    QVERIFY2(prepared.ok(), qPrintable(prepared.detail));
    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = candidateInput.lineageId;
    expected.dispatchId = candidateInput.dispatchId;
    expected.operationId = candidateInput.operationId;
    expected.productId = candidateInput.productId;
    expected.deviceIdentity = candidateInput.deviceIdentity;
    expected.deviceGeneration = candidateInput.deviceGeneration;
    QVERIFY2(writer.armDispatch(expected).ok(),
             "candidate A must reach its durable armed barrier");

    tryx::RetryCacheStore restarted(retryDirectory);
    const auto pending = restarted.load();
    QCOMPARE(pending.status,
             tryx::RetryCacheStore::LoadStatus::NeedsValidation);
    QVERIFY(!pending.validationRequests.isEmpty());
    tryx::RetryCacheStore::MutationResult recovered;
    for (const auto &request : pending.validationRequests) {
        tryx::RetryCacheStore::ValidationResult result;
        result.token = request.token;
        result.valid = true;
        result.actualSize = request.expectedSize;
        result.actualSha256 = request.expectedSha256;
        result.actualDevice = request.expectedDevice;
        result.actualInode = request.expectedInode;
        recovered = restarted.completeValidation(result);
        QVERIFY2(recovered.ok(), qPrintable(recovered.detail));
    }
    QVERIFY(recovered.snapshot.has_value());
    QVERIFY(recovered.snapshot->retryCandidate.has_value());
    QVERIFY(!recovered.snapshot->inFlightDispatch.has_value());
    const auto candidateBefore = *recovered.snapshot->retryCandidate;
    const quint64 revisionBefore = recovered.snapshot->storeRevision;

    QFile shadowBeforeFile(restarted.legacyShadowManifestPath());
    QVERIFY(shadowBeforeFile.open(QIODevice::ReadOnly));
    const QByteArray shadowBefore = shadowBeforeFile.readAll();
    shadowBeforeFile.close();
    struct stat shadowManifestBefore {};
    QCOMPARE(::stat(
                 QFile::encodeName(restarted.legacyShadowManifestPath())
                     .constData(),
                 &shadowManifestBefore),
             0);
    const QString candidateArtifactPath =
        QDir(restarted.canonicalDirectory()).filePath(
            candidateBefore.prepared.name);
    struct stat candidateArtifactBefore {};
    QCOMPARE(::stat(QFile::encodeName(candidateArtifactPath).constData(),
                    &candidateArtifactBefore),
             0);

    const QByteArray dispatchBytes("independent-dispatch-b");
    const QString dispatchStagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("dispatch-b.bin"));
    QVERIFY(writeAtomicOwnerFile(dispatchStagingPath, dispatchBytes));
    const auto dispatchInput = retryCachePreparedInput(
        dispatchStagingPath, dispatchBytes,
        QStringLiteral("dispatch-b"));

    const auto persisted = restarted.persistPrepared(
        *recovered.snapshot, dispatchInput);
    QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
    QVERIFY(persisted.snapshot.has_value());
    QCOMPARE(persisted.snapshot->storeRevision, revisionBefore + 1);
    QVERIFY(persisted.snapshot->retryCandidate.has_value());
    QVERIFY(persisted.snapshot->inFlightDispatch.has_value());
    QCOMPARE(persisted.snapshot->retryCandidate->lineageId,
             candidateBefore.lineageId);
    QCOMPARE(persisted.snapshot->retryCandidate->prepared.name,
             candidateBefore.prepared.name);
    QCOMPARE(persisted.snapshot->inFlightDispatch->lineageId,
             dispatchInput.lineageId);
    QCOMPARE(persisted.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::Preparing);

    QFile shadowAfterFile(restarted.legacyShadowManifestPath());
    QVERIFY(shadowAfterFile.open(QIODevice::ReadOnly));
    QCOMPARE(shadowAfterFile.readAll(), shadowBefore);
    struct stat shadowManifestAfter {};
    QCOMPARE(::stat(
                 QFile::encodeName(restarted.legacyShadowManifestPath())
                     .constData(),
                 &shadowManifestAfter),
             0);
    QCOMPARE(shadowManifestAfter.st_dev, shadowManifestBefore.st_dev);
    QCOMPARE(shadowManifestAfter.st_ino, shadowManifestBefore.st_ino);

    struct stat candidateArtifactAfter {};
    QCOMPARE(::stat(QFile::encodeName(candidateArtifactPath).constData(),
                    &candidateArtifactAfter),
             0);
    QCOMPARE(candidateArtifactAfter.st_dev,
             candidateArtifactBefore.st_dev);
    QCOMPARE(candidateArtifactAfter.st_ino,
             candidateArtifactBefore.st_ino);
    const QString dispatchArtifactPath =
        QDir(restarted.canonicalDirectory()).filePath(
            persisted.snapshot->inFlightDispatch->prepared.name);
    QVERIFY(QFileInfo::exists(dispatchArtifactPath));
    QVERIFY(dispatchArtifactPath != candidateArtifactPath);

    tryx::RetryCacheStore afterPreparing(retryDirectory);
    const auto reloaded = afterPreparing.load();
    QCOMPARE(reloaded.status,
             tryx::RetryCacheStore::LoadStatus::NeedsValidation);
    QVERIFY(!reloaded.validationRequests.isEmpty());
    QVERIFY(reloaded.snapshot.has_value());
    QVERIFY(reloaded.snapshot->retryCandidate.has_value());
    QVERIFY(!reloaded.snapshot->inFlightDispatch.has_value());
    QVERIFY(!QFileInfo::exists(dispatchArtifactPath));
    QVERIFY(QFileInfo::exists(candidateArtifactPath));

    QFile shadowReloadedFile(afterPreparing.legacyShadowManifestPath());
    QVERIFY(shadowReloadedFile.open(QIODevice::ReadOnly));
    QCOMPARE(shadowReloadedFile.readAll(), shadowBefore);
    struct stat shadowManifestReloaded {};
    QCOMPARE(::stat(
                 QFile::encodeName(afterPreparing
                     .legacyShadowManifestPath()).constData(),
                 &shadowManifestReloaded),
             0);
    QCOMPARE(shadowManifestReloaded.st_dev,
             shadowManifestBefore.st_dev);
    QCOMPARE(shadowManifestReloaded.st_ino,
             shadowManifestBefore.st_ino);

    tryx::RetryCacheStore::MutationResult validated;
    for (const auto &request : reloaded.validationRequests) {
        tryx::RetryCacheStore::ValidationResult result;
        result.token = request.token;
        result.valid = true;
        result.actualSize = request.expectedSize;
        result.actualSha256 = request.expectedSha256;
        result.actualDevice = request.expectedDevice;
        result.actualInode = request.expectedInode;
        validated = afterPreparing.completeValidation(result);
        QVERIFY2(validated.ok(), qPrintable(validated.detail));
    }
    QVERIFY(validated.snapshot.has_value());
    QVERIFY(validated.snapshot->retryCandidate.has_value());
    QVERIFY(!validated.snapshot->inFlightDispatch.has_value());
    QCOMPARE(validated.snapshot->retryCandidate->lineageId,
             candidateBefore.lineageId);
}

void PrinterProtocolTests::
    retryCacheStoreArmsIndependentDispatchWithoutRetiringCandidate() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    RetryCandidateFixture candidate;
    QString detail;
    QVERIFY2(createRetryCandidateFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("candidate-a-before-independent-arm"),
                 QStringLiteral("arm-candidate-a"), &candidate,
                 &detail),
             qPrintable(detail));
    QVERIFY(candidate.store);

    const QByteArray dispatchBytes(
        "independent-dispatch-b-before-arm");
    const QString dispatchStagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("arm-dispatch-b.bin"));
    QVERIFY(writeAtomicOwnerFile(dispatchStagingPath, dispatchBytes));
    const auto dispatchInput = retryCachePreparedInput(
        dispatchStagingPath, dispatchBytes,
        QStringLiteral("arm-dispatch-b"));
    const auto prepared = candidate.store->persistPrepared(
        candidate.snapshot, dispatchInput);
    QVERIFY2(prepared.ok(), qPrintable(prepared.detail));
    QVERIFY(prepared.snapshot.has_value());
    const quint64 preparingRevision =
        prepared.snapshot->storeRevision;

    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = dispatchInput.lineageId;
    expected.dispatchId = dispatchInput.dispatchId;
    expected.operationId = dispatchInput.operationId;
    expected.productId = dispatchInput.productId;
    expected.deviceIdentity = dispatchInput.deviceIdentity;
    expected.deviceGeneration = dispatchInput.deviceGeneration;
    const auto armed = candidate.store->armDispatch(
        *prepared.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));
    QVERIFY(armed.snapshot.has_value());
    QCOMPARE(armed.snapshot->storeRevision,
             preparingRevision + 1);
    QVERIFY(armed.snapshot->retryCandidate.has_value());
    QVERIFY(armed.snapshot->inFlightDispatch.has_value());
    QCOMPARE(armed.snapshot->retryCandidate->lineageId,
             candidate.snapshot.retryCandidate->lineageId);
    QCOMPARE(armed.snapshot->inFlightDispatch->lineageId,
             dispatchInput.lineageId);
    QCOMPARE(armed.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::DispatchArmed);
    QVERIFY(QFileInfo::exists(candidate.canonicalArtifactPath));

    QFile rootShadow(candidate.store->legacyShadowManifestPath());
    QVERIFY(rootShadow.open(QIODevice::ReadOnly));
    const QByteArray armedShadowBytes = rootShadow.readAll();
    QVERIFY(armedShadowBytes != candidate.shadowManifestBytes);
    const QJsonObject armedShadow =
        QJsonDocument::fromJson(armedShadowBytes).object();
    QCOMPARE(armedShadow.value(QStringLiteral("operationId")).toString(),
             dispatchInput.operationId);
    QCOMPARE(armedShadow
                 .value(QStringLiteral("terminalOutcome"))
                 .toString(),
             QStringLiteral("PartialOrUnknown"));

    const QString suspendedDirectory =
        QDir(retryDirectory).filePath(
            QStringLiteral("suspended-v10"));
    QVERIFY(QFileInfo(suspendedDirectory).isDir());
    QFile protectedManifest(
        QDir(suspendedDirectory).filePath(
            QStringLiteral("retry-manifest.json")));
    QVERIFY(protectedManifest.open(QIODevice::ReadOnly));
    QCOMPARE(protectedManifest.readAll(),
             candidate.shadowManifestBytes);
    QVERIFY(QFileInfo::exists(
        QDir(suspendedDirectory).filePath(
            QStringLiteral("prepared-media"))));
    QVERIFY(QFileInfo::exists(
        QDir(suspendedDirectory).filePath(
            QStringLiteral("state.json"))));

    tryx::RetryCacheStore restarted(retryDirectory);
    const auto load = restarted.load();
    QVERIFY2(
        load.status ==
            tryx::RetryCacheStore::LoadStatus::NeedsValidation,
        qPrintable(load.detail));
    QVERIFY(load.snapshot.has_value());
    QVERIFY(load.snapshot->retryCandidate.has_value());
    QVERIFY(load.snapshot->inFlightDispatch.has_value());
    QCOMPARE(load.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::DispatchArmed);
    QSet<QString> validationLineages;
    for (const auto &request : load.validationRequests) {
        validationLineages.insert(request.lineageId);
    }
    QVERIFY(validationLineages.contains(
        candidate.snapshot.retryCandidate->lineageId));
    QVERIFY(validationLineages.contains(dispatchInput.lineageId));

    tryx::RetryCacheStore::MutationResult recovered;
    for (const auto &request : load.validationRequests) {
        tryx::RetryCacheStore::ValidationResult result;
        result.token = request.token;
        result.valid = true;
        result.actualSize = request.expectedSize;
        result.actualSha256 = request.expectedSha256;
        result.actualDevice = request.expectedDevice;
        result.actualInode = request.expectedInode;
        recovered = restarted.completeValidation(result);
        QVERIFY2(recovered.ok(), qPrintable(recovered.detail));
    }
    QVERIFY(recovered.snapshot.has_value());
    QVERIFY(recovered.snapshot->retryCandidate.has_value());
    QVERIFY(recovered.snapshot->inFlightDispatch.has_value());
    QCOMPARE(recovered.snapshot->retryCandidate->lineageId,
             candidate.snapshot.retryCandidate->lineageId);
    QCOMPARE(recovered.snapshot->inFlightDispatch->lineageId,
             dispatchInput.lineageId);
    QCOMPARE(recovered.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::PartialOrUnknown);
    QVERIFY(recovered.snapshot->inFlightDispatch
                ->requiresDeviceRecovery);
    QVERIFY(recovered.snapshot->inFlightDispatch
                ->requiresNewRemoteName);

    QFile canonicalAfterRecovery(restarted.canonicalManifestPath());
    QVERIFY(canonicalAfterRecovery.open(QIODevice::ReadOnly));
    const QJsonObject recoveredManifest = QJsonDocument::fromJson(
        canonicalAfterRecovery.readAll()).object();
    QVERIFY(recoveredManifest.value(
        QStringLiteral("retryCandidate")).isObject());
    QCOMPARE(recoveredManifest
                 .value(QStringLiteral("inFlightDispatch"))
                 .toObject()
                 .value(QStringLiteral("phase"))
                 .toString(),
             QStringLiteral("PartialOrUnknown"));
}

void PrinterProtocolTests::retryCacheStoreRetiresSingleLocalCommit() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    ArmedSingleDispatchFixture fixture;
    QString detail;
    QVERIFY2(createArmedSingleDispatchFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("single-local-commit"),
                 QStringLiteral("single-local-commit"),
                 &fixture, &detail),
             qPrintable(detail));
    const auto armedDispatch =
        *fixture.armedSnapshot.inFlightDispatch;
    const auto pending = fixture.store->beginLocalCommit(
        fixture.armedSnapshot, fixture.expected,
        verifiedUserArtifact(
            armedDispatch.retryRemoteName,
            armedDispatch.prepared.size));
    QVERIFY2(pending.ok(), qPrintable(pending.detail));
    QVERIFY(pending.snapshot.has_value());
    QCOMPARE(pending.snapshot->storeRevision,
             fixture.armedSnapshot.storeRevision + 1);
    QVERIFY(!pending.snapshot->retryCandidate.has_value());
    QVERIFY(pending.snapshot->inFlightDispatch.has_value());
    QCOMPARE(pending.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::
                 LocalCommitPending);
    QCOMPARE(pending.snapshot->inFlightDispatch->operationId,
             fixture.expected.operationId);
    QVERIFY(QFileInfo::exists(fixture.canonicalArtifactPath));
    QVERIFY(QFileInfo::exists(fixture.shadowArtifactPath));

    const auto retired = fixture.store->retireDispatch(
        *pending.snapshot, fixture.expected,
        tryx::RetryCacheStore::DispatchRetirement::
            AcknowledgedSuccess);
    QVERIFY2(retired.ok(), qPrintable(retired.detail));
    QVERIFY(retired.snapshot.has_value());
    QVERIFY(!retired.snapshot->retryCandidate.has_value());
    QVERIFY(!retired.snapshot->inFlightDispatch.has_value());
    QVERIFY(retired.snapshot->cleanupPending.isEmpty());
    QVERIFY(!QFileInfo::exists(fixture.canonicalArtifactPath));
    QVERIFY(!QFileInfo::exists(fixture.shadowArtifactPath));
    QVERIFY(!QFileInfo::exists(
        fixture.store->legacyShadowManifestPath()));
    QVERIFY(!QFileInfo(
                 QDir(retryDirectory).filePath(
                     QStringLiteral("suspended-v10")))
                 .exists());
}

void PrinterProtocolTests::
    retryCacheStoreRetiresIndependentLocalCommit() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    RetryCandidateFixture candidate;
    QString detail;
    QVERIFY2(createRetryCandidateFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("independent-local-commit-a"),
                 QStringLiteral("independent-local-a"),
                 &candidate, &detail),
             qPrintable(detail));
    const auto candidateBefore =
        *candidate.snapshot.retryCandidate;

    const QByteArray dispatchBytes(
        "independent-local-commit-b");
    const QString stagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("independent-local-b.bin"));
    QVERIFY(writeAtomicOwnerFile(stagingPath, dispatchBytes));
    const auto dispatchInput = retryCachePreparedInput(
        stagingPath, dispatchBytes,
        QStringLiteral("independent-local-b"));
    const auto prepared = candidate.store->persistPrepared(
        candidate.snapshot, dispatchInput);
    QVERIFY2(prepared.ok(), qPrintable(prepared.detail));
    QVERIFY(prepared.snapshot.has_value());
    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = dispatchInput.lineageId;
    expected.dispatchId = dispatchInput.dispatchId;
    expected.operationId = dispatchInput.operationId;
    expected.productId = dispatchInput.productId;
    expected.deviceIdentity = dispatchInput.deviceIdentity;
    expected.deviceGeneration = dispatchInput.deviceGeneration;
    const auto armed = candidate.store->armDispatch(
        *prepared.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));
    QVERIFY(armed.snapshot.has_value());
    const auto dispatch = *armed.snapshot->inFlightDispatch;
    const QString dispatchCanonicalPath =
        QDir(candidate.store->canonicalDirectory()).filePath(
            dispatch.prepared.name);
    const QString dispatchShadowPath =
        QDir(retryDirectory).filePath(
            QStringLiteral("shadow-%1-prepared.bin")
                .arg(dispatch.lineageId));

    const auto pending = candidate.store->beginLocalCommit(
        *armed.snapshot, expected,
        verifiedUserArtifact(
            dispatch.retryRemoteName, dispatch.prepared.size));
    QVERIFY2(pending.ok(), qPrintable(pending.detail));
    QVERIFY(pending.snapshot.has_value());
    QVERIFY(pending.snapshot->retryCandidate.has_value());
    QCOMPARE(pending.snapshot->retryCandidate->operationId,
             candidateBefore.operationId);
    QVERIFY(pending.snapshot->inFlightDispatch.has_value());
    QCOMPARE(pending.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::
                 LocalCommitPending);

    const auto retired = candidate.store->retireDispatch(
        *pending.snapshot, expected,
        tryx::RetryCacheStore::DispatchRetirement::
            AcknowledgedSuccess);
    QVERIFY2(retired.ok(), qPrintable(retired.detail));
    QVERIFY(retired.snapshot.has_value());
    QVERIFY(retired.snapshot->retryCandidate.has_value());
    QVERIFY(!retired.snapshot->inFlightDispatch.has_value());
    QVERIFY(retired.snapshot->cleanupPending.isEmpty());
    QCOMPARE(retired.snapshot->retryCandidate->lineageId,
             candidateBefore.lineageId);
    QCOMPARE(retired.snapshot->retryCandidate->dispatchId,
             candidateBefore.dispatchId);
    QCOMPARE(retired.snapshot->retryCandidate->operationId,
             candidateBefore.operationId);
    QVERIFY(QFileInfo::exists(candidate.canonicalArtifactPath));
    QVERIFY(!QFileInfo::exists(dispatchCanonicalPath));
    QVERIFY(!QFileInfo::exists(dispatchShadowPath));
    QVERIFY(!QFileInfo(
                 QDir(retryDirectory).filePath(
                     QStringLiteral("suspended-v10")))
                 .exists());
    QFile restoredShadow(
        candidate.store->legacyShadowManifestPath());
    QVERIFY(restoredShadow.open(QIODevice::ReadOnly));
    QCOMPARE(restoredShadow.readAll(),
             candidate.shadowManifestBytes);
}

