void PrinterProtocolTests::
    retryCacheStoreDefersFinalizationLocalCommitAndRetries() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    const QByteArray preparedBytes(
        "finalization-local-commit-retry");
    ArmedSingleDispatchFixture fixture;
    QString detail;
    QVERIFY2(createArmedSingleDispatchFixture(
                 temporaryDirectory.path(), retryDirectory,
                 preparedBytes,
                 QStringLiteral("finalization-local-commit"),
                 &fixture, &detail),
             qPrintable(detail));
    tryx::RetryCacheStore::RetryableOutcomeInput uncertain;
    uncertain.outcome = tryx::RetryCacheStore::TerminalOutcome::
        FinalizationUnknown;
    uncertain.confirmedBytes = preparedBytes.size();
    uncertain.primaryErrorCategory =
        QStringLiteral("FinalizationUnknown");
    uncertain.primaryErrorMessage =
        QStringLiteral("FileList acknowledgement was lost");
    const auto recorded = fixture.store->recordRetryableOutcome(
        fixture.armedSnapshot, fixture.expected, uncertain);
    QVERIFY2(recorded.ok(), qPrintable(recorded.detail));
    QVERIFY(recorded.snapshot.has_value());
    QVERIFY(recorded.snapshot->retryCandidate.has_value());
    QVERIFY(!recorded.snapshot->inFlightDispatch.has_value());
    const auto finalizationCandidate =
        *recorded.snapshot->retryCandidate;
    QCOMPARE(finalizationCandidate.outcome,
             tryx::RetryCacheStore::TerminalOutcome::
                 FinalizationUnknown);
    QVERIFY(finalizationCandidate.requiresDeviceRecovery);
    QVERIFY(!finalizationCandidate.requiresNewRemoteName);
    QVERIFY(finalizationCandidate
                .finalizationOnlyReconciliation);

    const auto firstPending = fixture.store->beginLocalCommit(
        *recorded.snapshot, fixture.expected,
        verifiedUserArtifact(
            finalizationCandidate.retryRemoteName,
            finalizationCandidate.prepared.size));
    QVERIFY2(firstPending.ok(), qPrintable(firstPending.detail));
    QVERIFY(firstPending.snapshot.has_value());
    QVERIFY(!firstPending.snapshot->retryCandidate.has_value());
    QVERIFY(firstPending.snapshot->inFlightDispatch.has_value());
    QCOMPARE(firstPending.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::
                 LocalCommitPending);

    const auto deferred = fixture.store->deferLocalCommit(
        *firstPending.snapshot, fixture.expected,
        QStringLiteral("ThumbnailPersistenceFailed"),
        QStringLiteral("Local thumbnail commit failed"));
    QVERIFY2(deferred.ok(), qPrintable(deferred.detail));
    QVERIFY(deferred.snapshot.has_value());
    QVERIFY(deferred.snapshot->retryCandidate.has_value());
    QVERIFY(!deferred.snapshot->inFlightDispatch.has_value());
    QVERIFY(deferred.snapshot->cleanupPending.isEmpty());
    const auto deferredCandidate =
        *deferred.snapshot->retryCandidate;
    QCOMPARE(deferredCandidate.outcome,
             tryx::RetryCacheStore::TerminalOutcome::NotStarted);
    QCOMPARE(deferredCandidate.confirmedBytes, qint64{0});
    QCOMPARE(deferredCandidate.lastConfirmedChunkIndex,
             qint64{-1});
    QVERIFY(!deferredCandidate.requiresDeviceRecovery);
    QVERIFY(!deferredCandidate.requiresNewRemoteName);
    QVERIFY(!deferredCandidate
                 .finalizationOnlyReconciliation);
    QCOMPARE(deferredCandidate.lineageId,
             finalizationCandidate.lineageId);
    QCOMPARE(deferredCandidate.operationId,
             finalizationCandidate.operationId);
    QVERIFY(QFileInfo::exists(fixture.canonicalArtifactPath));
    QVERIFY(QFileInfo::exists(fixture.shadowArtifactPath));

    tryx::RetryCacheStore::RetryPreparedInput retry;
    retry.dispatchId = QUuid::createUuid().toString(
        QUuid::WithoutBraces);
    retry.operationId = QUuid::createUuid().toString(
        QUuid::WithoutBraces);
    retry.deviceIdentity = deferredCandidate.deviceIdentity;
    retry.deviceGeneration =
        deferredCandidate.deviceGeneration + 1;
    retry.retryRemoteName = deferredCandidate.retryRemoteName;
    const auto begun = fixture.store->beginRetry(
        *deferred.snapshot, retry);
    QVERIFY2(begun.ok(), qPrintable(begun.detail));
    QVERIFY(begun.snapshot.has_value());
    tryx::RetryCacheStore::ExpectedDispatch retryExpected;
    retryExpected.lineageId = deferredCandidate.lineageId;
    retryExpected.dispatchId = retry.dispatchId;
    retryExpected.operationId = retry.operationId;
    retryExpected.productId = deferredCandidate.productId;
    retryExpected.deviceIdentity = retry.deviceIdentity;
    retryExpected.deviceGeneration = retry.deviceGeneration;
    const auto rearmed = fixture.store->armDispatch(
        *begun.snapshot, retryExpected);
    QVERIFY2(rearmed.ok(), qPrintable(rearmed.detail));
    QVERIFY(rearmed.snapshot.has_value());
    const auto retryDispatch =
        *rearmed.snapshot->inFlightDispatch;
    const auto secondPending = fixture.store->beginLocalCommit(
        *rearmed.snapshot, retryExpected,
        verifiedUserArtifact(
            retryDispatch.retryRemoteName,
            retryDispatch.prepared.size));
    QVERIFY2(secondPending.ok(), qPrintable(secondPending.detail));
    QVERIFY(secondPending.snapshot.has_value());
    QCOMPARE(secondPending.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::
                 LocalCommitPending);

    const auto retired = fixture.store->retireDispatch(
        *secondPending.snapshot, retryExpected,
        tryx::RetryCacheStore::DispatchRetirement::
            AcknowledgedSuccess);
    QVERIFY2(retired.ok(), qPrintable(retired.detail));
    QVERIFY(retired.snapshot.has_value());
    QVERIFY(!retired.snapshot->retryCandidate.has_value());
    QVERIFY(!retired.snapshot->inFlightDispatch.has_value());
    QVERIFY(retired.snapshot->cleanupPending.isEmpty());
    QVERIFY(!QFileInfo::exists(fixture.canonicalArtifactPath));
    QVERIFY(!QFileInfo::exists(fixture.shadowArtifactPath));
}

