void PrinterProtocolTests::
    retryCacheStoreRestartsPendingLocalCommitAsCandidate() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    ArmedSingleDispatchFixture fixture;
    QString detail;
    QVERIFY2(createArmedSingleDispatchFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("restart-pending-local-commit"),
                 QStringLiteral("restart-local-commit"),
                 &fixture, &detail),
             qPrintable(detail));
    const auto dispatch =
        *fixture.armedSnapshot.inFlightDispatch;
    const auto pending = fixture.store->beginLocalCommit(
        fixture.armedSnapshot, fixture.expected,
        verifiedUserArtifact(
            dispatch.retryRemoteName, dispatch.prepared.size));
    QVERIFY2(pending.ok(), qPrintable(pending.detail));
    QVERIFY(pending.snapshot.has_value());
    QCOMPARE(pending.snapshot->inFlightDispatch->phase,
             tryx::RetryCacheStore::DispatchPhase::
                 LocalCommitPending);
    const quint64 pendingRevision =
        pending.snapshot->storeRevision;
    fixture.store.reset();

    tryx::RetryCacheStore restarted(retryDirectory);
    const auto loaded = restarted.load();
    QVERIFY2(loaded.status ==
                 tryx::RetryCacheStore::LoadStatus::
                     NeedsValidation,
             qPrintable(loaded.detail));
    QVERIFY(loaded.snapshot.has_value());
    QVERIFY(loaded.snapshot->retryCandidate.has_value());
    QVERIFY(!loaded.snapshot->inFlightDispatch.has_value());
    QVERIFY(!loaded.validationRequests.isEmpty());
    QCOMPARE(loaded.snapshot->storeRevision,
             pendingRevision + 1);
    const auto &pendingCandidate =
        *loaded.snapshot->retryCandidate;
    QCOMPARE(pendingCandidate.operationId,
             fixture.expected.operationId);
    QCOMPARE(pendingCandidate.outcome,
             tryx::RetryCacheStore::TerminalOutcome::NotStarted);
    QCOMPARE(pendingCandidate.confirmedBytes, qint64{0});
    QCOMPARE(pendingCandidate.lastConfirmedChunkIndex,
             qint64{-1});
    QVERIFY(!pendingCandidate.requiresDeviceRecovery);
    QVERIFY(!pendingCandidate.requiresNewRemoteName);
    QVERIFY(!pendingCandidate
                 .finalizationOnlyReconciliation);
    for (const auto &request : loaded.validationRequests) {
        QCOMPARE(request.lineageId, dispatch.lineageId);
        QCOMPARE(request.dispatchId, dispatch.dispatchId);
        QCOMPARE(request.operationId, dispatch.operationId);
    }

    tryx::RetryCacheStore::MutationResult validated;
    for (const auto &request : loaded.validationRequests) {
        tryx::RetryCacheStore::ValidationResult result;
        result.token = request.token;
        result.valid = true;
        result.actualSize = request.expectedSize;
        result.actualSha256 = request.expectedSha256;
        result.actualDevice = request.expectedDevice;
        result.actualInode = request.expectedInode;
        validated = restarted.completeValidation(result);
        QVERIFY2(validated.ok(), qPrintable(validated.detail));
    }
    QVERIFY(validated.snapshot.has_value());
    QVERIFY(validated.snapshot->retryCandidate.has_value());
    QVERIFY(!validated.snapshot->inFlightDispatch.has_value());
    QCOMPARE(validated.snapshot->retryCandidate->outcome,
             tryx::RetryCacheStore::TerminalOutcome::NotStarted);
    QVERIFY(!validated.snapshot->retryCandidate
                 ->requiresDeviceRecovery);
    QVERIFY(!validated.snapshot->retryCandidate
                 ->requiresNewRemoteName);
    QVERIFY(!validated.snapshot->retryCandidate
                 ->finalizationOnlyReconciliation);
    QVERIFY(!restarted.blocksMutations());
}

void PrinterProtocolTests::
    retryCacheStoreRecoversLocalCommitCanonicalCrash_data() {
    QTest::addColumn<QString>("topology");

    QTest::newRow("single-dispatch")
        << QStringLiteral("single");
    QTest::newRow("independent-candidate-and-dispatch")
        << QStringLiteral("independent");
    QTest::newRow("shared-retry-candidate")
        << QStringLiteral("shared");
}

void PrinterProtocolTests::
    retryCacheStoreRecoversLocalCommitCanonicalCrash() {
    QFETCH(QString, topology);

    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    std::unique_ptr<tryx::RetryCacheStore> store;
    tryx::RetryCacheStore::Snapshot armedSnapshot;
    tryx::RetryCacheStore::ExpectedDispatch expected;
    QString expectedCanonicalPath;
    QString supersededCandidatePath;
    QString detail;

    if (topology == QStringLiteral("single")) {
        ArmedSingleDispatchFixture fixture;
        QVERIFY2(createArmedSingleDispatchFixture(
                     temporaryDirectory.path(), retryDirectory,
                     QByteArray("single-local-commit-canonical-crash"),
                     QStringLiteral("single-canonical-crash"),
                     &fixture, &detail),
                 qPrintable(detail));
        armedSnapshot = fixture.armedSnapshot;
        expected = fixture.expected;
        expectedCanonicalPath = fixture.canonicalArtifactPath;
        store = std::move(fixture.store);
    } else if (topology == QStringLiteral("independent")) {
        RetryCandidateFixture candidate;
        QVERIFY2(createRetryCandidateFixture(
                     temporaryDirectory.path(), retryDirectory,
                     QByteArray("candidate-a-before-local-commit-crash"),
                     QStringLiteral("candidate-a-canonical-crash"),
                     &candidate, &detail),
                 qPrintable(detail));
        supersededCandidatePath = candidate.canonicalArtifactPath;
        const QByteArray dispatchBytes(
            "independent-b-local-commit-canonical-crash");
        const QString dispatchStaging =
            QDir(temporaryDirectory.path()).filePath(
                QStringLiteral("independent-b-canonical-crash.bin"));
        QVERIFY(writeAtomicOwnerFile(dispatchStaging, dispatchBytes));
        const auto dispatchInput = retryCachePreparedInput(
            dispatchStaging, dispatchBytes,
            QStringLiteral("independent-b-canonical-crash"));
        const auto persisted = candidate.store->persistPrepared(
            candidate.snapshot, dispatchInput);
        QVERIFY2(persisted.ok(), qPrintable(persisted.detail));
        QVERIFY(persisted.snapshot.has_value());
        expected.lineageId = dispatchInput.lineageId;
        expected.dispatchId = dispatchInput.dispatchId;
        expected.operationId = dispatchInput.operationId;
        expected.productId = dispatchInput.productId;
        expected.deviceIdentity = dispatchInput.deviceIdentity;
        expected.deviceGeneration = dispatchInput.deviceGeneration;
        const auto armed = candidate.store->armDispatch(
            *persisted.snapshot, expected);
        QVERIFY2(armed.ok(), qPrintable(armed.detail));
        QVERIFY(armed.snapshot.has_value());
        armedSnapshot = *armed.snapshot;
        expectedCanonicalPath =
            QDir(candidate.store->canonicalDirectory()).filePath(
                armedSnapshot.inFlightDispatch->prepared.name);
        store = std::move(candidate.store);
    } else if (topology == QStringLiteral("shared")) {
        ArmedSharedRetryFixture fixture;
        QVERIFY2(createArmedSharedRetryFixture(
                     temporaryDirectory.path(), retryDirectory,
                     QByteArray("shared-retry-local-commit-canonical-crash"),
                     QStringLiteral("shared-canonical-crash"),
                     &fixture, &detail),
                 qPrintable(detail));
        armedSnapshot = fixture.armedSnapshot;
        expected = fixture.expected;
        expectedCanonicalPath = fixture.candidate.canonicalArtifactPath;
        store = std::move(fixture.candidate.store);
    } else {
        QFAIL("Unknown local-commit canonical crash topology");
    }

    QVERIFY(store);
    QVERIFY(armedSnapshot.inFlightDispatch.has_value());
    const auto dispatch = *armedSnapshot.inFlightDispatch;
    store->setStopAfterLocalCommitCanonicalForTesting(true);
    const auto stopped = store->beginLocalCommit(
        armedSnapshot, expected,
        verifiedUserArtifact(
            dispatch.retryRemoteName, dispatch.prepared.size));
    QCOMPARE(stopped.code, tryx::RetryCacheStore::ErrorCode::IoError);
    QVERIFY(store->blocksMutations());
    QVERIFY(QFileInfo::exists(expectedCanonicalPath));

    QFile canonicalAfterStop(store->canonicalManifestPath());
    QVERIFY(canonicalAfterStop.open(QIODevice::ReadOnly));
    const QJsonObject stoppedManifest = QJsonDocument::fromJson(
        canonicalAfterStop.readAll()).object();
    const QJsonObject stoppedDispatch = stoppedManifest.value(
        QStringLiteral("inFlightDispatch")).toObject();
    QCOMPARE(stoppedDispatch.value(QStringLiteral("lineageId")).toString(),
             expected.lineageId);
    QCOMPARE(stoppedDispatch.value(QStringLiteral("dispatchId")).toString(),
             expected.dispatchId);
    QCOMPARE(stoppedDispatch.value(QStringLiteral("operationId")).toString(),
             expected.operationId);
    QCOMPARE(stoppedDispatch.value(QStringLiteral("phase")).toString(),
             QStringLiteral("LocalCommitPending"));
    canonicalAfterStop.close();
    store.reset();

    tryx::RetryCacheStore restarted(retryDirectory);
    const auto loaded = restarted.load();
    QVERIFY2(loaded.status ==
                 tryx::RetryCacheStore::LoadStatus::NeedsValidation,
             qPrintable(loaded.detail));
    QVERIFY(loaded.snapshot.has_value());
    QVERIFY(loaded.snapshot->retryCandidate.has_value());
    QVERIFY(!loaded.snapshot->inFlightDispatch.has_value());
    QVERIFY(loaded.snapshot->cleanupPending.isEmpty());
    QVERIFY(!loaded.snapshot->candidateTransition.has_value());
    QVERIFY(!loaded.validationRequests.isEmpty());
    const auto &candidate = *loaded.snapshot->retryCandidate;
    QCOMPARE(candidate.lineageId, expected.lineageId);
    QCOMPARE(candidate.dispatchId, expected.dispatchId);
    QCOMPARE(candidate.operationId, expected.operationId);
    QCOMPARE(candidate.productId, expected.productId);
    QCOMPARE(candidate.deviceIdentity, expected.deviceIdentity);
    QCOMPARE(candidate.deviceGeneration, expected.deviceGeneration);
    QCOMPARE(candidate.outcome,
             tryx::RetryCacheStore::TerminalOutcome::NotStarted);
    QCOMPARE(candidate.confirmedBytes, qint64{0});
    QCOMPARE(candidate.lastConfirmedChunkIndex, qint64{-1});
    QVERIFY(!candidate.requiresDeviceRecovery);
    QVERIFY(!candidate.requiresNewRemoteName);
    QVERIFY(!candidate.finalizationOnlyReconciliation);
    QVERIFY(QFileInfo::exists(expectedCanonicalPath));
    if (!supersededCandidatePath.isEmpty()) {
        QVERIFY(!QFileInfo::exists(supersededCandidatePath));
    }
    for (const auto &request : loaded.validationRequests) {
        QCOMPARE(request.lineageId, expected.lineageId);
        QCOMPARE(request.dispatchId, expected.dispatchId);
        QCOMPARE(request.operationId, expected.operationId);
    }

    tryx::RetryCacheStore::MutationResult validated;
    for (const auto &request : loaded.validationRequests) {
        tryx::RetryCacheStore::ValidationResult result;
        result.token = request.token;
        result.valid = true;
        result.actualSize = request.expectedSize;
        result.actualSha256 = request.expectedSha256;
        result.actualDevice = request.expectedDevice;
        result.actualInode = request.expectedInode;
        validated = restarted.completeValidation(result);
        QVERIFY2(validated.ok(), qPrintable(validated.detail));
    }
    QVERIFY(validated.snapshot.has_value());
    QVERIFY(validated.snapshot->retryCandidate.has_value());
    QVERIFY(!validated.snapshot->inFlightDispatch.has_value());
    QVERIFY(validated.snapshot->cleanupPending.isEmpty());
    QVERIFY(!validated.snapshot->candidateTransition.has_value());
    QCOMPARE(validated.snapshot->retryCandidate->lineageId,
             expected.lineageId);
    QCOMPARE(validated.snapshot->retryCandidate->dispatchId,
             expected.dispatchId);
    QCOMPARE(validated.snapshot->retryCandidate->operationId,
             expected.operationId);
    QCOMPARE(validated.snapshot->retryCandidate->outcome,
             tryx::RetryCacheStore::TerminalOutcome::NotStarted);
    QVERIFY(!restarted.blocksMutations());
}

