void PrinterProtocolTests::
    retryCacheStoreRejectsInvalidLocalCommitProof() {
    QFETCH(QString, scenario);
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    ArmedSingleDispatchFixture fixture;
    QString detail;
    QVERIFY2(createArmedSingleDispatchFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("invalid-local-commit-proof"),
                 QStringLiteral("invalid-local-proof"),
                 &fixture, &detail),
             qPrintable(detail));
    const auto dispatch =
        *fixture.armedSnapshot.inFlightDispatch;
    auto proof = verifiedUserArtifact(
        dispatch.retryRemoteName, dispatch.prepared.size);
    if (scenario == QStringLiteral("name")) {
        proof.remoteName = QStringLiteral(
            "different.mp4.h264_2240x1080");
    } else if (scenario == QStringLiteral("size")) {
        ++proof.size;
    } else if (scenario == QStringLiteral("source")) {
        proof.source =
            tryx::RetryCacheStore::RemoteArtifactSource::Preset;
    } else if (scenario == QStringLiteral("read-only")) {
        proof.readOnly = true;
    } else {
        QFAIL("Unknown invalid local-commit proof scenario");
    }
    QFile canonicalBeforeFile(
        fixture.store->canonicalManifestPath());
    QVERIFY(canonicalBeforeFile.open(QIODevice::ReadOnly));
    const QByteArray canonicalBefore =
        canonicalBeforeFile.readAll();
    QFile shadowBeforeFile(
        fixture.store->legacyShadowManifestPath());
    QVERIFY(shadowBeforeFile.open(QIODevice::ReadOnly));
    const QByteArray shadowBefore = shadowBeforeFile.readAll();

    const auto rejected = fixture.store->beginLocalCommit(
        fixture.armedSnapshot, fixture.expected, proof);
    QCOMPARE(rejected.code,
             tryx::RetryCacheStore::ErrorCode::Conflict);
    QVERIFY(!rejected.ok());
    QVERIFY(!rejected.snapshot.has_value());
    QVERIFY(!fixture.store->blocksMutations());
    QFile canonicalAfterFile(
        fixture.store->canonicalManifestPath());
    QVERIFY(canonicalAfterFile.open(QIODevice::ReadOnly));
    QCOMPARE(canonicalAfterFile.readAll(), canonicalBefore);
    QFile shadowAfterFile(
        fixture.store->legacyShadowManifestPath());
    QVERIFY(shadowAfterFile.open(QIODevice::ReadOnly));
    QCOMPARE(shadowAfterFile.readAll(), shadowBefore);
    QVERIFY(QFileInfo::exists(fixture.canonicalArtifactPath));
    QVERIFY(QFileInfo::exists(fixture.shadowArtifactPath));
}

