void PrinterProtocolTests::
    retryCacheStoreRejectsInexactProtectedTransitionIdentity() {
    QFETCH(QString, scenario);

    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    RetryCandidateFixture candidate;
    QString detail;
    QVERIFY2(createRetryCandidateFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("exact-transition-candidate-a"),
                 QStringLiteral("exact-transition-a"),
                 &candidate, &detail),
             qPrintable(detail));

    const QByteArray dispatchBytes("exact-transition-dispatch-b");
    const QString stagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("exact-transition-b.bin"));
    QVERIFY(writeAtomicOwnerFile(stagingPath, dispatchBytes));
    const auto dispatchInput = retryCachePreparedInput(
        stagingPath, dispatchBytes,
        QStringLiteral("exact-transition-b"));
    const auto prepared = candidate.store->persistPrepared(
        candidate.snapshot, dispatchInput);
    QVERIFY2(prepared.ok(), qPrintable(prepared.detail));
    QVERIFY(prepared.snapshot.has_value());
    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = dispatchInput.lineageId;
    expected.dispatchId = dispatchInput.dispatchId;
    expected.operationId = dispatchInput.operationId;
    expected.productId = dispatchInput.productId;
    expected.deviceIdentity = dispatchInput.deviceIdentity;
    expected.deviceGeneration = dispatchInput.deviceGeneration;
    const auto armed = candidate.store->armDispatch(
        *prepared.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));
    QVERIFY(armed.snapshot.has_value());
    const auto dispatch = *armed.snapshot->inFlightDispatch;

    const QString transitionStatePath =
        QDir(retryDirectory).filePath(
            QStringLiteral("suspended-v10/state.json"));
    QFile transitionStateFile(transitionStatePath);
    QVERIFY(transitionStateFile.open(QIODevice::ReadOnly));
    QJsonObject transitionState = QJsonDocument::fromJson(
        transitionStateFile.readAll()).object();
    transitionStateFile.close();
    QCOMPARE(transitionState
                 .value(QStringLiteral("dispatchDeviceIdentity"))
                 .toString(),
             dispatch.deviceIdentity);

    auto attemptedExpected = expected;
    if (scenario == QStringLiteral("whitespace")) {
        transitionState.insert(
            QStringLiteral("dispatchDeviceIdentity"),
            QStringLiteral(" %1 ").arg(dispatch.deviceIdentity));
        QVERIFY(writeAtomicOwnerFile(
            transitionStatePath,
            QJsonDocument(transitionState)
                .toJson(QJsonDocument::Compact)));
    } else if (scenario == QStringLiteral("dispatch-id")) {
        attemptedExpected.dispatchId =
            QUuid::createUuid().toString(QUuid::WithoutBraces);
    } else if (scenario == QStringLiteral("device-generation")) {
        ++attemptedExpected.deviceGeneration;
    } else {
        QFAIL("Unknown protected transition identity scenario");
    }

    const auto readAll = [](const QString &path) {
        QFile file(path);
        return file.open(QIODevice::ReadOnly)
            ? file.readAll()
            : QByteArray();
    };
    const QByteArray canonicalBefore = readAll(
        candidate.store->canonicalManifestPath());
    const QByteArray shadowBefore = readAll(
        candidate.store->legacyShadowManifestPath());
    const QByteArray transitionBefore = readAll(transitionStatePath);
    QVERIFY(!canonicalBefore.isEmpty());
    QVERIFY(!shadowBefore.isEmpty());
    QVERIFY(!transitionBefore.isEmpty());

    const auto rejected = candidate.store->beginLocalCommit(
        *armed.snapshot, attemptedExpected,
        verifiedUserArtifact(
            dispatch.retryRemoteName, dispatch.prepared.size));
    QCOMPARE(rejected.code,
             tryx::RetryCacheStore::ErrorCode::Conflict);
    QVERIFY(!rejected.snapshot.has_value());
    QCOMPARE(readAll(candidate.store->canonicalManifestPath()),
             canonicalBefore);
    QCOMPARE(readAll(candidate.store->legacyShadowManifestPath()),
             shadowBefore);
    QCOMPARE(readAll(transitionStatePath), transitionBefore);
}

