void PrinterProtocolTests::
    retryCacheStoreRejectsRestartedProtectedTransitionIdentityTamper() {
    QFETCH(QString, restartPath);
    QFETCH(QString, tamperKind);

    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    RetryCandidateFixture candidate;
    QString detail;
    QVERIFY2(createRetryCandidateFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("restart-transition-identity-candidate-a"),
                 QStringLiteral("restart-transition-identity-a"),
                 &candidate, &detail),
             qPrintable(detail));

    const QByteArray dispatchBytes(
        "restart-transition-identity-dispatch-b");
    const QString stagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("restart-transition-identity-b.bin"));
    QVERIFY(writeAtomicOwnerFile(stagingPath, dispatchBytes));
    const auto dispatchInput = retryCachePreparedInput(
        stagingPath, dispatchBytes,
        QStringLiteral("restart-transition-identity-b"));
    const auto prepared = candidate.store->persistPrepared(
        candidate.snapshot, dispatchInput);
    QVERIFY2(prepared.ok(), qPrintable(prepared.detail));
    QVERIFY(prepared.snapshot.has_value());
    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = dispatchInput.lineageId;
    expected.dispatchId = dispatchInput.dispatchId;
    expected.operationId = dispatchInput.operationId;
    expected.productId = dispatchInput.productId;
    expected.deviceIdentity = dispatchInput.deviceIdentity;
    expected.deviceGeneration = dispatchInput.deviceGeneration;
    const auto armed = candidate.store->armDispatch(
        *prepared.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));
    QVERIFY(armed.snapshot.has_value());
    const auto armedDispatch =
        *armed.snapshot->inFlightDispatch;

    if (restartPath == QStringLiteral("local-commit")) {
        candidate.store->setStopAfterLocalCommitCanonicalForTesting(
            true);
        const auto stopped = candidate.store->beginLocalCommit(
            *armed.snapshot, expected,
            verifiedUserArtifact(
                armedDispatch.retryRemoteName,
                armedDispatch.prepared.size));
        QCOMPARE(stopped.code,
                 tryx::RetryCacheStore::ErrorCode::IoError);
    } else if (restartPath == QStringLiteral("retirement")) {
        candidate.store->setStopAfterCleanupTombstoneForTesting(true);
        const auto stopped = candidate.store->retireDispatch(
            *armed.snapshot, expected,
            tryx::RetryCacheStore::DispatchRetirement::ProvenNotStarted);
        QCOMPARE(stopped.code,
                 tryx::RetryCacheStore::ErrorCode::IoError);
    } else if (restartPath != QStringLiteral("armed")) {
        QFAIL("Unknown protected transition restart path");
    }

    const QString canonicalPath =
        candidate.store->canonicalManifestPath();
    const QString rootPath =
        candidate.store->legacyShadowManifestPath();
    QFile canonicalFile(canonicalPath);
    QVERIFY(canonicalFile.open(QIODevice::ReadOnly));
    QJsonObject canonical = QJsonDocument::fromJson(
        canonicalFile.readAll()).object();
    canonicalFile.close();
    QJsonObject dispatch = canonical.value(
        QStringLiteral("inFlightDispatch")).toObject();
    QJsonObject protectedCandidate = canonical.value(
        QStringLiteral("retryCandidate")).toObject();
    QVERIFY(!protectedCandidate.isEmpty());
    QCOMPARE(dispatch.value(QStringLiteral("dispatchId")).toString(),
             expected.dispatchId);
    QCOMPARE(dispatch.value(QStringLiteral("deviceGeneration"))
                 .toString().toULongLong(),
             expected.deviceGeneration);

    QFile rootFile(rootPath);
    QVERIFY(rootFile.open(QIODevice::ReadOnly));
    QJsonObject root = QJsonDocument::fromJson(
        rootFile.readAll()).object();
    rootFile.close();
    const QString transitionStatePath =
        QDir(retryDirectory).filePath(
            QStringLiteral("suspended-v10/state.json"));
    QFile transitionBeforeFile(transitionStatePath);
    QVERIFY(transitionBeforeFile.open(QIODevice::ReadOnly));
    const QByteArray transitionBefore = transitionBeforeFile.readAll();
    transitionBeforeFile.close();
    candidate.store.reset();

    if (tamperKind ==
        QStringLiteral("dispatch-device-generation")) {
        const quint64 changedGeneration =
            expected.deviceGeneration + 1;
        dispatch.insert(QStringLiteral("deviceGeneration"),
                        QString::number(changedGeneration));
        root.insert(QStringLiteral("uploadDeviceGeneration"),
                    QString::number(changedGeneration));
        QVERIFY(writeAtomicOwnerFile(
            rootPath,
            QJsonDocument(root).toJson(QJsonDocument::Compact)));
    } else if (tamperKind == QStringLiteral("dispatch-operation-id")) {
        const QString changedOperationId =
            QStringLiteral("88888888-8888-4888-8888-888888888888");
        dispatch.insert(QStringLiteral("operationId"),
                        changedOperationId);
        root.insert(QStringLiteral("operationId"),
                    changedOperationId);
        QVERIFY(writeAtomicOwnerFile(
            rootPath,
            QJsonDocument(root).toJson(QJsonDocument::Compact)));
    } else if (tamperKind == QStringLiteral("candidate-dispatch-id")) {
        protectedCandidate.insert(
            QStringLiteral("dispatchId"),
            QStringLiteral("77777777-7777-4777-8777-777777777777"));
        canonical.insert(QStringLiteral("retryCandidate"),
                         protectedCandidate);
    } else if (tamperKind ==
               QStringLiteral("candidate-device-generation")) {
        protectedCandidate.insert(
            QStringLiteral("deviceGeneration"),
            QString::number(
                protectedCandidate
                    .value(QStringLiteral("deviceGeneration"))
                    .toString().toULongLong() + 1));
        canonical.insert(QStringLiteral("retryCandidate"),
                         protectedCandidate);
    } else if (tamperKind == QStringLiteral("dispatch-id")) {
        dispatch.insert(
            QStringLiteral("dispatchId"),
            QStringLiteral("99999999-9999-4999-8999-999999999999"));
    } else {
        QFAIL("Unknown protected transition tamper kind");
    }
    canonical.insert(QStringLiteral("inFlightDispatch"), dispatch);
    QVERIFY(writeAtomicOwnerFile(
        canonicalPath,
        QJsonDocument(canonical).toJson(QJsonDocument::Compact)));

    tryx::RetryCacheStore restarted(retryDirectory);
    const auto load = restarted.load();
    QCOMPARE(load.status, tryx::RetryCacheStore::LoadStatus::Conflict);
    QVERIFY(restarted.blocksMutations());
    QFile transitionAfterFile(transitionStatePath);
    QVERIFY(transitionAfterFile.open(QIODevice::ReadOnly));
    QCOMPARE(transitionAfterFile.readAll(), transitionBefore);
}

void PrinterProtocolTests::
    retryCacheStoreUpgradesLegacyProtectedTransitionIdentity() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    RetryCandidateFixture candidate;
    QString detail;
    QVERIFY2(createRetryCandidateFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("legacy-transition-identity-candidate-a"),
                 QStringLiteral("legacy-transition-identity-a"),
                 &candidate, &detail),
             qPrintable(detail));
    const auto protectedCandidate =
        *candidate.snapshot.retryCandidate;

    const QByteArray dispatchBytes(
        "legacy-transition-identity-dispatch-b");
    const QString stagingPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("legacy-transition-identity-b.bin"));
    QVERIFY(writeAtomicOwnerFile(stagingPath, dispatchBytes));
    const auto dispatchInput = retryCachePreparedInput(
        stagingPath, dispatchBytes,
        QStringLiteral("legacy-transition-identity-b"));
    const auto prepared = candidate.store->persistPrepared(
        candidate.snapshot, dispatchInput);
    QVERIFY2(prepared.ok(), qPrintable(prepared.detail));
    QVERIFY(prepared.snapshot.has_value());
    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = dispatchInput.lineageId;
    expected.dispatchId = dispatchInput.dispatchId;
    expected.operationId = dispatchInput.operationId;
    expected.productId = dispatchInput.productId;
    expected.deviceIdentity = dispatchInput.deviceIdentity;
    expected.deviceGeneration = dispatchInput.deviceGeneration;
    const auto armed = candidate.store->armDispatch(
        *prepared.snapshot, expected);
    QVERIFY2(armed.ok(), qPrintable(armed.detail));
    QVERIFY(armed.snapshot.has_value());

    const QString transitionStatePath =
        QDir(retryDirectory).filePath(
            QStringLiteral("suspended-v10/state.json"));
    QVERIFY(downgradeRetryTransitionStateToV1(retryDirectory));
    candidate.store.reset();

    tryx::RetryCacheStore restarted(retryDirectory);
    const auto load = restarted.load();
    QVERIFY2(load.status ==
                 tryx::RetryCacheStore::LoadStatus::NeedsValidation,
             qPrintable(load.detail));

    QFile upgradedFile(transitionStatePath);
    QVERIFY(upgradedFile.open(QIODevice::ReadOnly));
    const QJsonObject upgraded = QJsonDocument::fromJson(
        upgradedFile.readAll()).object();
    QCOMPARE(upgraded.value(QStringLiteral("version")).toInt(), 2);
    QCOMPARE(upgraded.value(QStringLiteral("dispatchId")).toString(),
             expected.dispatchId);
    QCOMPARE(upgraded
                 .value(QStringLiteral("dispatchDeviceGeneration"))
                 .toString().toULongLong(),
             expected.deviceGeneration);
    QCOMPARE(upgraded
                 .value(QStringLiteral("protectedDispatchId"))
                 .toString(),
             protectedCandidate.dispatchId);
    QCOMPARE(upgraded
                 .value(QStringLiteral("protectedDeviceGeneration"))
                 .toString().toULongLong(),
             protectedCandidate.deviceGeneration);

    tryx::RetryCacheTransitionStore durableTransition(retryDirectory);
    const auto durableLoad = durableTransition.inspect();
    QVERIFY2(durableLoad.code ==
                 tryx::RetryCacheTransitionStore::Code::Protected ||
                 durableLoad.code ==
                     tryx::RetryCacheTransitionStore::Code::CurrentPreserved,
             qPrintable(durableLoad.detail));
}

