void PrinterProtocolTests::
    retryCacheStoreRejectsSingleRetirementRevisionOverflow() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    RetryCandidateFixture fixture;
    QString detail;
    QVERIFY2(createRetryCandidateFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("single-retirement-overflow"),
                 QStringLiteral("single-overflow"),
                 &fixture, &detail),
             qPrintable(detail));

    QFile canonicalFile(fixture.store->canonicalManifestPath());
    QVERIFY(canonicalFile.open(QIODevice::ReadOnly));
    QJsonObject canonical = QJsonDocument::fromJson(
        canonicalFile.readAll()).object();
    canonicalFile.close();
    const quint64 nearMaximumRevision =
        std::numeric_limits<quint64>::max() - 4;
    canonical.insert(QStringLiteral("storeRevision"),
                     QString::number(nearMaximumRevision));
    QVERIFY(writeAtomicOwnerFile(
        fixture.store->canonicalManifestPath(),
        QJsonDocument(canonical).toJson(QJsonDocument::Compact)));

    tryx::RetryCacheStore highRevisionStore(retryDirectory);
    const auto loaded = highRevisionStore.load();
    QVERIFY2(loaded.status ==
                 tryx::RetryCacheStore::LoadStatus::NeedsValidation,
             qPrintable(loaded.detail));
    tryx::RetryCacheStore::MutationResult validated;
    for (const auto &request : loaded.validationRequests) {
        tryx::RetryCacheStore::ValidationResult result;
        result.token = request.token;
        result.valid = true;
        result.actualSize = request.expectedSize;
        result.actualSha256 = request.expectedSha256;
        result.actualDevice = request.expectedDevice;
        result.actualInode = request.expectedInode;
        validated = highRevisionStore.completeValidation(result);
        QVERIFY2(validated.ok(), qPrintable(validated.detail));
    }
    QVERIFY(validated.snapshot.has_value());
    QCOMPARE(validated.snapshot->storeRevision,
             nearMaximumRevision);
    const auto candidate = *validated.snapshot->retryCandidate;
    tryx::RetryCacheStore::ExpectedDispatch expected;
    expected.lineageId = candidate.lineageId;
    expected.dispatchId = candidate.dispatchId;
    expected.operationId = candidate.operationId;
    expected.productId = candidate.productId;
    expected.deviceIdentity = candidate.deviceIdentity;
    expected.deviceGeneration = candidate.deviceGeneration;

    QFile canonicalBeforeFile(
        highRevisionStore.canonicalManifestPath());
    QVERIFY(canonicalBeforeFile.open(QIODevice::ReadOnly));
    const QByteArray canonicalBefore = canonicalBeforeFile.readAll();
    QFile rootBeforeFile(
        highRevisionStore.legacyShadowManifestPath());
    QVERIFY(rootBeforeFile.open(QIODevice::ReadOnly));
    const QByteArray rootBefore = rootBeforeFile.readAll();
    struct stat canonicalIdentityBefore {};
    struct stat rootIdentityBefore {};
    struct stat artifactIdentityBefore {};
    QCOMPARE(::stat(
                 QFile::encodeName(
                     highRevisionStore.canonicalManifestPath())
                     .constData(),
                 &canonicalIdentityBefore),
             0);
    QCOMPARE(::stat(
                 QFile::encodeName(
                     highRevisionStore.legacyShadowManifestPath())
                     .constData(),
                 &rootIdentityBefore),
             0);
    QCOMPARE(::stat(
                 QFile::encodeName(fixture.canonicalArtifactPath)
                     .constData(),
                 &artifactIdentityBefore),
             0);

    const auto rejected = highRevisionStore.clearCandidate(
        *validated.snapshot, expected);
    QCOMPARE(rejected.code,
             tryx::RetryCacheStore::ErrorCode::Conflict);
    QVERIFY(!QFileInfo(
                 QDir(retryDirectory).filePath(
                     QStringLiteral("suspended-v10")))
                 .exists());
    QFile canonicalAfterFile(
        highRevisionStore.canonicalManifestPath());
    QVERIFY(canonicalAfterFile.open(QIODevice::ReadOnly));
    QCOMPARE(canonicalAfterFile.readAll(), canonicalBefore);
    QFile rootAfterFile(
        highRevisionStore.legacyShadowManifestPath());
    QVERIFY(rootAfterFile.open(QIODevice::ReadOnly));
    QCOMPARE(rootAfterFile.readAll(), rootBefore);
    struct stat canonicalIdentityAfter {};
    struct stat rootIdentityAfter {};
    struct stat artifactIdentityAfter {};
    QCOMPARE(::stat(
                 QFile::encodeName(
                     highRevisionStore.canonicalManifestPath())
                     .constData(),
                 &canonicalIdentityAfter),
             0);
    QCOMPARE(::stat(
                 QFile::encodeName(
                     highRevisionStore.legacyShadowManifestPath())
                     .constData(),
                 &rootIdentityAfter),
             0);
    QCOMPARE(::stat(
                 QFile::encodeName(fixture.canonicalArtifactPath)
                     .constData(),
                 &artifactIdentityAfter),
             0);
    QCOMPARE(canonicalIdentityAfter.st_dev,
             canonicalIdentityBefore.st_dev);
    QCOMPARE(canonicalIdentityAfter.st_ino,
             canonicalIdentityBefore.st_ino);
    QCOMPARE(rootIdentityAfter.st_dev, rootIdentityBefore.st_dev);
    QCOMPARE(rootIdentityAfter.st_ino, rootIdentityBefore.st_ino);
    QCOMPARE(artifactIdentityAfter.st_dev,
             artifactIdentityBefore.st_dev);
    QCOMPARE(artifactIdentityAfter.st_ino,
             artifactIdentityBefore.st_ino);
    QCOMPARE(artifactIdentityAfter.st_nlink,
             artifactIdentityBefore.st_nlink);
}

