void PrinterProtocolTests::
    retryCacheStoreRejectsSingleShadowFenceRevisionOverflow() {
    QFETCH(quint64, storeRevision);
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString retryDirectory =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("prepared-media"));
    ArmedSingleDispatchFixture fixture;
    QString detail;
    QVERIFY2(createArmedSingleDispatchFixture(
                 temporaryDirectory.path(), retryDirectory,
                 QByteArray("single-fence-overflow-artifact"),
                 QStringLiteral("single-fence-overflow"),
                 &fixture, &detail),
             qPrintable(detail));
    QVERIFY(QFile::remove(
        fixture.store->legacyShadowManifestPath()));
    QVERIFY(QFile::remove(fixture.shadowArtifactPath));
    fixture.store.reset();

    {
        tryx::RetryCacheStore fencingStore(retryDirectory);
        const auto fenced = fencingStore.load();
        QVERIFY2(fenced.status ==
                     tryx::RetryCacheStore::LoadStatus::Loaded,
                 qPrintable(fenced.detail));
        QVERIFY(fenced.snapshot.has_value());
        QCOMPARE(fenced.snapshot->inFlightDispatch->phase,
                 tryx::RetryCacheStore::DispatchPhase::
                     ShadowMissingFence);
    }

    const QString canonicalManifestPath =
        QDir(retryDirectory).filePath(
            QStringLiteral("v11/retry-manifest.json"));
    QFile canonicalFile(canonicalManifestPath);
    QVERIFY(canonicalFile.open(QIODevice::ReadOnly));
    QJsonObject canonical = QJsonDocument::fromJson(
        canonicalFile.readAll()).object();
    canonicalFile.close();
    canonical.insert(
        QStringLiteral("storeRevision"),
        QString::number(storeRevision));
    QVERIFY(writeAtomicOwnerFile(
        canonicalManifestPath,
        QJsonDocument(canonical).toJson(QJsonDocument::Compact)));

    tryx::RetryCacheStore highRevisionStore(retryDirectory);
    const auto loaded = highRevisionStore.load();
    QVERIFY2(loaded.status ==
                 tryx::RetryCacheStore::LoadStatus::Loaded,
             qPrintable(loaded.detail));
    QVERIFY(loaded.snapshot.has_value());
    QCOMPARE(loaded.snapshot->storeRevision, storeRevision);

    QFile beforeFile(canonicalManifestPath);
    QVERIFY(beforeFile.open(QIODevice::ReadOnly));
    const QByteArray canonicalBefore = beforeFile.readAll();
    struct stat artifactBefore {};
    QCOMPARE(::stat(
                 QFile::encodeName(fixture.canonicalArtifactPath)
                     .constData(),
                 &artifactBefore),
             0);

    const auto rejected = highRevisionStore.resolveShadowMissingFence(
        *loaded.snapshot, fixture.expected,
        tryx::RetryCacheStore::RecoveryFenceProof::
            PhysicalReconnectObserved);
    QCOMPARE(rejected.code,
             tryx::RetryCacheStore::ErrorCode::Conflict);
    QVERIFY(!highRevisionStore.blocksMutations());
    QVERIFY(!QFileInfo::exists(
        highRevisionStore.legacyShadowManifestPath()));
    QVERIFY(!QFileInfo::exists(fixture.shadowArtifactPath));
    QVERIFY(!QFileInfo(
                 QDir(retryDirectory).filePath(
                     QStringLiteral("suspended-v10")))
                 .exists());

    QFile afterFile(canonicalManifestPath);
    QVERIFY(afterFile.open(QIODevice::ReadOnly));
    QCOMPARE(afterFile.readAll(), canonicalBefore);
    struct stat artifactAfter {};
    QCOMPARE(::stat(
                 QFile::encodeName(fixture.canonicalArtifactPath)
                     .constData(),
                 &artifactAfter),
             0);
    QCOMPARE(artifactAfter.st_dev, artifactBefore.st_dev);
    QCOMPARE(artifactAfter.st_ino, artifactBefore.st_ino);
    QCOMPARE(artifactAfter.st_nlink, artifactBefore.st_nlink);
}

