void PrinterProtocolTests::
    retryCacheArtifactValidationReturnsActualReplacementIdentity() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString artifactPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("expected-artifact.bin"));
    const QString originalPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("original-artifact.bin"));
    const QString replacementPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("same-content-replacement.bin"));
    const QByteArray artifactBytes(
        "same-content-different-inode");
    QVERIFY(writeAtomicOwnerFile(artifactPath, artifactBytes));
    QVERIFY(writeAtomicOwnerFile(replacementPath, artifactBytes));
    struct stat expectedIdentity {};
    QCOMPARE(::stat(
                 QFile::encodeName(artifactPath).constData(),
                 &expectedIdentity),
             0);
    QVERIFY(QFile::rename(artifactPath, originalPath));
    QVERIFY(QFile::rename(replacementPath, artifactPath));
    struct stat replacementIdentity {};
    QCOMPARE(::stat(
                 QFile::encodeName(artifactPath).constData(),
                 &replacementIdentity),
             0);
    QVERIFY(expectedIdentity.st_dev != replacementIdentity.st_dev ||
            expectedIdentity.st_ino != replacementIdentity.st_ino);

    PrinterMediaPreparer preparer;
    QSignalSpy validationSpy(
        &preparer,
        &PrinterMediaPreparer::retryCacheArtifactValidated);
    const QString token =
        QStringLiteral("76767676-7676-4676-8676-767676767676");
    preparer.validateRetryCacheArtifact(
        token, artifactPath, artifactBytes.size(),
        QString::fromLatin1(
            QCryptographicHash::hash(
                artifactBytes, QCryptographicHash::Sha256).toHex()),
        static_cast<quint64>(expectedIdentity.st_dev),
        static_cast<quint64>(expectedIdentity.st_ino));

    QCOMPARE(validationSpy.count(), 1);
    const auto arguments = validationSpy.takeFirst();
    QCOMPARE(arguments.at(1).toBool(), false);
    QCOMPARE(arguments.at(2).toBool(), false);
    QCOMPARE(arguments.at(5).toULongLong(),
             static_cast<quint64>(replacementIdentity.st_dev));
    QCOMPARE(arguments.at(6).toULongLong(),
             static_cast<quint64>(replacementIdentity.st_ino));
    QVERIFY(arguments.at(5).toULongLong() !=
                static_cast<quint64>(expectedIdentity.st_dev) ||
            arguments.at(6).toULongLong() !=
                static_cast<quint64>(expectedIdentity.st_ino));
}

void PrinterProtocolTests::
    retryCacheArtifactHashRejectsPathReplacementAfterOpen() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString artifactPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("pinned-artifact.bin"));
    const QString displacedPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("displaced-artifact.bin"));
    const QString replacementPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("replacement-artifact.bin"));
    const QByteArray originalBytes(512 * 1024, '\x31');
    const QByteArray replacementBytes = originalBytes;
    QVERIFY(writeAtomicOwnerFile(artifactPath, originalBytes));
    QVERIFY(writeAtomicOwnerFile(replacementPath, replacementBytes));
    struct stat originalIdentity {};
    QCOMPARE(::stat(
                 QFile::encodeName(artifactPath).constData(),
                 &originalIdentity),
             0);
    int cancellationChecks = 0;
    bool replaced = false;
    const auto result =
        tryx::printer_media_file_integrity::
            hashPrivateRegularFile(
                artifactPath, originalBytes.size(), [&]() {
                    ++cancellationChecks;
                    if (cancellationChecks == 2) {
                        replaced = QFile::rename(
                                       artifactPath,
                                       displacedPath) &&
                            QFile::rename(
                                       replacementPath,
                                       artifactPath);
                    }
                    return false;
                });
    QVERIFY(replaced);
    QVERIFY(!result.cancelled);
    QVERIFY(result.sha256.isEmpty());
    QVERIFY(!result.error.isEmpty());
    struct stat currentIdentity {};
    QCOMPARE(::stat(
                 QFile::encodeName(artifactPath).constData(),
                 &currentIdentity),
             0);
    QVERIFY(static_cast<quint64>(originalIdentity.st_dev) !=
                static_cast<quint64>(currentIdentity.st_dev) ||
            static_cast<quint64>(originalIdentity.st_ino) !=
                static_cast<quint64>(currentIdentity.st_ino));
}

void PrinterProtocolTests::
    retryCacheArtifactHashHonorsMidReadCancellation() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString artifactPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("mid-read-cancel.bin"));
    const QByteArray artifactBytes(1024 * 1024, '\x41');
    QVERIFY(writeAtomicOwnerFile(artifactPath, artifactBytes));
    int cancellationChecks = 0;
    const auto result =
        tryx::printer_media_file_integrity::
            hashPrivateRegularFile(
                artifactPath, artifactBytes.size(), [&]() {
                    ++cancellationChecks;
                    return cancellationChecks >= 3;
                });
    QVERIFY(result.cancelled);
    QVERIFY(result.sha256.isEmpty());
    QVERIFY(result.error.isEmpty());
    QVERIFY(cancellationChecks >= 3);
}

void PrinterProtocolTests::
    retryCacheArtifactHashRejectsInPlaceMutation() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString artifactPath =
        QDir(temporaryDirectory.path()).filePath(
            QStringLiteral("in-place-mutation.bin"));
    const QByteArray artifactBytes(512 * 1024, '\x51');
    QVERIFY(writeAtomicOwnerFile(artifactPath, artifactBytes));
    int cancellationChecks = 0;
    bool mutated = false;
    const auto result =
        tryx::printer_media_file_integrity::
            hashPrivateRegularFile(
                artifactPath, artifactBytes.size(), [&]() {
                    ++cancellationChecks;
                    if (cancellationChecks == 2) {
                        QFile file(artifactPath);
                        if (file.open(QIODevice::ReadWrite) &&
                            file.seek(0) &&
                            file.write(QByteArrayLiteral("Z")) == 1 &&
                            file.flush()) {
                            mutated = true;
                        }
                    }
                    return false;
                });
    QVERIFY(mutated);
    QVERIFY(!result.cancelled);
    QVERIFY(result.sha256.isEmpty());
    QVERIFY(!result.error.isEmpty());
}

void PrinterProtocolTests::retryCancellationRetainsOwnershipOnManifestRemovalFailure() {
    QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString sysRoot =
        QDir(temporaryDirectory.path()).filePath(QStringLiteral("sys"));
    const QString devRoot =
        QDir(temporaryDirectory.path()).filePath(QStringLiteral("dev"));
    QVERIFY(createUsbDevice(sysRoot, QStringLiteral("1-1"), "1021"));
    QVERIFY(createPrinterEndpoint(sysRoot, devRoot,
                                  QStringLiteral("1-1"),
                                  QStringLiteral("lp0")));

    std::unique_ptr<DeviceManager> manager(
        DeviceManager::createForTesting(sysRoot, devRoot));
    QObject::disconnect(
        manager.get(), &DeviceManager::requestStartPrinterSession,
        manager->worker_, &DeviceWorker::startPrinterDisplaySession);
    manager->setAutoConnectModeForTesting(true);
    manager->rescanPrinterForTesting();
    QVERIFY(manager->isPrinterClassConnected());
    manager->sessionController_.state_.printerDisplaySessionActive = true;

    const QString preparedPath = QDir(temporaryDirectory.path())
        .filePath(QStringLiteral("retained.h264"));
    const QByteArray preparedBytes(4096, '\x41');
    QVERIFY(writeAtomicOwnerFile(preparedPath, preparedBytes));

    const QString operationId =
        QStringLiteral("31313131-3131-4131-8131-313131313131");
    PrinterOperationCoordinator::OperationRecord record;
    record.printerProductId = 0x1021;
    record.info.id = operationId;
    record.info.kind = QStringLiteral("Upload");
    record.info.state = QStringLiteral("Preflight");
    record.info.stage = QStringLiteral("EnsuringSession");
    record.info.subject = QStringLiteral("retained.mp4");
    record.info.total = preparedBytes.size();
    record.info.deviceGeneration = manager->sessionController_.state_.printerGeneration;
    record.preparedPath = preparedPath;
    record.preparedSha256 = QString::fromLatin1(
        QCryptographicHash::hash(preparedBytes,
                                 QCryptographicHash::Sha256)
            .toHex());
    record.remoteName =
        QStringLiteral("retained.mp4.h264_2240x1080");
    record.originalRemoteName = record.remoteName;
    record.uploadDeviceIdentity =
        manager->sessionController_.state_.printerDeviceSerial.trimmed();
    record.uploadDeviceGeneration = manager->sessionController_.state_.printerGeneration;
    manager->operationCoordinator_.operations_.insert(operationId, record);
    manager->operationCoordinator_.operationOrder_.append(operationId);
    manager->operationCoordinator_.activeOperationId_ = operationId;

    QString canonicalPreparedPath;
    QVERIFY2(armRetryCacheDispatchForTesting(
                 manager.get(), operationId,
                 &canonicalPreparedPath),
             qPrintable(manager->operationInfo(operationId).message));
    TryxRuntimeMediaEntry verified;
    verified.name = record.remoteName;
    verified.size = preparedBytes.size();
    verified.source = 1U;
    verified.readOnly = false;
    QString storeError;
    QVERIFY2(manager->operationCoordinator_.beginRetryCacheLocalCommit(
                 operationId, verified, &storeError),
             qPrintable(storeError));
    QVERIFY2(manager->operationCoordinator_.deferRetryCacheLocalCommit(
                 manager->operationContext(), operationId,
                 QStringLiteral("LocalMediaCommitFailed"),
                 QStringLiteral("injected local commit failure"),
                 &storeError),
             qPrintable(storeError));
    auto retryRecord = manager->operationCoordinator_.operations_.find(operationId);
    QVERIFY(retryRecord != manager->operationCoordinator_.operations_.end());
    retryRecord->info.terminalOutcome = QStringLiteral("NotStarted");
    manager->operationCoordinator_.finishOperation(
        operationId, QStringLiteral("RetryAvailable"),
        QStringLiteral("LocalMediaCommitFailed"),
        QStringLiteral("PreparedMedia"),
        QStringLiteral("injected local commit failure"));
    QVERIFY(manager->operationCoordinator_.retryCacheSnapshot_.retryCandidate.has_value());
    const QString lineageId =
        manager->operationCoordinator_.retryCacheSnapshot_.retryCandidate->lineageId;
    const QString shadowPreparedPath =
        QDir(manager->operationCoordinator_.retryCacheDirectory()).filePath(
            QStringLiteral("shadow-%1-prepared.bin")
                .arg(lineageId));
    QVERIFY(QFileInfo::exists(canonicalPreparedPath));
    QVERIFY(QFileInfo::exists(shadowPreparedPath));

    QSignalSpy uploadSpy(
        manager.get(), &DeviceManager::requestPrinterUploadPrepared);
    manager->operationCoordinator_.retryCacheStore()
        .setStopAfterRetirementTombstoneForTesting(true);
    manager->cancelOperation(operationId);

    QCOMPARE(manager->operationInfo(operationId).state,
             QStringLiteral("Cancelled"));
    QCOMPARE(manager->operationInfo(operationId).terminalOutcome,
             QStringLiteral("Cancelled"));
    QCOMPARE(manager->operationInfo(operationId).errorCategory,
             QStringLiteral("RetryCacheCleanupFailed"));
    QVERIFY(manager->operationInfo(operationId).retryMode.isEmpty());
    QVERIFY(manager->operationInfo(operationId).message.contains(
        QStringLiteral("cleanup"), Qt::CaseInsensitive));
    QVERIFY(!manager->operationCoordinator_.retryCacheSnapshot_.retryCandidate.has_value());
    QVERIFY(!manager->operationCoordinator_.retryCacheSnapshot_.inFlightDispatch.has_value());
    QVERIFY(!manager->operationCoordinator_.retryCacheSnapshot_.cleanupPending.isEmpty());
    QVERIFY(manager->operationCoordinator_.retryCacheStore().blocksMutations());
    QVERIFY(manager->retryCacheMutationGateActive());
    QVERIFY(QFileInfo::exists(canonicalPreparedPath));
    QVERIFY(QFileInfo::exists(shadowPreparedPath));
    QVERIFY(QFileInfo(
                QDir(manager->operationCoordinator_.retryCacheDirectory()).filePath(
                    QStringLiteral("suspended-v10")))
                .isDir());
    QVERIFY(!QFileInfo::exists(
        manager->operationCoordinator_.retryCacheStore().legacyShadowManifestPath()));

    QFile tombstone(
        manager->operationCoordinator_.retryCacheStore().canonicalManifestPath());
    QVERIFY(tombstone.open(QIODevice::ReadOnly));
    const QJsonObject tombstoneObject =
        QJsonDocument::fromJson(tombstone.readAll()).object();
    QVERIFY(tombstoneObject
                .value(QStringLiteral("cleanupPending"))
                .isArray());
    QVERIFY(!tombstoneObject
                 .value(QStringLiteral("cleanupPending"))
                 .toArray()
                 .isEmpty());
    QVERIFY(!tombstoneObject.contains(
        QStringLiteral("retryCandidate")));
    QVERIFY(!tombstoneObject.contains(
        QStringLiteral("inFlightDispatch")));

    const QString rejectedRetryId =
        QStringLiteral("36363636-3636-4636-8636-363636363636");
    QCOMPARE(manager->retryOperation(operationId, rejectedRetryId),
             rejectedRetryId);
    QCOMPARE(manager->operationInfo(rejectedRetryId).errorCategory,
             QStringLiteral("RetryCacheConflict"));
    QCOMPARE(uploadSpy.count(), 0);

    const QString retryDirectory = manager->operationCoordinator_.retryCacheDirectory();
    manager.reset();
    {
        tryx::RetryCacheStore blocked(retryDirectory);
        blocked.setCleanupRootSyncFailureForTesting(true);
        const auto failedLoad = blocked.load();
        QCOMPARE(failedLoad.status,
                 tryx::RetryCacheStore::LoadStatus::ReadFailed);
        QVERIFY(blocked.blocksMutations());
        QVERIFY(QFileInfo::exists(canonicalPreparedPath));
        QVERIFY(QFileInfo::exists(shadowPreparedPath));
    }

    tryx::RetryCacheStore resumed(retryDirectory);
    const auto resumedLoad = resumed.load();
    QVERIFY2(resumedLoad.status ==
                 tryx::RetryCacheStore::LoadStatus::Loaded,
             qPrintable(resumedLoad.detail));
    QVERIFY(resumedLoad.snapshot.has_value());
    QVERIFY(!resumedLoad.snapshot->retryCandidate.has_value());
    QVERIFY(!resumedLoad.snapshot->inFlightDispatch.has_value());
    QVERIFY(resumedLoad.snapshot->cleanupPending.isEmpty());
    QVERIFY(!QFileInfo::exists(canonicalPreparedPath));
    QVERIFY(!QFileInfo::exists(shadowPreparedPath));
    QVERIFY(!QFileInfo::exists(
        QDir(retryDirectory).filePath(
            QStringLiteral("suspended-v10"))));
}

